window.__LEX={"G5200":"<h1>hugros</h1>\n<p>Strong n° 5200 <i>Prononciation [hoo-gros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>humide, moite, mouillé</li>\n<li>plein de sève, vert</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑγρός, ά, όν :<br>   I</b> mouillé, <i>d’où :</i><br><b>      1</b> humide : γῆ ὑγρά, XÉN. <i>Œc. 19, 6,</i> pays humide ; <i>mais</i> ὑγρ. βλέμμα, ANACR. <i>28, 21,</i> regard mouillé, langoureux, voluptueux ; ὑγρὰ δέρκεσθαι, ANTH. <i>7, 27 ;</i> A. PL. <i>306,</i> avoir un regard langoureux, regarder avec des yeux langoureux ; ὑγρὸς πόθος, HH. <i>18, 33,</i> désir langoureux, voluptueux ; ὑγρὸν δέος, ARCHIL. <i>69, 4,</i> peur qui fait couler une sueur froide ;<br><b>      2</b> pluvieux : ἄνεμοι ὑγρὸν ἀέντες, OD. <i>5, 478 ; 19, 440, etc</i>. vents qui soufflent l’humidité, vents pluvieux ; ὑγρὰ νύξ, PLAT. <i>Criti. 112</i> a, nuit humide <i>ou</i> pluvieuse ;<br><b>      3</b> humide, mouillé, liquide, qui coule : ἔλαιον, IL. <i>23, 281 ;</i> OD. <i>6, 79,</i> huile d’olive liquide, <i>p. opp. à</i> la graisse solide des animaux ; ὑγρὸν ὕδωρ, OD. <i>4, 458,</i> eau qui coule <i>ou</i> glisse dans la main ; <i>en parl. de la mer,</i> PD. <i>O. 7, 126, etc. ;</i> ESCHL. <i>Suppl. 259 ;</i> ὑγρὰ κέλευθα, IL. <i>1, 312 ;</i> OD. <i>3, 71 ; 9, 252,</i> les chemins liquides, <i>etc. càd</i>. la mer ; ὑγρὰ ῥέεθρα, SOPH. <i>Ant. 1123,</i> eaux courantes ; ὑγρὰ κύματα, EUR. <i>I.A. 948,</i> flots humides ; <i>cf</i>. PLAT. <i>Tim. 43</i> c ; ὑγρὸν δάκρυ, EUR. <i>Ion 1369,</i> larme qui coule ; ὑγρ. αἰθήρ, PD. <i>N. 8, 41 ;</i> EUR. <i>Ion 796,</i> l’air fluide ; <i>subst</i>. ἡ ὑγρά, <i>ion</i>. ὑγρή, l’humidité, la fluidité, HIPP. <i>684, 50 ; particul</i>. la plaine liquide, la mer, <i>p. opp. à</i> τραφερή <i>ou</i> γαῖα, IL. <i>10, 27 ; 14, 308 ; 24, 341 ;</i> OD. <i>5, 45 ; 20, 98 ;</i> AR. <i>Vesp. 678, etc. ;</i> τὸ ὑγρόν, l’humidité, la fluidité, HDT. <i>4, 172 ;</i> XÉN. <i>Cyr. 8, 8, 8 ;</i> PLAT. <i>Phæd. 112</i> b, <i>etc. ;</i> γῆ ὑγρῷ φυραθεῖσα, PLAT. <i>Theæt. 147</i> c, terre pétrie avec de l’eau ; ἔξω τοῦ ὑγροῦ ζῆν, ATH. <i>312</i> b, vivre hors de l’eau ; ἐφ' ὑγροῖς ζωγραφεῖν, PLUT. <i>M. 759</i> c, peindre à fresque ;<br><b>   II</b> qui concerne l’humidité, la fluidité <i>ou</i> l’eau : ὑγροὶ θῆρες, ANTH. <i>9, 18,</i> animaux aquatiques, <i>p. opp. à</i> πεζοί ; ὑγρὰ μέτρα, PLAT. <i>Leg. 746</i> d, mesures pour les liquides, <i>p. opp. à</i> ξηρά ;<br><b>   III</b> <i>p. anal. :</i><br><b>      1</b> mou, flottant, flasque, XÉN. <i>Cyn. 4, 1 ;</i> BABR. <i>1, 10 ; en parl. d’enfants, d’animaux nouveau-nés,</i> tendre, délicat, NONN. <i>D. 1, 4 ;</i> EL. <i>N.A. 7, 9 ;</i><br><b>      2</b> ivre, enivré : ὑγρὴν τὴν ψυχὴν ἔχειν, HÉRACLITE ÉPH. <i>fr. 117</i> (STOB. <i>Fl. 5, 120</i>), avoir l’âme enivrée ; <i>cf</i>. PLUT. <i>M. 713</i> a, <i>etc. ;</i><br><b>      3</b> coulant, onduleux, replié en forme de vagues, <i>en parl. du dos,</i> PD. <i>P. 1, 17 ; du cou,</i> PHILSTR. <i>Im. 12, p. 883 ; d’un arc,</i> THCR. <i>Idyl. 25, 206, etc. ;</i><br><b>      4</b> <i>p. suite,</i> mou, flexible, souple, mobile, <i>en parl. des mouvements du corps,</i> ARSTT. <i>P.A. 2, 9 ;</i> ὑγρὸν σῶμα, XÉN. <i>Eq. 7, 7,</i> corps souple ; ὑγρὰ ἔχειν τὰ σκέλη, XÉN. <i>Eq. 1, 6, en parl. d’un cheval,</i> avoir les jambes souples, <i>p. opp. à</i> σκληρά ; σῶμα ὑγρὸν κείμενον, HPC. <i>37, 37,</i> corps étendu sans être trop allongé ni trop ramassé ; <i>fig. en parl. d’un ambitieux,</i> PLUT. <i>Mar. 28 ; d’un flatteur,</i> PLUT. <i>M. 51</i> b ; <i>d’un jeune homme,</i> PLAT. <i>Theæt. 162</i> b ; <i>de la jeunesse,</i> PLUT. <i>M. 3</i> e ; <i>en parl. du style,</i> style insinuant, LGN <i>34, 3 ;</i> DH. <i>Dem. 20 ;</i><br><b>      5</b> facilement enclin à, <i>avec le dat. :</i> ὑγρὸς τῷ γελοίῳ, PLUT. <i>Brut. 19,</i> enclin à donner des ridicules ; <i>avec</i> ἐς <i>et l’acc</i>. APP. <i>Civ. 5, 8 ;</i><br><b>      6</b> vacillant, flasque, PLUT. <i>M. 321</i> e ; ὑγρὸς ἀγκών, SOPH. <i>Ant. 1236 ;</i> χεῖρ' ὑγρά, EUR. <i>Ph. 1448,</i> bras défaillant, main faible ;<br><b>      7</b> mou, efféminé, sensuel, AR. <i>Vesp. 1208 ;</i> PLUT. <i>M. 751</i> a, <i>etc. ;</i><br><b>      8</b> <i>t. de gr. en parl. des voyelles,</i> fluide, <i>càd</i>. commune, longue <i>ou</i> brève, SEXT. <i>M. 1, 100</i>.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Œc. 19, 6 ;</i> PLAT. <i>Theæt. 162</i> b ; ARSTT. <i>P.A. 2, 9 ;</i> ANTH. <i>5, 60 ;</i> PLUT. <i>Brut. 29 ;</i> EL. <i>V.H. 14, 7 ;</i> <i>• Sup</i>. -ότατος, XÉN. <i>Eq. 7, 7 ;</i> APP. <i>Civ. 5, 8</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ug<sup>w</sup>-ro-, humide ; <i>cf. lat</i>. ūvidus, ūdus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υγρος - ὑγρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5201":"<h1>hudria</h1>\n<p>Strong n° 5201 <i>Prononciation [hoo-dree-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un vase pour mettre de l'eau</li>\n<li>une jarre à eau, un pot à eau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑδρία, ας (ἡ) :<br>   I</b> vase pour puiser, contenir <i>ou</i> verser de l’eau, AR. <i>Vesp. 926, Eccl. 678 ;</i> ATH. <i>199</i> d ;<br><b>   II</b> <i>p. ext</i>. vase, <i>en gén. :</i><br><b>      1</b> pot pour le vin, AR. <i>fr. 183 ;</i><br><b>      2</b> pot pour déposer de l’argent, AR. <i>Av. 602 ;</i><br><b>      3</b> urne pour les cendres des morts, PLUT. <i>Phil. 21 ;</i> LUC. <i>Dem. enc. 29 ;</i> ATH. <i>589</i> b ;<br><b>      4</b> urne pour voter au tribunal, ISOCR. <i>365</i> c ; DÉM. <i>1155, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ὑδρίη <span>[ῑ]</span> A. RH. <i>4, 1767</i>.<br><span><b>Étym</b>. ὕδωρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υδρια - ὑδρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G5202":"<h1>hudropoteo</h1>\n<p>Strong n° 5202 <i>Prononciation [hoo-drop-ot-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>boire de l'eau, être un buveur d'eau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑδροποτέω-ῶ</b>, ne boire que de l’eau, HDT. <i>1, 71 ;</i> XÉN. <i>Cyr. 6, 2, 26 ;</i> PLAT. <i>Rsp. 561</i> c, <i>etc</i>.<br><span><b>Étym</b>. ὑδροπότης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υδροποτεω - ὑδροποτέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5203":"<h1>hudropikos</h1>\n<p>Strong n° 5203 <i>Prononciation [hoo-dro-pik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>hydropique, souffrant d'hydropisie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑδρωπικός, ή, όν</b>, hydropique, HPC. <i>Aph. 1246 ;</i> ARSTT. <i>Probl. 3, 5, 7 ;</i> POL. <i>13, 2, 6 ; fig</i>. ANTH. <i>11, 332 ;</i> τὸ ὑδρωπικόν, LGN <i>3, 4,</i> hydropisie.<br><span><b>Étym</b>. ὕδρωψ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υδρωπικος - ὑδρωπικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5204":"<h1>hudor</h1>\n<p>Strong n° 5204 <i>Prononciation [hoo'-dore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>eau\n<ol type=\"a\">\n<li>de l'eau des fleuves, fontaines, puits</li>\n<li>de l'eau du déluge</li>\n<li>de l'eau dans tout dépôt terrestre</li>\n<li>de l'eau comme élément primaire, d'où est venu le monde d'avant déluge</li>\n<li>des flots de la mer</li>\n<li>fig. utilisé pour les peuples nombreux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕδωρ</b>, <i>gén</i>. <b>ὕδατος (τὸ)</b> <span>[ῠ <i>v. ci-dessous</i>]</span> eau :<br><b>   I</b> <i>en gén</i>. HOM. <i>etc. ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> eau de mer, OD. <i>3, 300 ;</i> ἁλμυρὸν ὕδωρ, OD. <i>9, 227,</i> eau salée, <i>etc. ;</i><br><b>      2</b> eau de fleuve, de rivière, IL. <i>2, 825 ; 8, 365, etc. ; au plur. une fois dans Hom</i>. OD. <i>13, 109 ; cf</i>. SOPH. <i>O.C. 1599, fr. 265, etc. ;</i><br><b>      3</b> eau de source, IL. <i>16, 161 ; 21, 312, etc. ;</i><br><b>      4</b> eau potable, OD. <i>9, 85 ; 10, 56, etc. ;</i> οἶνον καὶ ὕδωρ μίσγειν, OD. <i>1, 110,</i> mêler du vin et de l’eau ; ἐφ' ὕδωρ φοιτᾶν, HDT. <i>7, 137, etc</i>. aller chercher de l’eau, <i>au plur</i>. ὕδατα καὶ σῖτοι, PLAT. <i>Rsp. 404</i> b, de l’eau et des aliments ; πότιμον ὕδωρ, XÉN. <i>Hell. 3, 2, 19,</i> eau potable ; <span><i>prov</i>. ὕδωρ πίνειν</span>, AR. <i>Eq. 349 ;</i> DÉM. <i>73, 3 ; 355, 24,</i> boire de l’eau, <i>càd</i>. être insipide <i>ou</i> inerte, être incapable de grandes pensées, de grands sentiments, <i>etc. ;</i><br><b>      5</b> eau pour se laver : χερσὶν ὕδωρ ἐπιχεῖν, IL. <i>3, 270, etc. ;</i> OD. <i>1, 147, etc</i>. verser de l’eau sur les mains ; ὕδωρ κατὰ χειρός, AR. <i>Vesp. 1216,</i> l’eau qu’on se faisait verser sur les mains avant le repas ;<br><b>      6</b> eau pour se baigner, IL. <i>23, 282 ;</i><br><b>      7</b> eau, comme élément, <i>p. opp. à</i> γῆ : γῆν καὶ ὕδωρ αἰτεῖν, HDT. <i>5, 17, 18, etc</i>. demander la terre et l’eau, <i>en signe de domination ;</i> γῆν καὶ ὕδωρ διδόναι, HDT. <i>5, 18, etc</i>. donner la terre et l’eau, <i>càd</i>. se soumettre ; <i>prov</i>. <span>ἐν ὕδατι γράφειν</span>, PLAT. <i>Phædr. 276</i> c, <i>ou</i> καθ' ὕδατος γράφειν, LUC. <i>Cat. 21,</i> écrire sur l’eau, <i>càd</i>. faire de vains efforts, se donner une peine inutile ;<br><b>      8</b> eau de pluie, IL. <i>16, 385 ;</i> ὕδωρ ἐξ οὐρανοῦ, THC. <i>2, 77,</i> eau du ciel ; τὰ ἐκ Διὸς ὕδατα, PLAT. <i>Criti. 113</i> e, <i>Leg. 761</i> a, <i>m. sign. ;</i> ὕδατα ὄμϐρια, PD. <i>O. 10, 22, m. sign. ;</i> γίγνεται ὕδωρ, HDT. <i>8, 12, etc. ;</i> THC. <i>6, 70 ;</i> XÉN. <i>Hell. 1, 6, 28, etc</i>. il commence à pleuvoir ; τὸ ὕδωρ τὸ γενόμενον τῆς νυκτός, THC. <i>2, 5,</i> pluie survenue pendant la nuit ; χέει ὕδωρ Ζεύς, IL. <i>16, 385 ;</i> ὁ Ζεὺς ὕει ὕδωρ, AR. <i>Nub. 1280 ;</i> ὁ θεὸς ποιεῖ ὕδωρ, AR. <i>Vesp. 261,</i> Zeus <i>ou</i> le dieu fait tomber la pluie ; ὗσαι ὕδατι, HDT. <i>1, 87,</i> pleuvoir ;<br><b>      9</b> eau de la clepsydre (<i>v</i>. κλεψύδρα) ESCHN. <i>82, 13 ;</i> ἐν τῷ ἐμῷ ὕδατι, DÉM. <i>274, 9 ; 339, 5, etc. ;</i> ἐπὶ τοῦ ἐμοῦ ὕδατος, DÉM. <i>1318, 6,</i> pendant l’écoulement de mon eau, <i>càd</i>. pendant le temps qui m’était mesuré par la clepsydre ; πρὸς ὕδωρ σμικρὸν διδάξαι, PLAT. <i>Theæt. 201</i> b, instruire avec peu d’eau devant soi, <i>càd</i>. avoir peu de temps pour instruire ; ἐὰν τὸ ὕδωρ ἐγχωρῇ, DÉM. <i>1094, 3,</i> si le temps le permet ; οὐχ ἱκανόν μοι τὸ ὕδωρ, DÉM. <i>1116, 11,</i> le temps dont je dispose n’est pas suffisant ; ἀποδιδόναι τινὶ τὸ ὕδωρ, DÉM. <i>23, 20 ; ou</i> ἐγχεῖν, DÉM. <i>407, 16, etc</i>. donner la parole à qqn ; ὑπὲρ τὸ ἐγχεόμενον ὕδωρ (<i>v</i>. ὑπέρ) au delà de l’eau versée, <i>càd</i>. du temps accordé :<br><b>      10</b> sueur : ἐν ὕδατι βρέχεσθαι, HDT. <i>3, 104,</i> être mouillé, inondé de sueur :<br><b>      11</b> <i>en gén</i>. tout liquide (vin, urine, <i>etc</i>.) ARSTT. <i>Meteor. 4, 5, 6</i> :<br><b>      12</b> l’eau du Verseau, <i>constellation,</i> ARAT. <i>399</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῠ]</span> ; <i>ttef</i>. <span>[ῡ]</span> <i>à l’arsis dans Hom. et</i> AR. <i>Ran. 1339 ; postér., à la thésis,</i> HH. <i>Cer. 382 ;</i> BATR. <i>97, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *udōr, *ud-n-, eau ; <i>cf. lat</i>. unda, <i>sscr</i>. udán-, <i>all</i>. Wasser.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υδωρ - ὕδωρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n79 fois dans 70 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (5)</li>\n<li>Luc (6)</li>\n<li>Jean (24)</li>\n<li>Actes (7)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (3)</li>\n<li>1 Jean (4)</li>\n<li>Apocalypse (18)</li>\n</ul>\n</td></tr>\n</table>","G5205":"<h1>huetos</h1>\n<p>Strong n° 5205 <i>Prononciation [hoo-et-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pluie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑετός, οῦ (ὁ)</b> <span>[ῡ]</span> forte pluie, pluie continue (<i>p. opp. à</i> ὄμϐρος) IL. <i>12, 133 ;</i> HÉS. <i>O. 543 ;</i> XÉN. <i>Cyn. 5, 4 ;</i> ARSTT. <i>Meteor. 1, 9, 6 ; au plur</i>. ARSTT. <i>P.A. 2, 7, 12</i>.<br><span> ῠ <i>au gén. épq</i>. ὑετοῖο.<br><span><b>Étym</b>. ὕω ; <i>v</i>. ὑετώτερος <i>et</i> ὑετώτατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υετος - ὑετός</font>\n<br><br>vient du mot primaire huo (pleuvoir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G5206":"<h1>huiothesia</h1>\n<p>Strong n° 5206 <i>Prononciation [hwee-oth-es-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>adoption, adoption comme fils\n<ol type=\"a\">\n<li>cette relation que Dieu s'est plu à établir entre lui-même et les Israélites en préférence aux autres nations</li>\n<li>la nature et la condition des vrais disciples en Christ, qui par la réception de l'Esprit de Dieu en leur âme sont devenus fils de Dieu</li>\n<li>l'état de bénédiction considéré pour la vie future après le retour visible de Christ depuis les cieux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>υἱο·θεσία, ας (ἡ)</b> adoption de qqn comme fils, NT. <i>Rom. 8, 23 ;</i> GAL. <i>4, 5</i>.<br><span><b>Étym</b>. υἱός, τίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υιοθεσια - υἱοθεσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5207":"<h1>huios</h1>\n<p>Strong n° 5207 <i>Prononciation [hwee-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un fils\n<ol type=\"a\">\n<li>rarement utilisé pour le petit d'un animal</li>\n<li>généralement utilisé pour la descendance des hommes</li>\n<li>dans un sens restrictif, la descendance mâle (d'un père et d'une mère)</li>\n<li>dans un sens plus large, un descendant, quelqu'un de la postérité de n'importe qui\n<ol>\n<li>les enfants d'Israël</li>\n<li>les fils d'Abraham</li>\n</ol>\n</li>\n<li>utilisé pour décrire quelqu'un qui dépend d'un autre ou qui le suit\n<ol>\n<li>un élève, un pupille</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>fils de l'homme\n<ol type=\"a\">\n<li>terme décrivant l'homme, supportant la connotation de faiblesse et de mortalité</li>\n<li>dénote symboliquement le cinquième royaume dans <a class=\"ref\" data-r=\"DAN7.13\">Daniel 7.13</a> et par ce terme son humanité est indiquée en contraste avec la brutalité, la férocité, des quatre royaumes précédents (celui de Babylone, celui des Mèdes, le Perse, le Macédonien) représentés par les quatre bêtes dans le livre d'Enoch, (du 2<sup>ème</sup> siècle) et il est utilisé pour Christ</li>\n<li>utilisé par Christ lui-même, sans doute pour indiquer qu'il était le Messie, qu'il avait été désigné pour prendre la tête de la race humaine, l'homme, celui qui à la fois fournissait le modèle de l'homme parfait agissant en faveur de tout le genre humain. Christ semble avoir préféré ce titre à tous les autres titres Messianiques, parce que par son abaissement, il n'y avait pas l'espérance d'un Messie terrestre dans une splendeur royale.</li>\n</ol>\n</li>\n<li>fils de Dieu\n<ol type=\"a\">\n<li>utilisé pour décrire Adam (<a class=\"ref\" data-r=\"LUK3.38\">Luc 3.38</a>)</li>\n<li>utilisé pour décrire ceux qui sont nés de nouveau <a class=\"ref\" data-r=\"LUK20.36\">Luc 20.36</a> les anges, et Jésus-Christ</li>\n<li>de ceux que Dieu estime comme ses fils, qu'il aime, protège et bénit par dessus tous\n<ol>\n<li>dans l'A.T, utilisé des Juifs</li>\n<li>dans le N.T, des Chrétiens</li>\n<li>ceux dont Dieu modèle le caractère, par des châtiments, comme un père aimant (<a class=\"ref\" data-r=\"HEB12.5-8\">Hébreux 12.5-8</a>)</li>\n</ol>\n</li>\n<li>ceux qui vénèrent Dieu comme leur père, les pieux adorateurs de dieu, qui dans leur caractère et leur vie veulent lui ressembler, ceux qui sont gouvernés par l'Esprit de Dieu, ont le même calme et la même confiance joyeuse en Dieu que des enfants dans leurs parents (<a class=\"ref\" data-r=\"ROM8.14\">Romains 8.14</a> ; <a class=\"ref\" data-r=\"GAL3.26\">Galates 3.26</a>) et dorénavant dans la bénédiction et la gloire de la vie éternelle et veulent porter ouvertement cette dignité de fils de Dieu. Le terme est d'abord utilisé pour Jésus-Christ, jouissant de l'amour suprême de Dieu, uni à lui dans une intime affection, obéissant à la volonté du Père dans toutes ses actions.</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>υἱός, οῦ (ὁ) :<br>      1</b> fils, HOM. ATT. <i>etc. ; au plur. par périphr. avec un gén. pour désigner une classe d’hommes :</i> υἷες (<i>v. ci-dessous</i>) Ἀχαιῶν, IL. <i>1, 162, etc</i>. les fils des Grecs, <i>càd</i>. les Grecs ; <i>surt. postér. pour désigner une profession :</i> υἱεῖς (<i>v. ci-dessous</i>) ἰατρῶν <i>ou</i> ῥητόρων, ATT. les fils des médecins <i>ou</i> des orateurs, <i>càd</i>. les médecins, les orateurs ;<br><b>      2</b> gendre, DH. <i>4, 4 dout. ;</i> υἱός <i>est souv. s.-e. dans les désignations de parenté :</i> ὁ τοῦ Ὀλόρου, DH. <i>Rhet. 6, 1,</i> le fils d’Oloros, <i>càd</i>. Thucydide ; <i>de même dans les inscr. att. ; ttef. pour la désignation des noms d’artistes et dans les inscr. votives, on trouve qqf. mentionnés</i> υἱύς, ὑύς, <i>ou</i> υἱός, ὑός, <i>v. Meisterh. p. 167, 15</i>.<br><br>   I</b> <i>La déclin. est régul. :</i> υἱός, υἱοῦ, <i>etc. ; cependant les Att. déclinent, comme il suit, d’un th</i>. υἱε- (<i>p</i>. υἱεϝ-) ; <i>gén</i>. υἱέος, <i>dat</i>. υἱεῖ ; <i>plur</i>. υἱεῖς, υἱέων, υἱέσι, SOPH. <i>Ant. 571 ;</i> AR. <i>Nub. 1001 ;</i> υἱεῖς ; <i>duel</i> υἱέε, LYS. <i>156, 4 ;</i> υἱέοιν ; <i>les gén. sg</i>. υἱέως, <i>acc. sg. et pl</i>. υἱέα, υἱέας <i>sont blâmés par les anciens comme non-att. La déclin. homér. procède de trois thèmes :</i><br><b>      1</b> <i>du th</i>. υἱο- : υἱός, υἱοῦ (<i>une fois seul</i>. OD. <i>22, 238</i>), υἱόν ; <i>pl</i>. υἱῶν, υἱοῖσι, OD. <i>19, 498 ; acc</i>. υἱούς, IL. <i>5, 159 ;</i><br><b>      2</b> <i>du th</i>. υἱε- : <i>dat</i>. υἱέϊ <i>et</i> υἱεῖ, <i>acc</i>. υἱέα, IL. <i>13, 350 ; pl. nom</i>. υἱέες <i>et</i> υἱεῖς, <i>acc</i>. υἱέας ; <i>ce thème</i> υἱε- <i>est allongé en</i> υἱη- <i>chez les Épq. post. :</i> υἱῆος, υἱῆϊ, υἱῆα ; υἱῆες, υἱήεσσι, υἱῆας, A. RH. <i>2, 1094, 1119 ;</i> ANTH. <i>8, 88 ; 9, 23, etc. ;</i><br><b>      3</b> <i>d’un th</i>. υἱ- : <i>gén</i>. υἷος, <i>dat</i>. υἷϊ, <i>acc</i>. υἷα ; <i>pl. nom</i>. υἷες, <i>dat</i>. υἱάσι, <i>acc</i>. υἷας ; <i>duel nom.-acc</i>. υἷε ; <i>c’est cette dernière déclin. que les Épq. postér. ont suivie de préférence. ;</i><br><b>   II</b> <i>Dans les inscr. att. les formes se rattachent à trois types principaux :</i><br><b>      1</b> <i>thème</i> υἱ- <i>ou</i> ὑ-, <i>d’où l’acc. sg</i>. υἷα <i>et le nom. pl</i>. υἷες (<i>inscr. du 3<sup>e</sup> au 2<sup>e</sup> siècle av. J.C</i>.) ;<br><b>      2</b> <i>thème</i> υἱυ- <i>ou</i> ὑυ- <i>d’où le nom. sg</i>. υἱύς (<i>av. le 5<sup>e</sup> siècle av. J.C.), forme qu’on retrouve dans des inscr lacon., arcad. et crét. (avant le 5<sup>e</sup> siècle av. J.C.) ; et</i> ὗς (<i>6<sup>e</sup> siècle av. J.C.) ; le gén. sg. avec allong. en</i> υἱη- : υἱῆος (<i>époque de l’empire) et l’acc</i>. υἱέα (<i>époque de l’empire), et sans</i> ι : (<i>nom. sg</i>. ὑύς (<i>6<sup>e</sup> siècle av. J.C.) ; gén</i>. ὑέος (<i>400/350 av. J.C.) ; plur</i>. ὑεῖς (<i>409 av. J.C.), etc. ;</i><br><b>      3</b> <i>thème</i> υἱο <i>ou</i> ὑο-, <i>ce dernier le plus usuel et dont les exemples se répartissent, selon le tableau dressé par Meisterhans dans la proportion suiv. : 6<sup>e</sup> siècle av. J.C. 2 ex. de</i> υἱός, <i>1 de</i> ὑός ; <i>5<sup>e</sup> siècle : 1 de</i> υἱός, <i>3 de</i> ὑός ; <i>4<sup>e</sup> siècle : aucun de</i> υἱός, <i>7 de</i> ὑός ; <i>3<sup>e</sup> siècle : aucun de</i> υἱός, <i>9 de</i> ὑός ; <i>2<sup>e</sup> siècle : 1 de</i> υἱός, <i>32 de</i> ὑός ; <i>1<sup>er</sup> siècle : 4 de</i> υἱός, <i>7 de</i> ὑός ; <i>de ces divers thèmes ceux en</i> ῡυ- <i>disparaissent peu à peu, et à partir de 350 av. J.C. on ne rencontre plus que les formes en</i> υἱο- <i>ou</i> ὑο- ; <i>sur ces diverses formes, v. Meisterh. p. 47, 4 et 113, 14</i>.<br><span> υι <i>monosyll. long ; toutefois bref à la thésis dans Hom. au nom</i>. υἱός, IL. <i>6, 130 ; 17, 575 ;</i> OD. <i>11, 270 ; au voc</i>. υἱέ, IL. <i>7, 47 ; à l’acc</i>. υἱόν, IL. <i>4, 473 ; 6, 512 ; 17, 590</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *suH-i(e)u-, fils ; <i>cf. sscr</i>. sūnú-.</span></span><br><br>\n➁ <b>υἷος</b>, <i>v</i>. υἱός.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υιος - υἱός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – se réfère exclusivement aux petits enfants\n<br><br> – se réfère à l'enfant jusqu'à ses premières années d'école\n<br><br> – se réfère à l'enfant de tout âge\n<br><br> – se réfère à la grande enfance et la première jeunesse\n<br><br>,  dénote un enfant aussi bien en tant que descendant que par son âge, la référence à l'âge étant plus marquée dans\n<br><br> mais la période que couvre  n'est pas très exactement définie ; et dans l'usage classique ou moderne, la désignation de jeunesse va plus loin pour les filles que les garçons\n<br><br>Comparer : , \n<br><br> – donne la prééminence aux aspects physiques et extérieurs de famille\n<br><br> – donne la prééminence aux aspects internes, éthiques, légaux</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n381 fois dans 348 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (90)</li>\n<li>Marc (35)</li>\n<li>Luc (78)</li>\n<li>Jean (56)</li>\n<li>Actes (22)</li>\n<li>Romains (12)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (13)</li>\n<li>Ephésiens (4)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (24)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (22)</li>\n<li>2 Jean (2)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G5208":"<h1>hule</h1>\n<p>Strong n° 5208 <i>Prononciation [hoo-lay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une forêt, un bois</li>\n<li>du bois tombé, un combustible</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕλη, ης (ἡ)</b> <span>[ῡ]</span><br><b>   I</b> bois sur pied, <i>càd. :</i><br><b>      1</b> bois, forêt, HDT. <i>1, 203 ; p. opp. à</i> δένδρα, arbres fruitiers, THC. <i>4, 69 ;</i><br><b>      2</b> taillis, broussailles, XÉN. <i>An. 1, 5, 1 ; Œc. 16, 13, etc. ;</i><br><b>      3</b> arbre, <i>en gén</i>. HDT. <i>4, 21 ;</i><br><b>   II</b> bois coupé <i>ou</i> tombé, <i>particul</i>. bois à brûler, IL. <i>7, 418 ; 23, 50, etc. ;</i> OD. <i>9, 234 ;</i> HDT. <i>4, 164, etc. ;</i> XÉN. <i>Hell. 4, 5, 4, etc. ;</i> bois de construction, PLAT. <i>Leg. 705</i> c ; TH. <i>H.P. 5, 7, 1 ; p. suite :</i><br><b>      1</b> matériaux de construction, <i>en gén</i>. (bois, pierre, <i>etc</i>.) XÉN. <i>Hell. 1, 1, 25 ;</i> TH. <i>H.P. 5, 2, 1 ;</i> bois pour les parties vides d’un navire, ballast, OD. <i>5, 257 ; d’où fig</i>. matière dont une chose est faite, OD. <i>5, 257 ;</i> HDT. <i>4, 164, etc. ; p. suite,</i> matière, <i>au sens philosophique,</i> ARSTT. <i>Gen. et corr. 1, 4, 7 ; Metaph. 6, 7, 2, etc. ;</i> LGN <i>13, 4 ; particul</i>. matière d’un poème, d’un ouvrage, POL. <i>2, 16, 14, etc. ;</i> ὕλη ἰατρική, GAL. <i>9, 494,</i> la matière médicale, <i>càd</i>. l’ensemble de choses qu’embrasse la médecine ;<br><b>      2</b> résidu matériel, partie substantielle <i>ou</i> la plus grossière d’un corps, <i>particul</i>. lie du vin, AR. <i>fr. 697 dout</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ὕλα <span>[ᾱ]</span> PD.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *suol-h₂-, *suel-, <i>cf</i>. εἵλη, <i>ou</i> *h₁eus-l-h₂, <i>cf</i>. εὕω, « bois de chauffage ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υλη - ὕλη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G5209":"<h1>humas</h1>\n<p>Strong n° 5209 <i>Prononciation [hoo-mas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vous</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑμᾶς</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμας - ὑμᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n434 fois dans 386 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (38)</li>\n<li>Marc (14)</li>\n<li>Luc (37)</li>\n<li>Jean (36)</li>\n<li>Actes (27)</li>\n<li>Romains (32)</li>\n<li>1 Corinthiens (41)</li>\n<li>2 Corinthiens (59)</li>\n<li>Galates (19)</li>\n<li>Ephésiens (10)</li>\n<li>Philippiens (12)</li>\n<li>Colossiens (17)</li>\n<li>1 Thessaloniciens (33)</li>\n<li>2 Thessaloniciens (16)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (13)</li>\n<li>2 Pierre (6)</li>\n<li>1 Jean (6)</li>\n<li>2 Jean (2)</li>\n<li>Jude (3)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G5210":"<h1>humeis</h1>\n<p>Strong n° 5210 <i>Prononciation [hoo-mice']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vous</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑμεῖς</b>, <i>gén</i>. <b>ὑμῶν</b>, <i>dat</i>. <b>ὑμῖν</b>, <i>acc</i>. <b>ὑμᾶς</b> <span>[ῡ]</span> vous, <i>plur. de</i> σύ.<br><span><b>Étym</b>. <i>v</i>. σύ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμεις - ὑμεῖς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n243 fois dans 229 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (32)</li>\n<li>Marc (12)</li>\n<li>Luc (23)</li>\n<li>Jean (68)</li>\n<li>Actes (26)</li>\n<li>Romains (7)</li>\n<li>1 Corinthiens (18)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (5)</li>\n<li>Ephésiens (7)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (6)</li>\n<li>1 Thessaloniciens (10)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (6)</li>\n<li>Jude (2)</li>\n</ul>\n</td></tr>\n</table>","G5211":"<h1>Humenaios</h1>\n<p>Strong n° 5211 <i>Prononciation [hoo-men-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hyménée (Angl. Hymenaeus) = « appartenant à Hymen, dieu du mariage »\n<ol><li>un hérétique, un des opposants de l'apôtre Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ὑμέναιος, ου (ὁ)</b> Hyménæos, <i>dieu du mariage, qu’on invoquait dans le chant nuptial</i> (<i>v</i>. Ὑμήν).<br><span><b>Étym</b>. <i>cf</i>. ὑμέναιος.</span><br><br>\n<b>ὑμέναιος, ου (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> hyménée, <i>chant nuptial que l’on chantait en conduisant la jeune fille à son fiancé,</i> IL. <i>18, 493 ;</i> HÉS. <i>Sc. 274 ; au plur</i>. PD. <i>P. 3, 30 ;</i> EUR. <i>Alc. 922, etc. ;</i><br><b>      2</b> hyménée, mariage, SOPH. <i>O.R. 422 ;</i> EUR. <i>Ion 1475 ; au plur</i>. SOPH. <i>Ant. 813 ;</i> EUR. <i>I.A. 123, etc</i>.<br><span><b>Étym</b>. ὑμήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Υμεναιος - Ὑμέναιος</font>\n<br><br>vient de Humen (le dieu des noces)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5212":"<h1>humeteros</h1>\n<p>Strong n° 5212 <i>Prononciation [hoo-met'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>à vous, le vôtre\n<ol type=\"a\">\n<li>ce qui est possédé par vous</li>\n<li>ce qui est à vous</li>\n<li>venant de vous</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑμέτερος, α, ον</b> <span>[ῡ]</span><br><b>      1</b> votre, le vôtre, IL. <i>5, 489 ; 13, 815 ;</i> OD. <i>1, 375 ; 9, 284 ;</i> HÉS. <i>Th. 662 ;</i> PD. <i>P. 7, 15 ; 8, 95, etc. ; avec un gén</i>. ὑμέτερος ἑκάστου θυμός, IL. <i>17, 226,</i> votre courage à chacun de vous ; ὑμέτερος αὐτῶν θυμός, OD. <i>2, 138,</i> votre propre cœur ; <i>en prose, d’ordin. avec l’art. :</i> ταῖς ὑμετέραις πόλεσι, PLAT. <i>Leg. 836</i> c, à vos villes ; <i>ou au sens pass. :</i> αἱ ὑμέτεραι ἐλπίδες, THC. <i>1, 69,</i> les espérances fondées sur vous ; τὸ ὑμέτερον, ce qui vous concerne, votre intérêt, vos dispositions, HDT. <i>8, 140 ; ou</i> votre caractère, vos habitudes, THC. <i>1, 70 ;</i> τὰ ὑμέτερα, XÉN. <i>Cyr. 3, 2, 12,</i> vos biens ;<br><b>      2</b> ton, le tien, PD. <i>P. 7, 15 ; 8, 95 ;</i> SOL. <i>11, 2 ;</i> CALL. <i>Del. 204, 228 ;</i> NONN. <i>D. 5, 340 ; 6, 304 ;</i> ANTH. <i>5, 293</i>.<br><span><b>Étym</b>. ὑμεῖς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμετερος - ὑμέτερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G5213":"<h1>humin</h1>\n<p>Strong n° 5213 <i>Prononciation [hoo-min']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vous</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑμῖν</b>, <i>dat. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμιν - ὑμῖν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n616 fois dans 562 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (109)</li>\n<li>Marc (36)</li>\n<li>Luc (99)</li>\n<li>Jean (101)</li>\n<li>Actes (32)</li>\n<li>Romains (16)</li>\n<li>1 Corinthiens (46)</li>\n<li>2 Corinthiens (31)</li>\n<li>Galates (15)</li>\n<li>Ephésiens (8)</li>\n<li>Philippiens (13)</li>\n<li>Colossiens (11)</li>\n<li>1 Thessaloniciens (14)</li>\n<li>2 Thessaloniciens (12)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (7)</li>\n<li>Jacques (9)</li>\n<li>1 Pierre (11)</li>\n<li>2 Pierre (8)</li>\n<li>1 Jean (23)</li>\n<li>2 Jean (1)</li>\n<li>Jude (5)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G5214":"<h1>humneo</h1>\n<p>Strong n° 5214 <i>Prononciation [hoom-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>célébrer la louange de, chanter des hymnes à</li>\n<li>chanter un cantique, chanter\n<ol type=\"a\">\n<li>chant d'hymnes pascals, les <a class=\"ref\" data-r=\"PSA113-118;136\">Psaumes 113 – 118 et 136</a>, que les Juifs appelaient le « grand Hallel »</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑμνέω-ῶ</b> <span>(<i>f</i>. -ήσω, <i>ao</i>. ὕμνησα, <i>pf</i>. ὕμνηκα)</span> <span>[ῡ, <i>p. exc</i>. ῠ, <i>v. ci-dessous</i>]</span><br><b>   I <i>tr</i>.<br>      1</b> chanter un chant grave, religieux <i>ou</i> héroïque : ὕμνον, ESCHL. <i>Ag. 1191, 1474,</i> chanter un hymne ; παιᾶνα, EUR. <i>H.f. 688,</i> chanter le péan ;<br><b>      2</b> chanter, louer, célébrer dans un chant <i>ou</i> dans des vers, <i>acc</i>. HH. <i>Ap. 190 ;</i> HÉS. <i>Th. 11, 33 ;</i> PD. <i>O. 7, 14 ;</i> HDT. <i>4, 35 ;</i> XÉN. <i>Mem. 4, 2, 23, etc. ;</i> κακά, SOPH. <i>El. 382,</i> déplorer ses malheurs ; <i>avec double rég. :</i> τινα θρήνοις, EUR. <i>Rhes. 976,</i> chanter dans un chant de deuil les malheurs de qqn ; <i>avec double acc. :</i> ἃ τὴν πόλιν ὕμνησα, THC. <i>2, 42,</i> les vertus dont j’ai loué la ville ; <i>au pass</i>. être chanté, célébré <i>ou</i> bafoué par des chants, HDT. <i>5, 67 ;</i> ESCHL. <i>Sept. 7 ;</i><br><b>      3</b> vanter, rappeler avec emphase, avoir sans cesse à la bouche, PLAT. <i>Prot. 317</i> a, <i>Rsp. 364</i> a, <i>549</i> e, <i>etc. ; au pass</i>. XÉN. <i>Hell. 7, 1, 38 ;</i> ARSTT. <i>Nic. 10, 10, 6 ;</i><br><b>      4</b> <i>en mauv. part,</i> accuser sans cesse <i>ou</i> avec véhémence, se plaindre en termes véhéments de, <i>acc</i>. PLAT. <i>Rsp. 329</i> b ;<br><b>      5</b> réciter comme un chant (un texte de loi) <i>acc</i>. PLAT. <i>Leg. 870</i> e ;<br><b>   II <i>intr.</i></b> retentir, résonner, se faire entendre, PLAT. <i>Rsp. 463</i> d.<br><span><b><span class=\"arrow\"></span></b> <span>[ῠ]</span> EUR. <i>Bacch. 71. Prés. ind. épq</i>. ὑμνείω, HÉS. <i>O. 2 ; 3 pl. dor</i>. ὑμνεῦσι, HH. <i>Ap. 190 ; impér. 2 sg. dor</i>. ὕμνη, AR. <i>Lys. 1321 ; sbj. 1 pl. dor</i>. ὑμνίωμες, AR. <i>Lys. 1305 ; part. fém. ion. et dor</i>. ὑμνεῦσα, HÉS. <i>Th. 11 ; plur</i>. ὑμνεῦσαι, EUR. <i>Med. 423 ; pf. pass. 3 pl. ion</i>. ὑμνέαται, HDT. <i>5, 67</i>.<br><span><b>Étym</b>. ὕμνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμνεω - ὑμνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5215":"<h1>humnos</h1>\n<p>Strong n° 5215 <i>Prononciation [hoom'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un chant à la louange des dieux, héros, conquérants</li>\n<li>un chant sacré, un hymne</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕμνος, ου (ὁ) :<br>   I</b> <i>propr</i>. trame : ὕμνος ἀοιδῆς, OD. <i>8, 429,</i> trame d’un chant ;<br><b>   II</b> <i>p. suite,</i> chant, <i>particul. :</i><br><b>      1</b> chant en l’honneur d’un dieu <i>ou</i> d’un héros, hymne, HH. <i>Ap. 160 ;</i> HÉS. <i>O. 655 ;</i> PLAT. <i>Rsp. 607</i> a, <i>etc. ;</i> PD. <i>O. 1, 14 ; 3, 5, etc. ;</i> PLAT. <i>Leg. 700</i> b, <i>801</i> d ;<br><b>      2</b> <i>p. ext</i>. chant nuptial, SOPH. <i>Ant. 814 ;</i><br><b>      3</b> chant de deuil, ESCHL. <i>Sept. 867 ; Pers. 620, 625 ; Eum. 331 ;</i> EUR. <i>Alc. 447, etc</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμνος - ὕμνος</font>\n<br><br>Voir définition 5667</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> est le terme générique ;  et  sont spécifiques,\n<br><br> désignant un chant qui a pris son caractère général dans les Psaumes de l'AT, bien que non limité à eux,  est un hymne, un chant de louange. Tandis que l'idée maîtresse de\n<br><br> est d'être un accompagnement musical, et que  est une louange à Dieu,  est le mot global pour un chant, accompagné ou non, pour une louange ou tout autre sujet. Il est donc tout à fait possible que le même chant soit décrit par ces trois différents mots.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5216":"<h1>humon</h1>\n<p>Strong n° 5216 <i>Prononciation [hoo-mone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de vous, votre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑμῶν</b>, <i>gén. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υμων - ὑμῶν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n581 fois dans 502 versets de 25 livres bibliques (NT)\n<ul>\n<li>Matthieu (78)</li>\n<li>Marc (18)</li>\n<li>Luc (66)</li>\n<li>Jean (53)</li>\n<li>Actes (36)</li>\n<li>Romains (28)</li>\n<li>1 Corinthiens (45)</li>\n<li>2 Corinthiens (58)</li>\n<li>Galates (7)</li>\n<li>Ephésiens (21)</li>\n<li>Philippiens (23)</li>\n<li>Colossiens (24)</li>\n<li>1 Thessaloniciens (26)</li>\n<li>2 Thessaloniciens (12)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Philémon (2)</li>\n<li>Hébreux (22)</li>\n<li>Jacques (24)</li>\n<li>1 Pierre (22)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (1)</li>\n<li>2 Jean (1)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G5217":"<h1>hupago</h1>\n<p>Strong n° 5217 <i>Prononciation [hoop-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mener, conduire sous, apporter au-dessous</li>\n<li>se retirer, s'en aller, partir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·άγω</b> <span>(<i>f</i>. -άξω, <i>ao.2</i> -ήγαγον, <i>etc</i>.)</span> <span>[ῠᾰγ]</span><br><b>A <i>tr. :</i><br>      1</b> amener sous : ἵππους ζυγόν, IL. <i>16, 148 ; 23, 291 ; 24, 279 ; ou</i> ἵππους ζυγῷ, LUC. <i>Fug. 6,</i> amener les chevaux sous le joug, les atteler ; <i>abs. :</i> ὑπάγειν ἵππους, OD. <i>6, 73 ;</i> LUC. <i>D. deor. 25, 3, m. sign. ; fig. :</i> τινὰ ἐς χέρας τινός, HDT. <i>8, 106,</i> livrer une personne aux mains d’une autre ; τινὰ εἰς δουλείαν, LUC. <i>Apol. 3,</i> livrer qqn en servitude ; <i>particul. t. de jurisprud. :</i> τινὰ ὑπὸ τὸ δικαστήριον, HDT. <i>6, 72 ; 9, 93 ; ou</i> δικαστηρίῳ, LUC. <i>Fug. 11 ;</i> ὑπὸ τοὺς ἐφόρους, HDT. <i>6, 82,</i> amener qqn devant le tribunal, devant les éphores ; ἐς δίκην, THC. <i>3, 70 ; ou abs</i>. ὑπ. τινά, XÉN. <i>Hell. 2, 3, 38, etc</i>. amener en justice ; <i>d’où</i> intenter un procès, accuser : τινὰ θανάτου, XÉN. <i>Hell. 1, 3, 12 ; 2, 3, 11, etc</i>. accuser qqn d’un crime capital ; ὑπ. ὑπὸ τὸν δῆμον, HDT. <i>6, 136,</i> traîner en accusation devant le peuple ;<br><b>      2</b> amener par des voies secrètes <i>ou</i> détournées, amener par surprise : τοὺς πολεμίους ἐς δυσχωρίαν, XÉN. <i>Cyr. 1, 6, 37,</i> attirer l’ennemi dans un passage difficile ; ἐς ἐνέδρας, XÉN. <i>Hipp. 4, 12,</i> dans une embuscade ; emmener par ruse loin de, détourner par ruse de, <i>avec</i> ἀπό <i>et le gén. en parl. de la perdrix qui détourne le chasseur,</i> ARSTT. <i>H.A. 9, 8, 6 ;</i> ὑπ. τινὰ εἴς τι, DÉM. <i>127, 27 ; 678, 9,</i> pousser qqn à une entreprise difficile <i>ou</i> périlleuse ; <i>avec un inf</i>. entraîner à, pousser à, EUR. <i>Andr. 428 ; au pass</i>. être poussé à, <i>etc</i>. DÉM. <i>1433, 26 ; p. suite,</i> amener hors du droit chemin, <i>d’où</i> égarer, séduire, PLAT. <i>Euthyphr. 14</i> c ; <i>en gén</i>. tromper, HDT. <i>9, 94 ; au pass</i>. être trompé : τινι, DÉM. <i>59, 18, etc. ;</i> ὑπό τινος, DÉM. <i>25, 23,</i> par qqe ch. ;<br><b>      3</b> mener en dessous, <i>d’où au pass</i>. être mené en dessous, être entraîné en dessous, s’affaisser, THC. <i>2, 76 ;</i><br><b>      4</b> mener à l’écart, emmener hors de : τινα ἐκ βελέων, IL. <i>11, 163,</i> emmener qqn hors de la portée des traits ; τὸ στράτευμα, THC. <i>4, 127,</i> emmener l’armée ;<br><b>      5</b> laisser aller en dessous, faire évacuer par en bas : τὴν κοιλίην, ARÉT. <i>Cur. m. acut. 1, 10,</i> relâcher le ventre ; <i>d’où intr. :</i> κοιλία ὑπάγουσα, HPC. <i>396, 20,</i> ventre libre ;<br><b>B <i>intr. :</i><br>   I</b> se retirer, <i>d’où :</i><br><b>      1</b> s’éloigner discrètement, se retirer sans bruit, AR. <i>Av. 1017 ;</i><br><b>      2</b> se retirer pas à pas, <i>en parl. d’une armée,</i> HDT. <i>4, 120, 122 ; d’un gibier qui se retire devant le chasseur,</i> ARSTT. <i>H.A. 9, 44 ;</i><br><b>      3</b> <i>abs</i>. se retirer : τῆς ὁδοῦ, AR. <i>Ran. 174,</i> du chemin ;<br><b>   II</b> s’affaisser, s’accroupir, ARSTT. <i>H.A. 5, 2 ;</i><br><b>   III</b> s’avancer peu à peu, <i>en parl. d’une armée,</i> XÉN. <i>An. 3, 4, 48 ; 4, 2, 16 ; en gén</i>. suivre son chemin tranquillement, <i>fig. càd</i>. se laisser vivre, vivre sans souci, THGN. <i>921 ; p. ext</i>. s’avancer : ὕπαγε εἰς τοὔμπροσθεν, EUP. (AMM. <i>p. 140), ou simpl</i>. ὕπαγε, AR. <i>Nub. 1298 ;</i> ὕπαγ' ὦ, ὕπαγ' ὦ, EUR. <i>Cycl. 52,</i> avance ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. ὑπάξομαι, <i>ao.2</i> ὑπηγαγόμην)</span><br><b>      1</b> soumettre à sa puissance, soumettre, THC. <i>7, 46 ;</i> EUR. <i>El. 1155 ;</i> LUC. <i>D. deor. 18, 1 ; D. mar. 8, 1, etc. ;</i><br><b>      2</b> amener insensiblement avec soi, emmener peu à peu, <i>acc</i>. DH. <i>13, 1 ; d’où</i> égarer, séduire, ISOCR. <i>100</i> d ; <i>avec l’inf</i>. XÉN. <i>An. 2, 4, 3 ;</i><br><b>      3</b> amener à soi : τινα, EUR. <i>Andr. 906,</i> amener qqn (à un sujet) ; <i>p. suite,</i> attirer dans son parti, gagner à sa cause, <i>acc</i>. DÉM. <i>105, 7 ;</i> ἐς φιλίαν, DC. <i>42, 39,</i> se concilier l’amitié de qqn ; τινα εἴς τι, HDN <i>6, 2, 3 ;</i> ἐπί τι, HDN <i>2, 9, 14,</i> amener qqn à qqe ch. ;<br><b>      4</b> suggérer pour soi, insinuer <i>ou</i> conseiller dans son propre intérêt, <i>acc</i>. XÉN. <i>An. 2, 1, 18</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπαγω - ὑπάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n80 fois dans 76 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (15)</li>\n<li>Luc (5)</li>\n<li>Jean (33)</li>\n<li>Jacques (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G5218":"<h1>hupakoe</h1>\n<p>Strong n° 5218 <i>Prononciation [hoop-ak-o-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>obéissance, acquiescement, soumission</li>\n<li>obéissance apportée à des conseils, une obéissance montrée par l'observation des commandements du Christianisme</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπακοή, ῆς (ἡ)</b> <span>[ῠᾰ]</span> obéissance, soumission, NT. <i>Rom. 5, 19</i>.<br><span><b>Étym</b>. ὑπακούω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπακοη - ὑπακοή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 14 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (7)</li>\n<li>2 Corinthiens (3)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G5219":"<h1>hupakouo</h1>\n<p>Strong n° 5219 <i>Prononciation [hoop-ak-oo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>écouter, prêter l'oreille à\n<ol type=\"a\">\n<li>de quelqu'un qui vient à la porte pour savoir qui a frappé (la fonction d'un portier)</li>\n</ol>\n</li>\n<li>être attentif à un ordre\n<ol type=\"a\">\n<li>obéir à, être obéissant, se soumettre à</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·ακούω</b> <span>(<i>f</i>. ὑπακούσομαι)</span> <span>[ῠᾰ]</span><br><b>   I</b> écouter en baissant la tête, prêter l’oreille, OD. <i>14, 485 ;</i> HH. <i>Ven. 181 ;</i> EUR. <i>Alc. 402 ;</i> THCR. <i>Idyl. 7, 95, etc. ;</i> τινός, AR. <i>Vesp. 319, etc. ;</i> ESCHN. <i>61, 32 ;</i> τινί, AR. <i>Lys. 878, etc</i>. baisser la tête pour écouter qqn <i>ou</i> qqe ch. ; <i>particul. :</i><br><b>      1</b> <i>en parl. du portier qui prête l’oreille pour ouvrir,</i> XÉN. <i>Conv. 1, 11 ;</i> PLAT. <i>Phæd. 59</i> e, <i>Crit. 43</i> a ; TH. <i>Char. 4 ;</i> NT. <i>Ap. 12, 13, etc. ;</i><br><b>      2</b> <i>en gén. en parl. d’une pers. qui prête l’oreille pour écouter et répondre,</i> OD. <i>4, 283 ; 10, 83 ;</i> AND. <i>15, 12, 19 ;</i> THCR. <i>Idyl. 13, 59 ;</i><br><b>      3</b> <i>en parl. du juge,</i> prêter l’oreille : τινί, XÉN. <i>Cyr. 8, 1, 18,</i> pour écouter qqn ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> répondre à une invitation, obéir à une sommation de comparaître devant un tribunal, se présenter en justice, DÉM. <i>423, 17 ; 434, 15 ;</i> ESCHN. <i>7, 21, 33 ;</i> IS. <i>49, 25 ;</i> PLUT. <i>Sol. 31, etc. ;</i><br><b>      2</b> écouter, obéir, HDT. <i>3, 148, etc. ;</i> THC. <i>1, 141 ;</i> XÉN. <i>An. 4, 1, 9, etc. ;</i> ὑπ. τινός, HDT. <i>3, 101 ;</i> THC. <i>2, 62, etc. ;</i> XÉN. <i>Cyr. 8, 1, 20 ;</i> τινί, THC. <i>6, 69 ;</i> XÉN. <i>Cyr. 1, 1, 3 ; 3, 3, 11, etc</i>. obéir à qqn, être soumis à qqn ; <i>avec l’inf</i>. DS. <i>Exc. p. 568, 86 ; avec un n. de chose pour rég. :</i> ὑπ. νόμων, PLAT. <i>Leg. 708</i> d, <i>etc. ;</i> ὑπ. νόμοις, ESCHN. <i>7, 33, etc</i>. obéir aux lois ; ὑπ. δείπνῳ, ATH. <i>247</i> d, accepter une invitation à souper ; <i>fig</i>. ὑπ. τῷ ξυμφόρῳ τινός, THC. <i>5, 98,</i> se conformer à l’intérêt de qqn ; <i>p. anal</i>. céder à une impression : τὸ ἀγγεῖον ὑπ. πληγαῖς, PLUT. <i>M. 721</i> b, le vase résonne sous les coups ; τὸ μυθῶδες ὑπ. λόγῳ, PLUT. <i>Thes. 1,</i> ce qui est fabuleux cède à ce qui est raisonnable ; <i>en parl. de maladies :</i> ὑπ. τινί, HPC. <i>1086</i> b, <i>etc</i>. céder à l’emploi d’un remède ; <i>abs</i>. céder, diminuer, HPC. <i>112</i> a ;<br><b>      3</b> <i>p. suite,</i> condescendre à, se prêter à, se montrer favorable à : πρός τι, DS. <i>12, 75, etc. ;</i> εἴς τι, POLYEN <i>1, 27, 3,</i> à qqe ch. ; <i>avec un acc. neutre :</i> τοῦτο, XÉN. <i>Cyr. 2, 2, 3,</i> condescendre à cela ; οὐδέν, THC. <i>1, 29, 139, etc</i>. ne consentir à rien ; <i>avec double rég. :</i> τί τινος, THC. <i>1, 26 ;</i> PLAT. <i>Lach. 200</i> c ; τί τινι, PLAT. <i>Leg. 774</i> d, se montrer favorable à qqn pour qqe ch. ; <i>p. suite, avec un suj. de chose,</i> s’adapter à, s’arranger favorablement : τὸ πρᾶγμα ὑπ. τινί, LUC. <i>Ic. 10,</i> l’affaire marche convenablement ; ἡ μεταλλεία ὑπ. STR. <i>399,</i> la mine promet du bénéfice ;<br><b>      4</b> s’exposer à : αὐγαῖς ἁλίου, PD. <i>O. 3, 44,</i> aux rayons du soleil ; τῷ ἀέρι, TH. <i>C.P. 2, 12, 1,</i> à l’air ; <i>avec le gén. :</i> ὑπ. τοῦ ψύχους, TH. <i>C.P. 5, 4, 2,</i> au froid ;<br><b>   III</b> comprendre à demi-mot, <i>càd. :</i><br><b>      1</b> entendre par : κοινὸν ὑπακούωμεν, PLAT. <i>Phil. 31</i> c, par le commun entendons (ceci et cela) ; <i>cf</i>. PLUT. <i>M. 23</i> c, <i>etc. ;</i><br><b>      2</b> <i>t. de gr</i>. suppléer par la pensée, sous-entendre, DYSC. <i>Synt. p. 27, 23</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπακουω - ὑπακούω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 21 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>Romains (5)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5220":"<h1>hupandros</h1>\n<p>Strong n° 5220 <i>Prononciation [hoop'-an-dros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sous, c.à.d. sujette à un homme, mariée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕπ·ανδρος, ος, ον</b> <span>[ῠ]</span><br><b>      1</b> en pouvoir de mari, mariée, POL. <i>10, 26, 3 ;</i> PLUT. <i>Pel. 9 ;</i> ATH. <i>388</i> c ;<br><b>      2</b> de femme, efféminé, DS. <i>Exc. 520, 39</i>.<br><span><b>Étym</b>. ὑ. ἀνήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπανδρος - ὕπανδρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5221":"<h1>hupantao</h1>\n<p>Strong n° 5221 <i>Prononciation [hoop-an-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller à la rencontre, rencontrer</li>\n<li>dans une référence militaire\n<ol type=\"a\">\n<li>d'une rencontre hostile</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·αντάω-ῶ</b> <span>(<i>f</i>. -ήσομαι, <i>ao</i>. ὑπήντησα, <i>etc</i>.)</span> <span>[ῠ]</span><br><b>   I</b> <i>en b. part :</i><br><b>      1</b> <i>au propre,</i> aller à la rencontre de, rencontrer : τινι, PD. <i>P. 8, 84 ;</i> XÉN. <i>Cyr. 3, 3, 2 ;</i> PLUT. <i>Arat. 34 ;</i> τινος, SOPH. <i>Ph. 719,</i> qqn ;<br><b>      2</b> <i>fig</i>. s’accorder avec, <i>dat</i>. POSIDON. (ATH. <i>213</i> b) ;<br><b>   II</b> <i>avec idée d’hostilité :</i><br><b>      1</b> marcher à la rencontre de, XÉN. <i>Cyr. 1, 4, 22 ; 4, 2, 17, etc. ;</i><br><b>      2</b> s’opposer à, aller à l’encontre de, objecter : πρός τι, SEXT. <i>M. 10, 105,</i> à qqe ch. ;<br><b><i>Moy.</i></b> aller à la rencontre de, rencontrer, <i>dat</i>. HDN <i>2, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. dor</i>. ὑπάντασα <span>[τᾱ]</span> PD. <i>P. 8, 84</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπανταω - ὑπαντάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G5222":"<h1>hupantesis</h1>\n<p>Strong n° 5222 <i>Prononciation [hoop-an'-tay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aller à la rencontre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπάντησις, εως (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> rencontre, APP. <i>Civ. 4, 6 ;</i><br><b>      2</b> opposition, SEXT. <i>M. 2, 278</i>.<br><span><b>Étym</b>. ὑπαντάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπαντησις - ὑπάντησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5223":"<h1>huparxis</h1>\n<p>Strong n° 5223 <i>Prononciation [hoop'-arx-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>possessions, biens, richesse, propriété</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕπαρξις, εως (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> existence, ARSTT. <i>Plant. 1, 2, 16 ;</i> PLUT. <i>M. 1067</i> c ; SEXT. <i>P. 1, 21 ;</i><br><b>      2</b> moyens d’existence, fortune, richesses, POL. <i>2, 17, 11 ;</i> DH. <i>7, 8 ;</i> DS. <i>20, 71 ;</i> PLUT. <i>M. 226</i> c, <i>etc. ;</i><br><b>      3</b> <i>t. de math</i>. grandeur positive, DIOPH. <i>Arithm. 1, 9 ;</i><br><b>      4</b> <i>p. ext</i>. substance, SEXT. <i>P. 1, 129</i>.<br><span><b>Étym</b>. ὑπάρχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπαρξις - ὕπαρξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5224":"<h1>huparchonta</h1>\n<p>Strong n° 5224 <i>Prononciation [hoop-ar'-khon-tah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>possessions, biens, richesse, propriété</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπαρχοντα - ὑπάρχοντα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (8)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5225":"<h1>huparcho</h1>\n<p>Strong n° 5225 <i>Prononciation [hoop-ar'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>commencer en bas, faire un commencement\n<ol type=\"a\">\n<li>commencer</li>\n</ol>\n</li>\n<li>venir, de là être ici, être prêt, à portée de main</li>\n<li>être</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·άρχω</b> <span>[ῠ]</span><br><b>A</b> (ἄρχω, commencer) ;<br><b>   I <i>tr.</i></b> commencer : ὅστις ὑπάρξῃ, OD. <i>24, 286,</i> celui qui commencerait ; παιδοϐόροι πρῶτον ὑπῆρξαν μόχθοι, ESCHL. <i>Ch. 1069,</i> le massacre des enfants qui furent dévorés fut le commencement ; <i>cf</i>. PLAT. <i>Conv. 198</i> d, <i>1 Alc. 119</i> d, <i>etc. ; avec le gén. :</i> ὑπάρχειν ἀδίκων ἔργων, HDT. <i>1, 5 ;</i> ἀδικίης, HDT. <i>7, 9 ;</i> τῆς ἀδικίας, THC. <i>2, 74,</i> prendre l’initiative d’un tort fait à qqn, faire tort le premier ; <i>abs</i>. ὑπάρχων ἠδίκεις αὐτούς, ISOCR. <i>356</i> a, c’est toi qui as commencé à leur faire tort ; ἀμύνεσθαι τοὺς ὑπάρξαντας, LYS. <i>169, 44,</i> se défendre contre ceux qui ont commencé ; ἀμυνομένους, μὴ ὑπάρχοντας, PLAT. <i>Gorg. 456</i> e, se défendant, ne commençant pas ; <i>en b. part :</i> ὑπῆρξαν τῆς ἐλευθερίας ἁπάσῃ τῇ Ἑλλάδι, AND. <i>18, 34,</i> ils donnèrent à toute la Grèce l’impulsion vers la liberté ; τῆς εὐγενείας πρῶτον ὑπῆρξε τοῖσδε ἡ τῶν προγόνων γένεσις, PLAT. <i>Menex. 237</i> b, l’origine des ancêtres était le commencement de leur noblesse ; <i>rar. avec l’acc. :</i> τὰς εὐεργεσίας ἃς ὑπῆρξαν εἰς ὑμᾶς, DÉM. <i>431, 16,</i> les bienfaits dont ils ont pris l’initiative envers vous ; <i>cf</i>. ISOCR. <i>307</i> d ; ESCHN. <i>31, 31 ; au pass</i>. ὑπῆρκτο αὐτοῦ, THC. <i>1, 93,</i> on en avait déjà commencé une partie (du Pirée) ; τὰ ὑπαργμένα (<i>ion. pour</i> ὑπηργμένα) ἔκ τινος, HDT. <i>7, 11,</i> ce qui est commencé par qqn, les premiers essais de qqn ; οὐδέν μοι ὑπῆρκτο εἰς αὐτόν, ANT. <i>136, 13,</i> je ne l’avais pas offensé le premier ; αἱ ὑπηρεσίαι αἱ ὑπηργμέναι εἰς Φίλιππον αὐτῷ, ESCHN. <i>42, 23,</i> les services qu’il a rendus à Philippe ; τὰ παρὰ τῶν θεῶν ὑπηργμένα, DÉM. <i>12, 1,</i> les bienfaits que les dieux nous ont les premiers accordés ; <i>avec le part</i>. ἐμὲ ὑπῆρξαν ἄδικα ποιοῦντες, HDT. <i>7, 8,</i> ils m’ont fait tort les premiers ; <i>cf</i>. HDT. <i>9, 78 ;</i> XÉN. <i>An. 2, 3, 23, etc. ; avec un dat. instrum. :</i> τοῖς αὐτοῖς ἀμύνεσθαι οἷσπερ καὶ οἱ Λακεδαιμόνιοι ὑπῆρξαν, THC. <i>2, 67,</i> se venger en faisant les mêmes maux dont les Lacédémoniens avaient pris l’initiative, <i>càd</i>. que les Lacédémoniens avaient commis les premiers ;<br><b>   II</b> commencer en bas, sortir du fond ; <i>d’où en gén</i>. sortir, naître, résulter de : ἡ ὑπάρχουσα αἰσχύνη, DÉM. <i>408, 22 ;</i> la honte qui en résulte ; τὸ μισεῖσθαι πᾶσιν ὑπ. THC. <i>2, 64,</i> être haï échoit à tous ceux qui, <i>etc. ;</i> ἡ ὑπάρχουσα ἀπ' ἀλλήλων ἀμφοτέροις σωτηρία, THC. <i>6, 86,</i> la sécurité que nous nous procurons mutuellement, <i>càd</i>. qui résulte de notre union ;<br><b>   III</b> être le fondement, <i>d’où :</i><br><b>      1</b> être, exister antérieurement : πημονῆς ἅλις γ' ὑπάρχει, ESCHL. <i>Ag. 1656,</i> voilà assez de désastres ; πολλαὶ ὑπάρχουσιν ἡμῖν εὐεργεσίαι ἐς τὴν πόλιν, ISOCR. <i>53</i> a, il existe de notre part beaucoup de services envers l’État, nous avons fait beaucoup de bien à l’État ; οὔτε πρὸς τὴν πόλιν αὐτοῖς τοιαῦτα ὑπ. οὔτε πρὸς ἐμέ, LYS. <i>122, 13,</i> il n’y a de tels services de leur part ni envers l’État ni envers moi ; ταῦτα ὑπῆρχε Βοιωτοῖς καὶ Θηϐαίοις πρὸς ἀλλήλους, PLUT. <i>M. 866</i> f, telle était la situation des Béotiens et des Thébains les uns vis-à-vis des autres ;<br><b>      2</b> <i>par suite,</i> être sous la main, être à la disposition : ἡ ὑπάρχουσα οὐσία, ISOCR. <i>8</i> a, le bien existant, qu’on a à sa disposition ; αἱ νέες τοῖσι Ἀθηναίοισι προποιηθεῖσαι ὑπῆρχον, HDT. <i>7, 144,</i> les navires construits auparavant par les Athéniens se trouvaient disponibles ; τά γ' ἀφ' ὑμῶν ὑπάρχει, DÉM. <i>103, 6,</i> au moins ce qui vient de vous est prêt, <i>càd</i>. de votre part il n’y a pas d’obstacle ; <i>part. plur</i>. τὰ ὑπάρχοντα, ce qui est sous la main, à la disposition : τῶν μὲν ὑπαρχόντων ἀμελεῖν, τῶν δὲ ἀπόντων ἐπιθυμεῖν, THPP. COLOPH. (ATH. <i>261</i> a) être indifférent à ce qu’on a, désirer ce qu’on n’a pas ; τὰ ἑκατέροις ὑπάρχοντα, THC. <i>1, 141,</i> les ressources dont chacun des deux partis disposait ; ἀπὸ τῶν ὑπαρχόντων, THC. <i>6, 33,</i> avec les moyens dont on dispose ; <i>de même</i> τὰ ὑπ. les exemples qu’on a sous les yeux, DÉM. <i>258, 2 ; ou</i> ce qu’on possède, le bien, la fortune, PLUT. <i>Them. 5, Æmil. 4, etc. ;</i> ὑπάρχει μοι <i>avec l’inf</i>. il est à ma disposition de, il m’est accordé, permis <i>ou</i> possible de, <i>etc</i>. THC. <i>5, 9 ; 7, 63 ;</i> XÉN. <i>Cyr. 8, 8, 20 ;</i> PLAT. <i>Phædr. 240</i> b, <i>269</i> d, <i>etc. ;</i> DÉM. <i>312, 22 ;</i> PLUT. <i>Marc. 6, etc. ; sans dat</i>. οὐχ ὑπάρχει εἰδέναι, THC. <i>1, 82,</i> il n’est pas possible de savoir, <i>etc. ; cf</i>. SOPH. <i>El. 1340 ;</i> XÉN. <i>Ath. 3, 9, etc. ; abs. au part. neutre :</i> πανταχόθεν ὑπάρχον ὑμῖν πολεμεῖν, THC. <i>1, 124,</i> tout vous conviant à faire la guerre ; <i>cf</i>. PLAT. <i>Conv. 217</i> a ; <i>particul</i>. ὑπάρχειν τινί, être à la disposition de qqn, <i>càd</i>. être prêt à servir qqn, lui être dévoué, lui être utile, l’assister, XÉN. <i>An. 1, 1, 4 ; 5, 6, 23, etc. ;</i> DÉM. <i>358, 7 ; 384, 25 ;</i> ὑπ. τινὶ πρός τινα, DÉM. <i>22, 5 ; ou</i> κατά τινος, DÉM. <i>377, 10,</i> aider qqn contre qqn ;<br><b>      3</b> <i>abs</i>. être réel, <i>p. opp. à</i> φαίνεσθαι, SEXT. <i>p. 53 ;</i><br><b>      4</b> <i>en gén. c</i>. εἶναι, être : τούτου ὑπάρχοντος, PLAT. <i>Tim. 30</i> c, cela étant, puisqu’il en est ainsi ; τοῖσιν ἄγουσιν κλαύμαθ' ὑπάρξει, SOPH. <i>Ant. 932,</i> pour ceux qui la conduisent il y aura des pleurs ; <i>avec un attrib. :</i> τὸ πλέον τοῦ χωρίου καρτερὸν αὐτὸ ὑπῆρχε, THC. <i>4, 4,</i> la plus grande partie du pays était naturellement fortifiée ; πάντες ὑπάρχουσί μοι μάρτυρες, PLAT. <i>Ep. 309</i> a, tous me sont témoins ; μέγα ὑπάρχειν, ATT. pouvoir beaucoup, contribuer beaucoup : τινί, DÉM. <i>33, 27,</i> dans qqe ch. ; πρός τι, PLUT. <i>Pomp. 14,</i> pour qqe ch. ; ὑπάρχειν τινός, DH. <i>4, 65,</i> descendre de qqn ; ὥσπερ ὑπῆρχε, THC. <i>3, 109,</i> comme cela se trouvait, <i>càd</i>. selon les circonstances ; <i>part</i>. ὑπάρχων, ουσα, ον, ce qui se trouve, ce qui existe : τὰ ὑποκείμενα ἀποδόσθαι τῆς ὑπαρχούσης τιμῆς, DÉM. <i>926, 24,</i> livrer les marchandises en dépôt au prix courant ; <i>part. plur</i>. τὰ ὑπάρχοντα, l’état actuel, la situation présente, les circonstances existantes, DÉM. <i>18, 12 ;</i> ἀπὸ τῶν ἀεὶ ὑπαρχόντων, THC. <i>4, 18,</i> par la suite des circonstances, <i>càd</i>. des événements ; <i>de même</i> πρὸς τὰ ὑπάρχοντα, THC. <i>6, 31 ;</i> ἐκ τῶν ὑπαρχόντων, THC. <i>7, 76 ;</i> XÉN. <i>An. 6, 4, 9 ; ou</i> τὰ ὑπάρχοντα, la puissance existante, DÉM. <i>102, 2 ; p. suite,</i> ὑπάρχω <i>avec un part. au sens de</i> τυγχάνω : ἐχθρὸς ὑπῆρχεν ὤν, DÉM. <i>526, 18,</i> il se trouvait avoir des sentiments d’inimitié ; <i>cf</i>. DÉM. <i>30, 15 ; 190 fin, etc. ;</i> PLUT. <i>Artax. 2, etc. ;</i><br><b>B</b> (ἄρχω, commander) :<br><b>      1</b> commander sous les ordres de qqn <i>ou</i> à la place de qqn, <i>d’où à Rome,</i> être lieutenant : τινί, DC. <i>36, 19 ; 71, 34,</i> de qqn ;<br><b>      2</b> <i>en gén</i>. commander à, dominer sur, <i>dat</i>. THC. <i>6, 87 ;</i><br><b>C</b> <b><i>Moy.</i></b> <span>(<i>f</i>. ὑπάρξομαι, <i>ao</i>. ὑπηρξάμην)</span><br><b>      1</b> commencer, être à son commencement : ὑπαρχομένου τοῦ ἦρος, EL. <i>N.A. 4, 34,</i> au commencement du printemps ;<br><b>      2</b> commencer, prendre l’initiative, <i>avec le gén</i>. EL. <i>N.A. 1, 20 ; avec l’inf</i>. EL. <i>N.A. 4, 11 ;</i> ὑπάρξασθαι φαίνεται, GAL. il semble avoir été le premier à s’en occuper.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπαρχω - ὑπάρχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n48 fois dans 47 versets de 9 livres bibliques (NT)\n<ul>\n<li>Luc (7)</li>\n<li>Actes (26)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (2)</li>\n<li>Philippiens (2)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G5226":"<h1>hupeiko</h1>\n<p>Strong n° 5226 <i>Prononciation [hoop-i'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ne pas résister plus longtemps, laisser le chemin, céder (de combattants)</li>\n<li>métaph. se soumettre aux autorités et aux avertissements</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπείκω</b> <span>(<i>impf</i>. ὑπεῖκον, <i>f</i>. -είξω <i>et</i> -είξομαι, <i>ao</i>. ὑπεῖξα)</span><br><b>      1</b> céder la place, se retirer : νεῶν, IL. <i>16, 305,</i> des vaisseaux ; τινὶ ἕδρης, OD. <i>16, 42,</i> céder son siège à qqn ; τινὶ λόγων, XÉN. <i>Mem. 2, 3, 16,</i> laisser parler qqn avant soi ;<br><b>      2</b> céder à, obéir à, <i>dat</i>. XÉN. <i>An. 7, 7, 31 ;</i> SOPH. <i>Aj. 670 ; en gén</i>. céder, XÉN. <i>Eq. 7, 6 ; Cyr. 8, 8, 16, etc. ;</i><br><b>      3</b> condescendre à, <i>dat</i>. OD. <i>12, 117, etc. ; en prose att</i>. PLAT. <i>Leg. 717</i> d, <i>etc. ;</i> τι ἀλλήλοισι, IL. <i>4, 62,</i> se faire des concessions mutuelles en qqe ch. ; τινί τι, IL. <i>1, 294,</i> condescendre à qqn en qqe ch., accorder qqe ch. à qqn ; <i>cf</i>. DÉM. <i>197 fin ; avec l’inf</i>. se résigner à, A. RH. <i>4, 1678 ; ou</i> cesser de, A. RH. <i>4, 408 ; avec une prop. inf. :</i> ὕπεικε τὸν κασίγνητον μολεῖν, SOPH. <i>O.C. 1184,</i> permets que notre frère vienne ; <i>abs</i>. IL. <i>15, 211 ; 20, 266, etc. ;</i> SOPH. <i>Aj. 371, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Épq</i>. ὑποείκω, IL. <i>20, 266 ; impf</i>. ὑπόεικον, IL. <i>16, 305 ;</i> A. RH. <i>2, 1266 ; f</i>. ὑποείξω, IL. <i>4, 62 ; 15, 211 ;</i> ὑπείξομαι, IL. <i>1, 294 ; 23, 602 ; 2 sg. épq</i>. ὑπείξεαι, OD. <i>12, 117 ; ao. 3 sg</i>. ὑπόειξε, IL. <i>15, 227 ; d’où sbj. 1 pl. épq</i>. ὑποείξομεν, IL. <i>4, 62</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπεικω - ὑπείκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5227":"<h1>hupenantios</h1>\n<p>Strong n° 5227 <i>Prononciation [hoop-en-an-tee'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>opposé à\n<ol type=\"a\">\n<li>réunion avec quelqu'un d'autre que prévu</li>\n</ol>\n</li>\n<li>contraire à, un adversaire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·εναντίος, ος, ον</b>, placé en face de, à l’opposite, <i>d’où :</i><br><b>      1</b> qui tient tête à, qui va à l’encontre de, qui rencontre, <i>dat</i>. HÉS. <i>Sc. 347 ;</i><br><b>      2</b> opposé à, <i>dat</i>. THC. <i>2, 2 ;</i> PLAT. <i>2 Alc. 138</i> c ; <i>subst</i>. οἱ ὑπεναντίοι, XÉN. <i>Cyr. 1, 6, 38,</i> l’ennemi ; <i>de même avec πρός et l’acc</i>. ARSTT. <i>Pol. 7, 9, 3 ;</i><br><b>      3</b> opposé, contraire, HPC. <i>V. med. 13 ;</i> PLAT. <i>Pol. 306</i> e ; <i>avec le dat</i>. contraire à, HDT. <i>7, 50 ;</i> XÉN. <i>Hell. 4, 8, 24 ;</i> PLAT. <i>Theæt. 176</i> a, <i>etc. ;</i> τὸ ὑπεναντίον, HDT. <i>3, 80,</i> le contraire ; τὰ ὑπεναντία, ARSTT. <i>Poet. 17, 1 ; 25, 30,</i> les contraires ; <i>adv</i>., ὑπεναντία <i>avec le dat</i>. contre (<i>inscr. de 324 av. J.C.) ; v. Meisterh. p. 176, 23</i>.<br><span>•<i> Sup</i>. ὑπεναντιώτατος, ALEX. (<i>Com. fr. 3, 446</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -α, PLUT. <i>Ages. 24</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπεναντιος - ὑπεναντίος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5228":"<h1>huper</h1>\n<p>Strong n° 5228 <i>Prononciation [hoop-er']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en faveur de, pour l'amour de</li>\n<li>au delà de, plus de</li>\n<li>plus, au delà, au-dessus de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπέρ</b> <span>[ῠ]</span> <i>adv. et prép. :</i><br><b>A</b> <i>adv</i>., au-dessus : ὑπὲρ μὲν ἄγαν, EUR. <i>Med. 627,</i> beaucoup trop ; <i>écrit</i> ὑπεράγαν, STR. <i>147 ;</i> EL. <i>N.A. 3, 38, etc. ; postér. en prose :</i> διάκονοι Χριστοῦ εἰσιν ; ὑπὲρ ἐγώ, NT. <i>2Cor. 11, 23,</i> ils sont serviteurs du Christ ? eh bien moi encore plus ;<br><b>B</b> <i>prép. avec le gén. et l’acc. :</i> au-dessus de, sur : <i>avec le gén. :</i><br><b>   I</b> au-dessus de, <i>càd. :</i><br><b>      1</b> sur, <i>sans mouv. : avec idée de contact,</i> ἕστηκε ξύλον αὖον ὑπὲρ αἴης, IL. <i>23, 327,</i> au-dessus du sol, <i>càd</i>. émergeant du sol se dresse une tige sèche ; ὑπὲρ γῆς, au-dessus de la terre, sortant du sol, TH. <i>C.P. 3, 3, 1, etc. ; p. opp. à</i> ἐπὶ γῆς <i>et à</i> ὑπὸ γῆς, TH. <i>Ign. § 1 ; c</i>. ἐπὶ γῆς, sur la terre, LUC. <i>Luct. 9, Cat. 9, etc. ;</i> Σικελοὶ οἱ ὑπὲρ τῶν ἄκρων, THC. <i>4, 25,</i> ceux des Sicules qui occupaient les hauteurs ; ὑπὲρ κεφαλῆς, IL. <i>2, 20,</i> au-dessus de sa tête, au haut de sa tête ; στέρνον ὑπὲρ μαζοῖο, IL. <i>4, 528,</i> la poitrine au-dessus du sein ; πασάων δ' ὕπερ ἥ γε κάρη ἔχει, OD. <i>6, 107,</i> elle dépasse toutes les autres de la tête ; ὑπὲρ πόλιος ἦα κιών, OD. <i>16, 471,</i> j’étais dans ma marche sur les hauteurs qui dominent la ville ; ὑπὲρ τῆς κώμης γήλοφος ἦν, XÉN. <i>An. 1, 10, 11,</i> au-dessus du village s’élevait une colline ; <i>avec mouv. : avec ou sans contact,</i> au-dessus de, par-dessus : κῦμα νηὸς ὑπὲρ τοίχων καταϐήσεται, IL. <i>15, 382,</i> le flot se précipite par-dessus les parois du vaisseau ; τοξεύειν ὑπὲρ τῶν πρόσθεν, XÉN. <i>Cyr. 6, 3, 24,</i> lancer des flèches par-dessus les rangs de devant ; ἐκκυϐιστᾶν ὑπὲρ τῶν ξιφῶν, XÉN. <i>Conv. 2, 11,</i> faire la culbute par dessus les épées ; τάφρων ὕπερ πηδᾶν, SOPH. <i>Aj. 1279,</i> sauter par-dessus des fossés ;<br><b>      2</b> par-dessus, de l’autre côté de, au delà de : τηλοῦ ὑπὲρ πόντου, OD. <i>13, 257,</i> loin au delà de la mer ; <i>de même avec le gén., en prose réc. :</i> ὑπὲρ ποταμοῦ οἰκεῖν, DC. <i>36, 37,</i> habiter de l’autre côté du fleuve (<i>cf. ci-dessous</i> ὑπέρ <i>avec l’acc</i>.) ;<br><b>      3</b> <i>en gén</i>. au delà, plus loin (dans l’intérieur d’un pays) : Αἰθιοπία ἡ ὑπὲρ Αἰγύπτου, THC. <i>2, 48,</i> l’Éthiopie au-dessus (<i>ou</i> au delà) de l’Égypte ; <i>cf</i>. HDT. <i>1, 175 ;</i> THC. <i>1, 104, etc. ;</i> XÉN. <i>An. 2, 6, 2, etc. ;</i><br><b>   II</b> pour, <i>càd. :</i><br><b>      1</b> pour la défense de (<i>sens qui se rattache au préc., l’idée de défense impliquant celle de combattants qui couvrent de leurs bras ou de leur armure un compagnon d’armes, ou de retranchements une ville assiégée ; cf. une relation d’idées semblable pour</i> ἀμφί, περί, πρό) : τεῖχος τειχίσασθαι νεῶν ὕπερ, IL. <i>7, 449 ; ou</i> ποιήσασθαι, IL. <i>12, 12,</i> établir un retranchement pour protéger le camp, pour le camp ; ἀντιστῆναι ὑπὲρ γῆς, SOPH. <i>Ant. 518,</i> défendre le pays ; μάχεσθαι ὑπέρ τινος, PLAT. <i>Ap. 32</i> b, <i>etc</i>. combattre pour qqn <i>ou</i> qqe ch. ; κινδυνεύειν ὑπέρ τινος, THC. <i>2, 20, etc</i>. s’exposer à un danger pour qqe chose ; βοηθεῖν ὑπὲρ τῆς χώρας, XÉN. <i>An. 3, 5, 4,</i> venir au secours du pays ; θνῄσκειν <i>ou</i> ἀποθνῄσκειν ὑπέρ τινος, SOPH. <i>Tr. 708 ;</i> EUR. <i>Hec. 314 ;</i> PLAT. <i>Conv. 179</i> b, <i>etc</i>. mourir pour qqn <i>ou</i> qqe ch. ; <i>p. anal</i>. ὁ ὑπέρ τινος λόγος, PLAT. <i>Rsp. 359</i> c, apologie de qqn ; λέγειν ὑπέρ τινος, XÉN. <i>An. 5, 5, 13 ;</i> SOPH. <i>El. 554, etc</i>. parler en faveur de qqn, parler pour qqn (<i>v. ci-dessous un autre sens</i> II, 2) ; ἑκατόμϐην ῥέξαι ὑπέρ τινος, IL. <i>1, 444,</i> offrir une hécatombe pour qqn ; θύειν ὑπέρ τινος, XÉN. <i>Mem. 2, 2, 13,</i> offrir un sacrifice en faveur de qqn ; <i>en ce sens dans les inscr. att. :</i> ἄρχοντες ὁπόσοι ὑπὲρ τοῦ κοινοῦ τῶν Θετταλῶν ἄρχουσιν (<i>inscr. de 369 av. J.C</i>.) tous les magistrats qui gèrent les intérêts communs des Thessaliens ; <i>v. Meisterh. p. 182, 49 ;</i><br><b>      2</b> à la place de, au nom de : λέγειν ὑπέρ τινος, XÉN. <i>An. 5, 5, 13,</i> parler pour qqn, au nom de qqn ; ἀποκρίνεσθαι ὑπέρ τινος, PLAT. <i>Rsp. 590</i> a, répondre au nom de qqn, pour qqn ; προλέγειν ὑπέρ τινος, XÉN. <i>An. 7, 7, 3,</i> annoncer au nom de qqn ; <i>cf</i>. PLAT. <i>Menex. 248</i> e, <i>Crit. 45</i> e, <i>etc. ; chez les écriv. réc. au lieu de</i> ἀντί, EL. <i>N.A. 4, 26 ; 7, 42 ;</i><br><b>      3</b> à cause de : εὐδαιμονίζειν τινὰ ὑπέρ τινος, XÉN. <i>An. 1, 7, 3,</i> estimer qqn heureux à cause de qqe ch. ; φοϐεῖσθαι <i>ou</i> δεδιέναι ὑπέρ τινος, SOPH. <i>O.R. 989 ;</i> PLAT. <i>Rsp. 387</i> c, <i>etc</i>. être inquiet, soucieux pour qqn <i>ou</i> qqe ch. ; θαρρεῖν ὑπέρ τινος, XÉN. <i>Cyr. 7, 1, 17,</i> être sans inquiétude pour qqn ; ἀγανακτεῖν ὑπέρ τινος, PLAT. <i>Phæd. 115</i> e, être hors de soi à cause de qqn ; στένειν ὑπέρ τινος, ESCHL. <i>Pr. 66,</i> gémir de qqe ch. ; <i>avec des verbes impliquant l’idée d’une peine ou d’une récompense :</i> δίκην δοῦναι ὑπέρ τινος, ATT. être puni pour qqe ch. ; δίκην λαϐεῖν ὑπέρ τινος, ATT. punir pour qqe ch. ; τιμωρεῖν τινα ὑπέρ τινος, LYS. <i>13, § 41 et 42 ; ou</i> τιμωρεῖσθαί τινα ὑπέρ τινος, XÉN. <i>An. 1, 3, 4,</i> punir qqn pour qqe ch. ; χάριν ἀποδοῦναι ὑπέρ τινος, ISOCR. <i>Evag. § 56,</i> se montrer reconnaissant pour qqe ch. ; τιμᾶν τινα ὑπέρ τινος, ISOCR. <i>Evag. § 57,</i> rendre honneur à qqn pour qqe ch. ; <i>de même avec les verbes impliquant une idée d’effort, pour désigner ce que l’on s’efforce d’obtenir ou ce dont on veut préserver :</i> νῦν ὑπὲρ πάντων ἀγών, ESCHL. <i>Pers. 405,</i> maintenant il s’agit d’un combat pour le tout ; φιλονεικεῖν ὑπέρ τινος, ISOCR. aimer à se quereller pour qqe ch. ; ἀμφισϐητεῖν ὑπέρ τινος, ISOCR. <i>Panath. § 54,</i> être en dissentiment pour qqe ch. ; <i>de même pour ce dont on veut préserver :</i> ἴδετε παρθένων ἱκέσιον λόχον δουλοσύνας ὕπερ, ESCHL. <i>Sept. 107,</i> jetez un regard sur la troupe des jeunes filles qui implorent pour être préservées de l’esclavage ; τὴν ψῆφον φέρειν ὑπὲρ τῆς αἰσχύνης τοῦ δήμου, ESCHN. <i>Ctes. § 10 Baiter-Sauppe,</i> prendre une décision pour détourner la honte du peuple ; <i>de même avec les verbes signifiant</i> prier, implorer, <i>pour citer l’objet en faveur duquel on implore :</i> λίσσεσθαί τινα ὑπέρ τινος, IL. <i>15, 660, 665, etc. ;</i> OD. <i>15, 261,</i> supplier qqn pour une personne <i>ou</i> une chose ; <i>de même dans la locut</i>. ὑπὲρ τοῦ <i>avec l’inf. au sens d’une prop. finale :</i> ὑπὲρ τοῦ μηδένα βιαίῳ θανάτῳ ἀποθνῄσκειν, XÉN. <i>Hier. 4, 3,</i> afin que personne ne meure d’une mort violente ; <i>cf</i>. ISOCR. <i>Areop. § 64, Panath. § 80 ;</i><br><b>      4</b> au sujet de : ὅθ' ὑπὲρ σέθεν αἴσχε' ἀκούω, IL. <i>6, 524,</i> lorsque j’entends des diffamations sur ton compte ; διαλέγεσθαι ὑπέρ τινος, PLAT. <i>Ap. 39</i> e, discourir de qqe ch. ; βουλεύεσθαι ὑπέρ τινος, ATT. délibérer sur qqe ch. ; <i>en ce sens, dans les inscr. att. à partir du 3<sup>e</sup> siècle av. J.C. : dans une inscr. de 335 à 332 av. J.C. seul</i>. περί ; <i>dans une inscr. de 290,</i> ὑπέρ <i>à côté de</i> περί : περὶ ὧν ἀπαγγέλλει ὁ ἀγωνοθέτης ὑπὲρ τῶν θυσιῶν (<i>inscr. de 290 av. J.C</i>.) au sujet de la déclaration de l’agonothète sur les sacrifices ; <i>postér</i>. ὑπέρ <i>se substitue tout à fait à</i> περί : ὑπὲρ ὧν ἀπαγγέλλουσιν ὑπὲρ τῶν θυσιῶν (<i>inscr. de 200 av. J.C</i>.) au sujet des déclarations sur les sacrifices ; <i>v. Meisterh. p. 182, 50 ;</i><br><b>   III</b> au delà de, par-dessus, plus loin que, plus que, mieux que, PD. <i>O. 11, 72 ; N. 9, 54, etc. ;</i> SOPH. <i>Ant. 11, 38 ;</i><br><b>C</b> <i>Avec l’acc. :</i><br><b>   I</b> au delà de, <i>avec mouv. :</i> ὑπὲρ ὦμον ἤλυθ' ἀκωκὴ ἔγχεος, IL. <i>5, 16,</i> la pointe de la javeline arriva au-dessus de l’épaule (sans l’atteindre) ; ὑπὲρ οὐδὸν ἐϐήσετο δώματος εἴσω, OD. <i>7, 135,</i> il franchit le seuil et entra dans la maison ; ἀποπλαγχθέντες ὑπὲρ μέγα λαῖτμα θαλάσσης, OD. <i>9, 260,</i> ballottés au delà du grand gouffre de la mer ; ἀλαλῆσθαι ὑπεὶρ ἅλα, OD. <i>3, 73,</i> errer sur la mer ; ὑπὲρ πόντον ἐλθεῖν, ESCHL. <i>Eum. 250,</i> aller au delà de la mer, traverser la mer, <i>etc. ; sans mouv</i>. ὑπὲρ Ἡρακλείας στήλας κατοικεῖν, PLAT. <i>Criti. 108</i> e, habiter au delà des colonnes d’Hercule ; <i>avec idée de temps :</i> ὑπὲρ τὸ ὕδωρ λέγειν, LUC. <i>Im. 29,</i> parler au delà du temps accordé (<i>v</i>. ὕδωρ) ; ὑπὲρ τὸν Τιθωνὸν ζῆν, LUC. <i>D. mort. 7, 1,</i> vivre plus longtemps que Tithôn ; ὁ ὑπὲρ τὰ Μηδικὰ πόλεμος, THC. <i>1, 41,</i> la guerre d’avant les guerres Médiques ; <i>avec un n. de nombre :</i> ἔπεσον ὑπὲρ τεσσεράκοντα ἄνδρας, HDT. <i>5, 64,</i> il tomba plus de quarante hommes ; ὑπὲρ τριάκοντα ἔτη γεγονώς, PLAT. <i>Leg. 664</i> d, âgé de plus de trente ans ; ὑπὲρ τὰ στρατεύσιμα ἔτη γεγονώς, XÉN. <i>Cyr. 1, 2, 4,</i> au delà de l’âge où l’on est soumis au service militaire ;<br><b>   II</b> au-dessus de : πρυμνὸν ὕπερ θέναρος, IL. <i>5, 339,</i> au-dessus du poignet ; οὔθ' ὑπὲρ γῆν οὔθ' ὑπὸ γῆν, PLUT. <i>Arist. 10,</i> ni sur terre, ni sous terre ; καθίζεσθαι ὑπέρ τινα, PLUT. <i>Artax. 5,</i> être assis au-dessus de qqn ; ὑπερίσχειν τὰς κεφαλὰς ὑπὲρ τὸ ὑγρόν, POL. <i>3, 84, 9,</i> laisser dépasser les têtes au-dessus de l’eau ; <i>fig</i>. μεγέθει καὶ ῥώμῃ ὑπὲρ τοὺς ἄλλους, PLAT. <i>Rsp. 488</i> a, surpasser les autres en grandeur et en force ; ὑπὲρ ἄνθρωπον εἶναι, PLAT. <i>Leg. 839</i> d, être surhumain, dépasser les proportions humaines ; εἴ τι ὑπὲρ τὴν ἑαυτοῦ φύσιν ἀκούει, THC. <i>2, 35,</i> s’il entend dire qqe ch. qui dépasse sa portée, ce qu’il est capable de faire lui-même ; ἀρετὴ ἡ ὑπὲρ τοὺς ἰδιώτας, ARSTT. <i>Pol. 4, 9, 1,</i> une vertu trop élevée pour les hommes ordinaires ; ὑπὲρ ἄνθρωπον εἶναι, LUC. <i>V. auct. 2,</i> être plus qu’un homme ; ὑπὲρ δύναμιν, THC. <i>6, 16,</i> au-dessus des forces ; ὑπὲρ τὴν οὐσίαν, PLAT. <i>Rsp. 372</i> b, plus que les moyens d’existence ne le permettent ; ὑπὲρ τὴν ἀξίαν, EUR. <i>H.f. 146,</i> au-dessus du mérite ; ὑπὲρ ἐλπίδα, SOPH. <i>Ant. 366,</i> au delà de l’attente ; ὑπὲρ ἄνθρωπον φρονεῖν, XÉN. <i>Cyr. 8, 7, 3,</i> avoir des sentiments qui dépassent la nature humaine, <i>càd</i>. trop ambitieux ; <i>p. suite en mauv. part :</i> ὑπὲρ αἶσαν, IL. <i>3, 59,</i> au dessus <i>ou</i> au delà de ce qui convient ; ὑπὲρ μοῖραν, IL. <i>20, 336,</i> au-dessus du sort, <i>càd</i>. contre la décision du sort ; ὑπὲρ ὅρκια, IL. <i>3, 299, etc</i>. contre le serment ; ὑπὲρ θεόν, IL. <i>17, 327,</i> contre la volonté de la divinité.<br><span><b><span class=\"arrow\"></span><br>   I</b> ὑπέρ <i>se place qqf. en poésie après son rég. : il s’accentue alors</i> ὕπερ, IL. <i>5, 339 ;</i> OD. <i>19, 450, etc. ;</i><br><b>   II</b> <i>En composition, ὑπέρ marque :</i><br><b>      1</b> <i>l’idée de</i> au-dessus, <i>v</i>. ὑπεράνω, ὑπέργειος, <i>etc. ;</i><br><b>      2</b> <i>l’idée de</i> au delà, <i>v</i>. ὑπερϐαίνω, ὑπερϐάλλω, ὑπερπόντιος, <i>etc. ;</i><br><b>      3</b> <i>l’idée de</i> protection, <i>v</i>. ὑπερμαχεῖν, ὑπεραπολογεῖσθαι ;<br><b>      4</b> <i>l’idée de</i> au delà de la mesure, <i>v</i>. ὑπεράγαν, ὑπέραισχρος, ὑπερήφανος ;<br><b>   III</b> <i>épq</i>. ὑπείρ, IL. <i>23, 227, etc. ;</i> OD. <i>3, 73, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *uper(i)-, sur, au-dessus de ; <i>cf. lat</i>. super, <i>sscr</i>. upári.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερ - ὑπέρ</font>\n<br><br>une préposition primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n159 fois dans 143 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Jean (12)</li>\n<li>Actes (9)</li>\n<li>Romains (19)</li>\n<li>1 Corinthiens (11)</li>\n<li>2 Corinthiens (37)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (11)</li>\n<li>Philippiens (7)</li>\n<li>Colossiens (6)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (3)</li>\n<li>1 Timothée (3)</li>\n<li>Tite (1)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (12)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n<li>1 Jean (2)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G5229":"<h1>huperairomai</h1>\n<p>Strong n° 5229 <i>Prononciation [hoop-er-ah'-ee-rom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se lever ou s'élever par dessus une chose</li>\n<li>s'élever, être élevé, être hautain</li>\n<li>se comporter avec arrogance, agir d'une manière insolente envers quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·αίρω</b> <span>(<i>f</i>. -αρῶ, <i>ao</i>. -ῆρα, <i>pf</i>. -ῆρκα, <i>etc</i>.)</span><br><b>   I <i>tr.</i></b> lever <i>ou</i> élever au-dessus, <i>acc</i>. PLAT. <i>Phædr. 248</i> a ; LUC. <i>Am. 54, etc. ;</i><br><b>   II <i>intr. :</i><br>      1</b> s’élever au-dessus de, surpasser, dépasser : τὸ μέγεθος δένδρου, TH. <i>C.P. 5, 14, 9,</i> la hauteur d’un arbre ; <i>p. anal. :</i> τὸ λαιὸν τῶν πολεμίων νεῶν, POL. dépasser l’aile gauche de la flotte ennemie (pour l’envelopper <i>ou</i> l’attaquer) ; <i>fig</i>. l’emporter sur, surpasser, exceller, <i>en prose att</i>. PLAT. <i>Leg. 717</i> d, <i>etc. ; avec l’acc. :</i> τινά, DÉM. <i>1395, 23,</i> se rendre maître de qqn ; τινά τινι, DÉM. <i>798, 8,</i> dépasser, surpasser qqn en qqe ch. ; <i>avec le gén</i>. τινὸς τῷ μεγέθει, DS. <i>20, 91,</i> surpasser qqn en grandeur ; <i>fig</i>. τῶν συμϐαινόντων, SEXT. être supérieur aux circonstances, aux événements ; ὑπ. τῆς οὐσίας τὸ μέγεθος ὁ τῶν τέκνων ἀριθμός, ARSTT. <i>Pol. 2, 7, 5,</i> le nombre des enfants dépasse l’importance de la fortune ; πυγωνιαῖον ἢ μικρὸν ὑπεραῖρον, TH. <i>H.P. 4, 6, 8,</i> d’une coudée ou un peu plus ;<br><b>      2</b> passer par-dessus, franchir : τὰς Ἄλπεις, POL. <i>2, 23, 1,</i> les Alpes ; τὸ πέλαγος, POL. <i>1, 28, 1,</i> la mer ; <i>abs. en parl. d’un fleuve :</i> ἄκραν, POL. <i>1, 54, 7,</i> doubler un promontoire ; ἀγγεῖα, ARSTT. <i>Mir. 67,</i> déborder des vases, <i>en parl. d’un liquide ;</i> εἰς τὰ χωρία, DÉM. <i>1274, 20,</i> déborder et inonder le pays ;<br><b>      3</b> être excessif, démesuré : ἔν τινι <i>ou</i> τινί, DC. <i>37, 8, etc</i>. en qqe ch. : τὸ ὑπεραῖρον, POL. <i>16, 12, 9,</i> ce qui passe la mesure, excès ;<br><b>   III</b> <i>Moy. :</i><br><b>      1</b> s’élever outre mesure, <i>d’où</i> être fier, être au-dessus de, <i>gén</i>. RHÉT. <i>1, 632 W. ;</i><br><b>      2</b> <i>en mauv. part,</i> s’élever, se révolter : ἐπὶ Θεόν, NT. <i>2Thess. 2, 4,</i> contre Dieu ;<br><b>      3</b> <i>abs</i>. s’élever, être orgueilleux, vain, ARISTÉN. <i>1, 17 ;</i> NT. <i>2Cor. 12, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπεραιρομαι - ὑπεραίρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5230":"<h1>huperakmos</h1>\n<p>Strong n° 5230 <i>Prononciation [hoop-er'-ak-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>au delà de la fleur de l'âge, de l'amorce de la vie</li>\n<li>grassouillet et mûr, (et ainsi dans un grand danger de souillure)\n<ol type=\"a\">\n<li>d'une vierge</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπέρ·ακμος, ος, ον</b>, qui a passé l’âge de la force, de la jeunesse, NT. <i>1Cor. 7, 36</i>.<br><span><b>Étym</b>. ὑ. ἀκμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερακμος - ὑπέρακμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5231":"<h1>huperano</h1>\n<p>Strong n° 5231 <i>Prononciation [hoop-er-an'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>au-dessus\n<ol type=\"a\">\n<li>au-dessus d'une chose</li>\n<li>d'un lieu</li>\n<li>de rang ou de pouvoir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·άνω</b> <span>[ᾰ]</span> <i>adv. :</i><br><b>      1</b> tout à fait au-dessus, LUC. <i>D. deor. 4, 2, etc. ;</i> τινός, ARSTT. <i>H.A. 3, 3, 17, etc</i>. de qqe ch. ; ὑπεράνω γίγνεσθαι, PLUT. <i>M. 10</i> b, <i>etc</i>. l’emporter sur, triompher de, <i>gén. ;</i> ποιεῖν τινα ὑπεράνω τινός, PLUT. <i>M. 98</i> e, <i>ou</i> ποιεῖσθαί τινα ὑπεράνω τινός, PLUT. <i>M. 6</i> c, mettre une personne fort au-dessus d’une autre ; <i>abs</i>. πάντων ὑπ. ποιεῖν, DL. <i>7, 128,</i> agir plus noblement que tous ;<br><b>      2</b> <i>p. suite,</i> excessivement : οἱ ὑπ. πλεονασμοί, POL. <i>12, 24, 1,</i> redites excessives.<br><span><b>Étym</b>. ὑ. ἄνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερανω - ὑπεράνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5232":"<h1>huperauxano</h1>\n<p>Strong n° 5232 <i>Prononciation [hoop-er-owx-an'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>augmenter au delà de la mesure</li>\n<li>croître grandement, s'épanouir magnifiquement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·αυξάνω :<br>      1 <i>tr.</i></b> accroître <i>ou</i> augmenter outre mesure, <i>au pass</i>. AND. <i>32, 23 ;</i> GAL. <i>14, 226, 410 ;</i> DC. <i>79, 15 ;</i><br><b>      2 <i>intr.</i></b> croître avec force, CALLISTH. (STOB. <i>Fl. 100, 14</i>) ; NT. <i>2Thess. 1, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπεραυξανω - ὑπεραυξάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5233":"<h1>huperbaino</h1>\n<p>Strong n° 5233 <i>Prononciation [hoop-er-bah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>marcher sur, au delà de</li>\n<li>métaph.\n<ol type=\"a\">\n<li>transgresser</li>\n<li>dépasser les limites convenables</li>\n<li>empiéter, faire tort, pécher\n<ol>\n<li>de quelqu'un qui en trompe un autre dans une affaire</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·ϐαίνω</b> <span>(<i>f</i>. -ϐήσομαι, <i>ao.2</i> -έϐην, <i>etc</i>.)</span><br><b>A <i>intr</i>.<br>   I</b> passer par-dessus, franchir :<br><b>      1</b> <i>avec idée de lieu :</i> τεῖχος, IL. <i>12, 469 ;</i> OD. <i>16, 41 ;</i> EUR. <i>Bacch. 654 ;</i> THC. <i>3, 20,</i> un mur ; οὐδόν, OD. <i>8, 80,</i> le seuil d’une maison ; δόμους, EUR. <i>Med. 382,</i> entrer dans une maison ; τάφρους, EUR. <i>Rhes. 111,</i> franchir un fossé ; οὔρους, HDT. <i>6, 108,</i> franchir des frontières ; οὔρεα, HDT. <i>4, 25,</i> franchir des montagnes ; <i>rar. avec le gén</i>. HDT. <i>3, 54 dout. ;</i> EUR. <i>Suppl. 1049 dout., Ion 220 dout. ; abs</i>. ὑπ. εἰς τὴν τῶν Θηϐαίων, XÉN. <i>Hell. 5, 4, 59,</i> pénétrer sur le territoire des Thébains ; <i>cf</i>. PLAT. <i>Rsp. 587</i> c ; <i>en parl. de fleuves,</i> franchir son lit, déborder, HDT. <i>2, 99 ;</i> ἐς χώρην, HDT. <i>2, 13,</i> inonder un pays, <i>etc. ;</i><br><b>      2</b> <i>avec idée de temps :</i> πλέον ὑπ. ἑϐδομήκοντα ἔτη, PLAT. <i>Leg. 755</i> a, dépasser soixante-dix ans ; <i>abs</i>. dies ὑπερϐαίνοντες, MACR. <i>Sat. 1, 13, 10,</i> jours surnuméraires ;<br><b>   II</b> <i>fig. càd. :</i><br><b>      1</b> transgresser, violer : θέμιν καὶ δίκαν, PD. <i>fr. 4,</i> le droit et la justice ; νόμους, HDT. <i>3, 83 ;</i> SOPH. <i>Ant. 449, etc</i>. des lois ; τὰς πίστεις καὶ τοὺς ὅρκους, DÉM. <i>153, 4,</i> les engagements et les serments ; <i>d’où abs</i>. pécher, faillir, <i>d’ord. joint à</i> ἁμαρτάνω, IL. <i>9, 501 ;</i> PLAT. <i>Rsp. 366</i> a ;<br><b>      2</b> laisser de côté, passer à côté de, <i>d’où</i> omettre, négliger, <i>acc</i>. HDT. <i>3, 89 ;</i> PLAT. <i>Crat. 415</i> b <i>et c, Rsp. 528</i> d ; DÉM. <i>51, 7, etc. ;</i><br><b>   III</b> surpasser, l’emporter sur : τινά τινι, PLAT. <i>Tim. 24</i> d, <i>Rsp. 478</i> c ; POL. <i>12, 13, 1, etc</i>. sur qqn en qqe ch. ; <i>abs</i>. vaincre, THGN. <i>1015 ;</i><br><b>   IV</b> se mettre devant, protéger, défendre : τινί, OPP. <i>H. 1, 710,</i> qqn ;<br><b>B</b> <i>tr. (à l’ao.1, 3 sg. impér</i>. ὑπερϐησάτω) faire passer <i>ou</i> enlever par-dessus, XÉN. <i>Eq. 7, 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 épq. 3 pl</i>. ὑπέρϐασαν (<i>p</i>. ὑπερέϐησαν) IL. <i>12, 469 ; sbj. épq. 3 sg</i>. ὑπερϐήῃ, IL. <i>9, 501 ; part. pf. poét. acc. sg. masc</i>. ὑπερϐεϐαῶτα, OPP. <i>H. 1, 710</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερβαινω - ὑπερβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G5234":"<h1>huperballontos</h1>\n<p>Strong n° 5234 <i>Prononciation [hoop-er-bal-lon'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>au-dessus de la mesure, infiniment plus, au-delà de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερϐαλλόντως</b>, <i>adv</i>., d’une manière excessive <i>ou</i> extraordinaire) XÉN. <i>Ages. 1, 36 ;</i> PLAT. <i>Leg. 667</i> a, <i>836</i> a ; ISOCR. <i>8</i> b, <i>234</i> c ; POL. <i>16, 24, 4, etc</i>.<br><span><b>Étym</b>. ὑπερϐάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερβαλλοντως - ὑπερβαλλόντως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5235":"<h1>huperballo</h1>\n<p>Strong n° 5235 <i>Prononciation [hoop-er-bal'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>surpasser dans le don, jeter au delà de toute chose</li>\n<li>transcender, surpasser, excéder, exceller</li>\n<li>excellent, qui surpasse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·ϐάλλω</b> <span>(<i>f</i>. -ϐαλῶ, <i>ao.2</i> -έϐαλον, <i>etc</i>.)</span><br><b>   I</b> lancer par-dessus <i>ou</i> au delà, dépasser le but, <i>d’ord. avec l’acc., rar. avec le gén. du but par-dessus lequel on jette :</i> ὑπ. ἄκρον (λόφον) IL. <i>23, 843 ;</i> OD. <i>11, 597,</i> lancer par-dessus le sommet de la colline ; ἀγῶνος ὑπ. IL. <i>23, 847,</i> lancer par-dessus tout l’espace réservé aux jeux ; <i>l’objet qu’on jette, au dat. :</i> ὑπ. Φυλῆα δουρί, IL. <i>23, 637,</i> jeter la lance au delà de Phylès, <i>càd</i>. atteindre avec la lance bien au delà de Phylès, <i>càd</i>. le surpasser ; <i>postér. à l’acc. :</i> τὸν αὐχένα ὑπ. τινός, PHILSTR. <i>V. Ap. 3, 8,</i> allonger le cou par-dessus qqe ch. ;<br><b>   II <i>intr.</i></b> passer par-dessus, <i>d’où :</i><br><b>      1</b> dépasser le but, <i>particul. en parl. de chiens,</i> XÉN. <i>Cyn. 6, 20 ; avec l’acc</i>. dépasser, devancer, prévenir, SOPH. <i>El. 716 ;</i><br><b>      2</b> déborder, <i>en parl. d’un chaudron qui bout,</i> HDT. <i>1, 59 ; d’un fleuve :</i> ὑπ. τὰς ἀρούρας, HDT. <i>2, 111,</i> inonder les campagnes ;<br><b>      3</b> <i>particul</i>. franchir une hauteur, XÉN. <i>An. 1, 1, 7 ; 4, 6, 10 ; avec l’acc. du lieu que l’on franchit :</i> ὑπ. κορυφάς, ESCHL. <i>Pr. 722 ;</i> τείχη, EUR. <i>Rhes. 989 ;</i> τὰς Ἄλπεις, POL. <i>2, 35, 5, etc</i>. franchir des sommets, des murs, les Alpes ; <i>particul. t. de mar</i>. franchir <i>ou</i> doubler un promontoire : Μαλέην, HDT. <i>7, 168,</i> franchir le cap Malée ; τὴν ἄκραν, THC. <i>8, 104,</i> doubler le promontoire ;<br><b>      4</b> enchérir sur, faire une surenchère, AND. <i>17, 26, etc. ;</i> ὑπ. ἀλλήλους, HDT. <i>1, 196 ;</i> LYS. <i>165, 1,</i> enchérir les uns sur les autres ;<br><b>      5</b> dépasser la mesure : ὑπ. μέτρον, THGN. <i>479,</i> dépasser la mesure ; ὑπ. τὰ ἱκανά, XÉN. <i>Hier. 8, 4,</i> dépasser le suffisant, <i>càd</i>. être superflu ; <i>abs</i>. faire des réclamations exagérées, THC. <i>8, 56 ; fig</i>. μὴ γλῶσσ' ὑπερϐάλῃ κακοῖς, EUR. <i>Hipp. 924,</i> que ta langue ne dépasse la mesure dans la souffrance ;<br><b>      6</b> <i>avec l’acc</i>. surpasser : ἡδοναὶ ὑπ. λύπας, PLAT. <i>Leg. 734</i> b, les plaisirs surpassent les peines ; ὑπ. τὰς ἄλλων ἀρετάς, ISOCR. <i>57</i> b, surpasser les vertus des autres ; ὑπ. τινὰ τόλμῃ τε καὶ μιαρίᾳ, XÉN. <i>Hell. 7, 3, 6,</i> surpasser qqn en audace et en perversité ; <i>avec le gén. au lieu de l’acc. :</i> λύπῃ ὑπερϐάλλει τὸ ἀδικεῖν τοῦ ἀδικεῖσθαι, PLAT. <i>Gorg. 475</i> c, léser autrui fait plus de peine que d’être lésé soi-même ; <i>cf</i>. PLAT. <i>Leg. 734, etc. ; seul. avec le dat. de la chose par laquelle on dépasse la mesure :</i> ὑπ. μεγέθει δώρων, XÉN. <i>Cyr. 8, 2, 13,</i> se distinguer par la grandeur des présents ; ὑπ. ἀνοίᾳ, DÉM. <i>94, 24,</i> être insensé outre mesure ; ὑπ. αἴσχει, XÉN. <i>Cyr. 2, 2, 29,</i> être extrêmement laid ; <i>part</i>. ὑπερϐάλλων, ουσα, ον, excessif, extraordinaire, surabondant : βροντῆς ὑπερϐάλλων κτύπος, ESCHL. <i>Pr. 923,</i> bruit excessif du tonnerre ; ὑπ. ἥλιος, HDT. <i>4, 183,</i> soleil extrêmement chaud ; ὑπ. δαπάνη, XÉN. <i>Hier. 11, 2,</i> dépense excessive ; εὐδαιμονία, EUR. <i>Ion 472,</i> bonheur excessif ; <i>p. opp. à</i> καταδεεστέρους, ISOCR. <i>191</i> d ; τὰ ὑπερϐάλλοντα, EUR. <i>Med. 107,</i> puissance par trop grande ; τὰ ὑπ. ἑκατέρωσε, PLAT. <i>Rsp. 619</i> a, l’excès des deux côtés ; <i>avec un acc. de temps :</i> dépasser : ἔτεα ἑκατόν, HDT. <i>3, 23,</i> vivre plus de cent ans ; ὑπ. τὸν χρόνον, XÉN. <i>Hell. 5, 3, 21,</i> dépasser le temps ;<br><b>   III</b> <i>Moy. :</i><br><b>      1</b> exagérer, amplifier, ISOCR. <i>210</i> d ;<br><b>      2</b> enchérir sur ; τινα χρήμασι, PLAT. <i>Phædr. 232</i> c, offrir plus d’argent que qqn ; τοὺς εὐεργετοῦντας ἀγαθοῖς, XÉN. <i>Cyr. 5, 3, 32,</i> surpasser en bienfaits ceux qui ont rendu service ;<br><b>      3</b> l’emporter sur, HDT. <i>6, 9 ; 7, 168 ;</i> ὑπ. τινα φίλτροις, SOPH. <i>Tr. 584,</i> l’emporter sur qqn grâce à des sortilèges ; ὑπ. τινι, HDT. <i>1, 61 ; 3, 21 ; 9, 71,</i> l’emporter par qqe ch. ; <i>avec l’acc. :</i> τινα, HDT. <i>5, 124,</i> l’emporter sur qqn ; τινά τινι, EUR. <i>Or. 691,</i> l’emporter sur qqn par qqe ch. ; τινα τῷ τε ὕψεϊ καὶ τῷ μεγάθεϊ, HDT. <i>2, 175,</i> l’emporter sur qqn par la taille et par la grandeur ; τινα ἀναιδείᾳ, AR. <i>Eq. 409,</i> l’emporter sur qqn en impudence ; ὑπ. ἔν τινι, STR. <i>2,</i> l’emporter en qqe ch. ; εἴς τι, PLAT. <i>Criti. 115</i> e, par rapport à qqe ch. ; <i>avec le gén. :</i> ὑπ. τινά τινος, LYCURG. <i>165, 15,</i> l’emporter sur qqn en qqe ch. ; <i>part</i>. ὑπερϐεϐλημένος, η, ον, supérieur, éminent, distingué, excellent, <i>en parl. de pers</i>., EUR. <i>Alc. 153 ; en parl. de choses,</i> PLAT. <i>Rsp. 558</i> b, <i>p. opp. à</i> ἐλλείπουσα, PLAT. <i>Leg. 719</i> d ; <i>avec un gén</i>. πολὺ τῶν παρ' ἡμῖν ὑπερϐεϐλημένοι κατὰ τὸ μέγεθος, STR. <i>145,</i> biens supérieurs aux nôtres par la grandeur ;<br><b>      4</b> remettre, différer, <i>abs</i>. HDT. <i>3, 76 ; 7, 206 ;</i> PLAT. <i>Phædr. 254</i> d ; <i>avec un acc</i>. HDT. <i>9, 45, 51 ;</i> LUC. <i>Gymn. 40, etc. ;</i> PLUT. <i>Æmil. 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 épq</i>. ὑπειρέϐαλον, IL. <i>23, 637</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερβαλλω - ὑπερβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (3)</li>\n</ul>\n</td></tr>\n</table>","G5236":"<h1>huperbole</h1>\n<p>Strong n° 5236 <i>Prononciation [hoop-er-bol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un don au delà de</li>\n<li>métaph.\n<ol type=\"a\">\n<li>supériorité, excellence, prééminence, exceptionnel</li>\n<li>au delà de la mesure, extrêmement, extraordinaire</li>\n<li>excessivement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερϐολή, ῆς (ἡ) :<br>      1</b> action de lancer par-dessus <i>ou</i> au delà, PHILSTR. <i>p. 842 ;</i><br><b>      2</b> action de passer par-dessus, de franchir (une montagne, <i>etc</i>.) XÉN. <i>An. 1, 2, 25 ;</i> POL. <i>3, 34, 6 ; d’où</i> action de se transporter, <i>avec</i> εἰς <i>et l’acc</i>. XÉN. <i>An. 4, 6, 5 ;</i> POL. <i>10, 1, 8 ; p. ext</i>. lieu élevé qu’on franchit, passage de montagne, XÉN. <i>An. 3, 5, 18 ; 4, 1, 21, etc. ;</i> STR. <i>206, 292, etc. ;</i><br><b>      3</b> action de dépasser la mesure, excès, surabondance : ὑπ. χερῶν, EUR. <i>Hipp. fr. 437, 2 Nauck,</i> supériorité des forces ; ὑπ. χρημάτων, EUR. <i>Med. 232,</i> surabondance de richesses ; ὑπ. στρατιᾶς, THC. <i>6, 31,</i> supériorité de l’armée ; ὑπ. πλησμονῆς, PLAT. <i>Leg. 776</i> a, satiété jusqu’à l’excès ; ὑπ. ἀρετῆς, THC. <i>2, 45,</i> excès de vaillance ; <i>p. opp. à</i> ἔλλειψις, PLAT. <i>Prot. 356</i> a, <i>à</i> ἔνδεια, PLAT. <i>Prot. 357</i> a ; διὰ τὴν ὑπερϐολὴν τοῦ συμϐάντος, POL. <i>1, 37, 1,</i> comme l’événement surpassait toute description ; <i>au plur</i>. DÉM. <i>500, 10 ; d’où simpl</i>. action de dépasser, d’ajouter encore ; ὑπερϐολὴν ποιεῖσθαι, DÉM. <i>447, 25,</i> aller à toutes les extrémités, admettre le cas extrême ; ὑπερϐολὴν ποιεῖσθαί τινος, DÉM. <i>609, 8, etc. ;</i> LYS. <i>143, 20, etc</i>. ajouter encore à qqe ch., enchérir sur qqe ch. ; τοῦτο γάρ ἐστιν ὑπερϐολή, DÉM. <i>1333, 16,</i> car c’est là le dernier degré, le plus haut point, le comble ; εἰς ὑπερϐολήν, EUR. <i>fr. 479, Hipp. 939 ;</i> ESCHN. <i>F. leg. § 4 Baiter-Sauppe ; ou</i> εἰς ὑπερϐολάς, PLAT. <i>Ep. 316</i> c, démesurément, à l’excès, <i>ou simpl</i>. au plus haut point ; καθ' ὑπερϐολήν, SOPH. <i>O.R. 1196 ;</i> ISOCR. <i>84</i> d, <i>etc. ; ou</i> ὑπερϐολῇ, MACH. (ATH. <i>341</i> a) <i>m. sign. ; particul</i>. hyperbole, exagération de langage, ARSTT. <i>Rhet. 3, 11, etc. ;</i> ὑπερϐολὰς εἰπεῖν, ISOCR. <i>58</i> d, dire des exagérations ;<br><b>      4</b> remise, ajournement, délai, répit, HDT. <i>8, 112 ;</i> POL. <i>14, 9, 8 ;</i><br><b>      5</b> <i>t. de math</i>. hyperbole, section conique, APOLL. PERG. <i>Con. 2, 12</i>.<br><span><b>Étym</b>. ὑπερϐάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερβολη - ὑπερβολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G5237":"<h1>hupereido</h1>\n<p>Strong n° 5237 <i>Prononciation [hoop-er-i'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>négliger, ne pas tenir compte, sans attendre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·οράω</b> <span>(<i>impf</i>. ὑπερεώρων, <i>f</i>. ὑπερόψομαι, <i>ao.2</i> ὑπερεῖδον, <i>pf</i>. ὑπερεόρακα, <i>pass. ao</i>. ὑπερώφθην)</span><br><b>      1</b> regarder par-dessus, voir d’en haut, <i>acc</i>. HDT. <i>7, 36 ;</i><br><b>      2</b> regarder de haut, avec fierté <i>ou</i> dédain, mépriser, dédaigner, <i>acc</i>. HDT. <i>5, 69 ;</i> THC. <i>4, 62 ; 5, 6, etc. ;</i> XÉN. <i>Mem. 1, 3, 4 ;</i> PLAT. <i>Criti. 120</i> e, <i>etc. ; gén</i>. ANT. <i>122, 43 ;</i> XÉN. <i>Mem. 1, 2, 9, etc. ; au pass</i>. THC. <i>5, 28, etc. ;</i> PLAT. <i>Phædr. 232</i> d.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. part. ion. acc. sg</i>. ὑπερορέοντα, HDT. <i>7, 36</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερειδω - ὑπεροράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5238":"<h1>huperekeina</h1>\n<p>Strong n° 5238 <i>Prononciation [hoop-er-ek'-i-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>au delà : les régions qui sont au delà de notre contrée de résidence</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·έκεινα</b>, <i>adv. et prép</i>. au delà, au delà de, <i>gén</i>. NT. <i>2Cor. 10, 16</i>.<br><span><b>Étym</b>. ὑ. ἐκεῖνα, <i>pl. neutre de</i> ἐκεῖνος ; <i>cf</i>. ἐπέκεινα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερεκεινα - ὑπερέκεινα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5239":"<h1>huperekteino</h1>\n<p>Strong n° 5239 <i>Prononciation [hoop-er-ek-ti'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'étendre au delà des limites prescrites, s'étendre au-delà de la mesure, dépasser largement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·εκτείνω</b>, étendre <i>ou</i> allonger outre mesure, NT. <i>2Cor. 10, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερ-εκτεινω - ὑπερεκτείνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5240":"<h1>huperekchuno</h1>\n<p>Strong n° 5240 <i>Prononciation [hoop-er-ek-khoo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>verser au-delà de la mesure</li>\n<li>déborder, aller par dessus</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·εκχύνω</b> <i>(seul. prés.) c</i>. ὑπερεκχέω NT. <i>Luc. 6, 38</i>.<br><br>\n<b>ὑπερ·εκχέω</b>, répandre par-dessus, <i>d’où au pass</i>. déborder et se répandre, DS. <i>11, 89 ;</i> EL. <i>N.A. 12, 41 ;</i> ARTÉM. <i>2, 27</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερεκχυνω - ὑπερεκχύν(ν)ω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5241":"<h1>huperentugchano</h1>\n<p>Strong n° 5241 <i>Prononciation [hoop-er-en-toong-khan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>intercéder pour quelqu'un</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·εντυγχάνω</b>, intervenir, <i>particul</i>. intercéder pour : τινός, CLÉM. <i>126 ; ou</i> ὑπέρ τινος, NT. <i>Rom. 8, 26,</i> pour qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερεντυγχανω - ὑπερεντυγχάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5242":"<h1>huperecho</h1>\n<p>Strong n° 5242 <i>Prononciation [hoop-er-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir au-dessus de quelqu'un</li>\n<li>s'élever au-dessus, surpasser\n<ol type=\"a\">\n<li>être au-dessus, être supérieur en rang, autorité, pouvoir\n<ol>\n<li>les hommes importants, gouvernants</li>\n</ol>\n</li>\n<li>exceller, être supérieur, meilleur que, surpasser</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·έχω</b> <span>(<i>f</i>. -έξω, <i>ao.2</i> -έσχον, <i>etc. d’où sbj</i>. ὑπέρσχω, <i>opt</i>. ὑπέρσχοιμι, <i>inf</i>. ὑπερσχεῖν, <i>part</i>. ὑπερσχών)</span><br><b>   I <i>tr</i>.<br>      1</b> tenir au-dessus, tenir élevé sur : σπλάγχνα ὑπ. Ἡφαίστοιο, IL. <i>2, 426,</i> tenir les entrailles au-dessus du feu ; τί τινος, AR. <i>Av. 1508, Eq. 1170, etc</i>. tenir qqe ch. au-dessus de qqn ; χεῖρα, IL. <i>4, 249 ;</i> χεῖράς τινι, IL. <i>5, 433 ;</i> OD. <i>14, 184 ; ou</i> χεῖρά τινος, IL. <i>9, 420, 687 ; 24, 374 ;</i> THGN. <i>757 ;</i> LUC. <i>Tim. 10,</i> tenir les mains au-dessus de qqn pour le protéger ;<br><b>      2</b> tenir au-dessus, lever au-dessus : ὑπ. τὸ ῥύγχος, ARSTT. <i>H.A. 8, 12, 6,</i> tenir le museau <i>ou</i> la bouche au-dessus (de l’eau, pour respirer), <i>en parl. du dauphin ; abs</i>. ὑπ. ὀφρύν, ANTH. <i>5, 299,</i> lever le sourcil ;<br><b>   II <i>intr. :</i><br>      1</b> se tenir au-dessus, s’élever au-dessus : γαίης, IL. <i>11, 735,</i> de la terre ; τῆς θαλάσσης, THC. <i>7, 25,</i> de la mer ; <i>abs</i>. HDT. <i>2, 4 ;</i> τὰ ὑπερέχοντα, HDT. <i>2, 41,</i> les parties dominantes <i>ou</i> saillantes ; <i>particul</i>. s’élever au-dessus de l’horizon, se lever, <i>en parl. d’un astre,</i> OD. <i>13, 93 ;</i><br><b>      2</b> être au-dessus de (par la taille), surpasser, dominer : ὑπ. ὤμους, IL. <i>3, 210,</i> surpasser qqn des épaules ; ὑπ. τινός, HDT. <i>5, 92,</i> surpasser qqe ch. ; <i>p. anal</i>. τῶν πολεμίων ὑπ. τῷ κέρατι, XÉN. <i>Hell. 4, 2, 18,</i> dépasser le flanc de l’ennemi avec l’aile d’une armée ; <i>fig</i>. l’emporter sur, être supérieur : τινός, DÉM. <i>689, 10,</i> à qqn ; τινί τινος, PLAT. <i>Tim. 24</i> e ; <i>ou</i> τινί τινα, XÉN. <i>Hell. 6, 1, 9 ;</i> EUR. <i>Hipp. 1365 ; ou</i> τινός τι, ESCHL. <i>Pers. 709,</i> surpasser qqn en qqe ch. ; <i>avec un part. :</i> ὑπερέχει λέγων, LUC. <i>J. tr. 4,</i> il excelle à parler ; <i>abs</i>. dominer, prévaloir, ESCHL. <i>Pr. 213 ;</i> DÉM. <i>128, 25, etc. ; au pass. :</i> ὑπὸ Φαίδωνος ὑπερέχεσθαι, PLAT. <i>Phæd. 102</i> c, être surpassé par Phédon ; <i>abs</i>. PLAT. <i>Parm. 150</i> d ;<br><b>      3</b> être au-dessus de, suffire largement à : τῶν ἀναλωμάτων, DS. <i>4, 80,</i> être au-dessus de ses dépenses, y suffire et au delà ;<br><b>      4</b> résister à, supporter : τῆς ἀντλίας, AR. <i>Pax 17,</i> l’odeur de la sentine ;<br><b>      5</b> <i>t. de math</i>. τὸ ὑπερέχον, DIOPH. <i>Arithm. 1, 3,</i> quantité en plus <i>ou</i> positive (<i>p. opp. à</i> quantité en moins <i>ou</i> négative).<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 épq. 2 pl</i>. ὑπερέσχεθε, IL. <i>11, 735 ; 24, 374 ; ao.2 sbj. 3 sg</i>. ὑπέρσχῃ, IL. <i>4, 249 ; prés. épq</i>. ὑπειρέχω, <i>d’où opt. 3 sg</i>. ὑπειρέχοι, THGN. <i>757 ; impf. 3 sg</i>. ὑπείρεχε, IL. <i>5, 433 ;</i> ὑπείρεχεν, IL. <i>3, 210 ; 3 pl</i>. ὑπείρεχον, IL. <i>2, 426</i>.<br><span><b>Étym</b>. ὑ. ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερεχω - ὑπερέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Philippiens (3)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5243":"<h1>huperephania</h1>\n<p>Strong n° 5243 <i>Prononciation [hoop-er-ay-fan-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>orgueil, hauteur, arrogance</li>\n<li>le caractère de quelqu'un qui, avec une grande estime de son propre pouvoir ou mérite, regarde les autres de haut, et les traite avec insolence et mépris</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερηφανία, ας (ἡ)</b> <span>[φᾰ]</span> fierté, orgueil, dédain, <i>avec le gén. de la pers. ou de la chose à laquelle on attribue ce sentiment,</i> XÉN. <i>Cyr. 5, 2, 27 ;</i> PLAT. <i>Conv. 219</i> c ; DÉM. <i>559, 17 ; ou le gén. de la pers. ou de la chose pour laquelle on éprouve ce sentiment,</i> PLAT. <i>Rsp. 391</i> c ; DÉM. <i>577, 16, etc</i>.<br><span><b>Étym</b>. ὑπερήφανος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερηφανια - ὑπερηφανία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G5244":"<h1>huperephanos</h1>\n<p>Strong n° 5244 <i>Prononciation [hoop-er-ay'-fan-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se montrer au-dessus des autres, surpasser, se mettre en évidence, avec une trop haute estime de ses propres moyens ou de ses mérites, mépriser les autres ou même les traiter avec mépris, d'une façon hautaine</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερή·φανος, ος, ον</b> <span>[ᾰ]</span><br><b>      1</b> magnifique, splendide, <i>au propr</i>. PHILIPPID. (<i>Com. fr. 4, 476) ; fig</i>. PLAT. <i>Phæd. 96</i> a, <i>Conv. 217</i> e, <i>etc. ;</i> PLUT. <i>Fab. 26 ;</i><br><b>      2</b> fier, orgueilleux, méprisant, dédaigneux, HÉS. <i>Th. 149 ;</i> PD. <i>P. 2, 52 ;</i> ESCHL. <i>Pr. 402 ;</i> ISOCR. <i>274</i> b ; <i>joint à</i> ὑϐριστής, ARSTT. <i>Rhet. 2, 16, 1 ;</i> τὸ ὑπερήφανον, PLUT. <i>Alc. c.Cor. 4 ;</i> ATH. <i>584</i> e, l’orgueil.<br><span>•<i> Cp</i>. -ώτερος, DÉM. <i>175, 10 ;</i> ARSTT. <i>Rhet. 2, 17, 6 ; sup. irrég</i>. -έστατος, SCHOL.<br><span><b>Étym</b>. ὑ. φαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερηφανος - ὑπερήφανος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>2 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5245":"<h1>hupernikao</h1>\n<p>Strong n° 5245 <i>Prononciation [hoop-er-nik-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être plus qu'un conquérant, gagner une immense victoire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·νικάω-ῶ</b> <span>[ῑ]</span> vaincre tout à fait, triompher de, <i>acc</i>. NT. <i>Rom. 8, 37</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερνικαω - ὑπερνικάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5246":"<h1>huperogkos</h1>\n<p>Strong n° 5246 <i>Prononciation [hoop-er'-ong-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enflé, démesuré, très enflé, énorme</li>\n<li>métaph. immodéré, extravagant, énormité, outrance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπέρ·ογκος, ος, ον :<br>   I</b> gonflé outre mesure, XÉN. <i>Hell. 5, 4, 58 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> très gros, chargé d’embonpoint, <i>joint à</i> πιμελής, LUC. <i>Tim. 15 ; p. opp. à</i> ἄσαρκος, ALCIPHR. <i>1, 39, 5 ;</i><br><b>      2</b> ampoulé, <i>en parl. du style, p. opp. à</i> ἰσχνός, PLUT. <i>M. 7</i> a ;<br><b>      3</b> énorme, démesuré, excessif, <i>au propre,</i> PLAT. <i>Ep. 317</i> c ; PLUT. <i>Marc. 15, M. 820</i> f, <i>etc. ; fig</i>. PLAT. <i>Leg. 728</i> e ; <i>p. opp. à</i> ταπεινός, DÉM. <i>46, 16 ; joint à</i> μέγας, PLUT. <i>Æmil. 34, M. 820</i> f ; <i>particul</i>. orgueilleux, PLUT. <i>Arist. c. Cat. ma. 3 ;</i> τὸ ὑπερογκότερον, ARR. <i>An. 7, 29, 1,</i> orgueil excessif.<br><span>•<i> Cp</i>. -ότερος, ARR. <i>l. c</i>.<br><span><b>Étym</b>. ὑ. ὄγκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερογκος - ὑπέρογκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G5247":"<h1>huperoche</h1>\n<p>Strong n° 5247 <i>Prononciation [hoop-er-okh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>élévation, prééminence, supériorité, prestige, avantage, autorité</li>\n<li>métaph. excellence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπεροχή, ῆς (ἡ) :<br>   I</b> partie saillante, saillie, proéminence, <i>avec un gén</i>. POL. <i>10, 10, 10 ;</i> PLUT. <i>M. 936</i> a ; <i>abs</i>. POL. <i>3, 104, 3 ;</i><br><b>   II</b> <i>p. anal. ou fig. :</i><br><b>      1</b> supériorité, excellence, ARSTT. <i>Rhet. 2, 12, 6 ; Pol. 4, 13, 10, etc. ; au plur</i>. ISOCR. <i>238</i> b ; ARSTT. <i>Pol. 7, 1, 5 ; d’où</i> suprématie, autorité, ARSTT. <i>Pol. 1, 64, 1, etc. ; au plur</i>. DS. <i>4, 41 ;</i><br><b>      2</b> excès, surabondance, <i>p. opp. à</i> ἔλλειψις, ARSTT. <i>Metaph. 3, 2, 18, etc. ; Nic. 1, 7, 14, etc. ; au plur</i>. PLAT. <i>Leg. 711</i> d, <i>etc. ;</i><br><b>      3</b> <i>t. de math</i>. excédent, PLUT. <i>Marc. 17, M. 1022</i> b, <i>1028</i> c, <i>1139</i> d ; ARCHIM. <i>Plan. æq. 1, 2 ;</i> DIOPH. <i>Arithm. 4, 37 ;</i><br><b>      4</b> <i>t. de rhét</i>. périphrase, <i>p. opp. à</i> ἔλλειψις, PLAT. <i>Pol. 283</i> c.<br><span><b>Étym</b>. ὑπερέχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπεροχη - ὑπεροχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5248":"<h1>huperperisseuo</h1>\n<p>Strong n° 5248 <i>Prononciation [hoop-er-per-is-syoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abonder au delà de la mesure, abonder énormément, surabonder</li>\n<li>déborder, réjouir abondamment</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·περισσεύω</b>, <i>att</i>. <b>ὑπερ·περιττεύω</b>, surabonder, MOSCHION <i>Mul. pass. p. 6 ; fig</i>. NT. <i>Rom. 5, 20 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. NT. <i>2Cor. 7, 4</i>.<br><span><b>Étym</b>. *ὑπερπέρισσος, <i>v</i>. ὑπερπερίσσως.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερπερισσευω - ὑπερπερισσεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5249":"<h1>huperperissos</h1>\n<p>Strong n° 5249 <i>Prononciation [hoop-er-per-is-soce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>au delà de la mesure, extrêmement, surabondamment</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·περίσσως</b>, <i>adv</i>., surabondamment, NT. <i>Marc. 7, 37</i>.<br><span><b>Étym</b>. ὑ. περισσός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερπερισσως - ὑπερπερισσῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G5250":"<h1>huperpleonazo</h1>\n<p>Strong n° 5250 <i>Prononciation [hoop-er-pleh-on-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être extrêmement abondant</li>\n<li>déborder</li>\n<li>posséder en excès</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·πλεονάζω</b>, être surabondant, excessif, HÉRON <i>Spir. p. 165, 40 ;</i> NT. <i>1Tim. 1, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερπλεοναζω - ὑπερπλεονάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5251":"<h1>huperupsoo</h1>\n<p>Strong n° 5251 <i>Prononciation [hoop-er-oop-so'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>métaph. élever au plus haut rang et au plus grand pouvoir, élever à la suprême majesté</li>\n<li>vanter au plus haut point</li>\n<li>être enflé d'orgueil, exalté outre mesure</li>\n<li>se conduire d'une façon altière, comme un noble</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·υψόω-ῶ</b>, élever outre mesure, exalter, <i>acc</i>. NT. <i>Phil. 2, 9 ; au pass</i>. SPT. <i>Ps. 36, 35 ; 96, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερυψοω - ὑπερυψόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5252":"<h1>huperphroneo</h1>\n<p>Strong n° 5252 <i>Prononciation [hoop-er-fron-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>penser plus de bien de soi qu'il n'est convenable, être prétentieux, avoir une trop haute opinion de soi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερ·φρονέω-ῶ :<br>   I</b> élever ses pensées trop haut, avoir des vues trop hautes, HPC. <i>1279, 26 ;</i><br><b>   II</b> <i>plus souv. :</i><br><b>      1 <i>intr.</i></b> avoir des sentiments trop hauts, être fier, orgueilleux, ESCHL. <i>Ag. 1039 ;</i> POL. <i>3, 18, 7 ;</i> τινι, HDT. <i>1, 199 ;</i> PLAT. <i>1 Alc. 104</i> a, s’enorgueillir de qqe ch. ;<br><b>      2 <i>tr.</i></b> traiter dédaigneusement, mépriser, dédaigner, <i>acc</i>. ESCHL. <i>Pers. 825 ;</i> AR. <i>Nub. 226 ;</i> THC. <i>3, 39 ; gén</i>. EUR. <i>Bacch. 1326 ;</i> AR. <i>Nub. 1400 ;</i> PLAT. <i>Phædr. 258</i> b.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερφρονεω - ὑπερφρονέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5253":"<h1>huperoon</h1>\n<p>Strong n° 5253 <i>Prononciation [hoop-er-o'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la plus haute partie de la maison, la chambre haute ou grenier où demeuraient les femmes</li>\n<li>une pièce de la partie supérieure d'une maison, quelquefois construite sur le toit plat, où les Orientaux avaient coutume de se retirer pour se reposer, méditer, prier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπερῷος, ῴα, ῷον</b>, situé à l’étage supérieur, DH. <i>3, 68 ;</i> PLUT. <i>Pel. 35, etc. ; subst. :</i><br><b>      1</b> τὸ ὑπερῷον, IL. <i>2, 514 ;</i> OD. <i>15, 517 ;</i> PD. <i>fr. 25 ;</i> AR. <i>Eq. 1001, Pl. 811 ;</i> LYS. <i>p. 3 Reiske ;</i> ANT. <i>113, 3 ; plur</i>. τὰ ὑπερῷα, IL. <i>16, 184 ;</i> OD. <i>1, 362 ; 4, 751, 760,</i> étage supérieur d’une maison (<i>primit</i>. réservé aux femmes, <i>postér</i>. aux esclaves et aux étrangers) ;<br><b>      2</b> ἡ ὑπερῴα, <i>ion</i>. ἡ ὑπερῴη, IL. <i>22, 495 ;</i> HPC. <i>Mochl. 865 ;</i> ARSTT. <i>H.A. 1, 11, 10 ;</i> PLUT. <i>M. 14</i> d, <i>Cato ma. 9,</i> la partie supérieure de la bouche, le palais.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ὑπερῷος, DH. <i>l. c. ; dans les inscr. att</i>. ὑπερῷον, <i>non</i> ὑπερῶον, CIA. <i>2, 817, 27 (358 av. J.C.) ; v. Meisterh. p. 52, 8 ; ion</i>. ὑπερώϊος, IL. <i>2, 514 ;</i> OD. <i>15, 517 ; 18, 206, 302 ; par contr</i>. ὑπερῷος, IL. <i>16, 184 ;</i> OD. <i>1, 362 ; 4, 751, 760</i>.<br><span><b>Étym</b>. ὑπέρ, -ώϊος ; <i>cf</i>. πατρώϊος <i>de</i> πατήρ, μητρώϊος <i>de</i> μήτηρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερωον - ὑπερῷον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (4)</li>\n</ul>\n</td></tr>\n</table>","G5254":"<h1>hupecho</h1>\n<p>Strong n° 5254 <i>Prononciation [hoop-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tenir au-dessous, mettre sous, placer en dessous</li>\n<li>métaph. soutenir, subir\n<ol type=\"a\">\n<li>souffrir un châtiment</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·έχω</b> <span>(<i>f</i>. ὑφέξω, <i>ao.2</i> ὑπέσχον, <i>etc</i>.)</span><br><b>   I</b> tenir sous, <i>càd. :</i><br><b>      1</b> placer sous : θήλεας ἵππους, IL. <i>5, 269,</i> faire couvrir des cavales ;<br><b>      2</b> présenter <i>ou</i> tendre en bas : χεῖρα, IL. <i>7, 188 ;</i> DÉM. <i>421, 18, etc</i>. tendre la main pour demander <i>ou</i> recevoir qqe ch. ; μαστόν, EUR. <i>Ion 1372,</i> tendre le sein ; θηλὴν νηπίοις, PLUT. <i>Rom. 21,</i> présenter la mamelle aux petits enfants ; οὖας, SIM. <i>fr. 37, 14 Bgk, ou</i> τὰ ὦτα, EL. <i>N.A. 12, 44 ;</i> ARSTD. <i>t. 2, 230, etc</i>. prêter l’oreille, tendre les oreilles ; <i>particul</i>. tendre, en baissant ; φιάλην, AR. <i>Pax 431,</i> une coupe ; ἐξάλειπτρον, AR. <i>Ach. 1063,</i> un vase à parfums ;<br><b>   II</b> <i>fig</i>. soumettre, <i>càd. :</i><br><b>      1</b> soumettre au jugement de : τι ταῖς αἰσθήσεσι καὶ ἐννοίαις, PLAT. <i>Theæt. 191</i> d, soumettre qqe ch. au contrôle des sens et de l’intelligence ; λόγον, XÉN. <i>Mem. 4, 4, 9 ;</i> PLAT. <i>Leg. 774</i> b, <i>etc</i>. rendre raison, rendre compte, fournir des explications <i>ou</i> donner une réponse ; εὐθύνας, LYS. <i>115, 11 ;</i> PLUT. <i>Cæs. 33 ;</i> LGN <i>14, 4,</i> rendre ses comptes ;<br><b>      2</b> <i>particul</i>. soumettre au jugement de qqn une excuse, un prétexte, <i>d’où</i> prétexter, alléguer : τὴν ἐκεχειρίαν, AR. <i>Pax 908,</i> prétexter la suspension d’armes ;<br><b>      3</b> soumettre une proposition, offrir, <i>avec un dat. et un inf. :</i> ὑπόσχες Σωκράτει ἐξελέγξαι ὅπως ἂν βούληται, PLAT. <i>Gorg. 497</i> b, offre, <i>càd</i>. permets à Socrate de te réfuter comme il voudra ;<br><b>   III</b> tenir en étant dessous, <i>d’où fig</i>. soutenir, supporter, subir (<i>cf. lat</i>. sustinere) : αἰτίαν, XÉN. <i>Cyr. 6, 3, 16 ;</i> PLAT. <i>Ap. 33</i> b ; ANT. <i>137, 18,</i> subir <i>ou</i> encourir une accusation ; τιμωρίαν, THC. <i>6, 80 ;</i> PLAT. <i>Leg. 716</i> b ; ESCHN. <i>85, 23 ;</i> LYCURG. <i>159, 15, etc</i>. subir <i>ou</i> encourir un châtiment ; δίκην τινός, XÉN. <i>An. 5, 8, 1 ;</i> DÉM. <i>371, 20,</i> subir la peine de qqe ch. ; δίκην τινί, EUR. <i>Hec. 1253, etc</i>. être puni, être châtié par qqn ; ὑπ. φόνου δίκας, PLAT. <i>Leg. 872</i> c ; <i>ou</i> ὑπ. φόνον, EUR. <i>El. 1318,</i> encourir la peine d’un meurtre ; ὑπ. τοῖς χρήμασι τὰς δίκας, ISOCR. <i>389</i> c, porter la peine de qqe ch. par la perte de son bien ; <i>p. anal. :</i> ὑπ. ἄτην, SOPH. <i>Tr. 1274,</i> subir un malheur ;<br><b>   IV</b> avoir sous soi, entraîner à sa suite : πλοῦτος ὑπέχων μέριμναν, PD. <i>O. 2, 99,</i> la fortune qui entraîne après elle des soucis.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. épq</i>. ὑπέσχεθον, IL. <i>7, 188</i>.<br><span><b>Étym</b>. <i>cf</i>. ὑπισχνέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπ-εχω - ὑπέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G5255":"<h1>hupekoos</h1>\n<p>Strong n° 5255 <i>Prononciation [hoop-ay'-ko-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prêter l'oreille, obéissant, docile, soumis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπήκοος, οος, οον</b>, qui prête l’oreille à, <i>dat</i>. ANTH. <i>9, 46 ; d’où :</i><br><b>   I</b> obéissant, docile, soumis : τινος, ESCHL. <i>Pers. 232, 242 ;</i> HDT. <i>4, 167, etc. ;</i> ARSTT. <i>Nic. 1, 13, 2, etc. ; ou</i> τινι (<i>rar. chez les plus anc. écrivains</i>) EUR. <i>Her. 287 ;</i> AR. <i>Pl. 146 ;</i> XÉN. <i>Cyr. 2, 4, 22,</i> à qqn ; ὑπήκοον ποιεῖν τινα, HDT. <i>1, 102,</i> soumettre qqn à son autorité ; <i>subst.</i> οἱ ὑπήκοοι, les sujets, <i>à Athènes,</i> THC. <i>3, 6 et 22 ; 8, 2, 2 ; p. opp. à</i> αὐτόνομοι, THC. <i>7, 57 ; chez les Crétois, classe analogue aux Périèques de Lacédémone,</i> SOSICR. (ATH. <i>263</i> f) ; <i>avec un adj. :</i> σοὺς ὑπηκόους, XÉN. <i>Hell. 4, 1, 36,</i> tes sujets ; <i>cf</i>. XÉN. <i>Cyr. 5, 5, 27 et 33 ;</i> ἡ ὑπήκοος (<i>s.-e</i>. χώρα) DC. <i>36, 19,</i> le pays soumis ; τὸ ὑπήκοον, THC. <i>6, 69,</i> la partie sujette (des alliés) ;<br><b>   II</b> <i>postér. subst</i>. ὁ ὑπ. auditeur, disciple, JAMBL. <i>V. Pyth. 121</i>.<br><span><b>Étym</b>. ὑπακούω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπηκοος - ὑπήκοος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5256":"<h1>hupereteo</h1>\n<p>Strong n° 5256 <i>Prononciation [hoop-ay-ret-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>agir comme un serviteur, comme un homme du rang</li>\n<li>administrer, rendre des services, pourvoir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπηρετέω-ῶ</b> <span>(<i>f</i>. -ήσω, <i>ao</i>. ὑπηρέτησα, <i>pf</i>. ὑπηρέτηκα)</span><br><b>   I</b> servir comme rameur <i>ou</i> comme matelot, EL. <i>N.A. 13, 2 ; d’où au pass</i>. être manœuvré par des rameurs <i>ou</i> des matelots, <i>en parl. d’un navire,</i> DS. <i>2, 55 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> servir, aider, assister, se mettre à la disposition de, <i>dat</i>. HDT. <i>8, 41 ;</i> SOPH. <i>O.C. 283 ;</i> PLAT. <i>Leg. 914</i> a, <i>etc. ;</i> τινι ἔς τι, HDT. <i>1, 109 ;</i> XÉN. <i>Eq. 8, 7 ;</i> τινι πρός τι, DÉM. <i>1382, 11 ;</i> τινί τι, SOPH. <i>Ph. 1024 ;</i> EUR. <i>Rhes. 153 ;</i> XÉN. <i>Cyr. 1, 6, 39 ; 5, 1, 12 ; Hell. 3, 3, 9 ; An. 1, 9, 18 ; Mem. 2, 4, 7 ;</i> PLAT. <i>Conv. 196</i> c, <i>etc</i>. rendre qqe service à qqn ; αὑτοῖς οὐχ ὑπηρετοῦσιν, ARSTT. <i>Pol. 5, 7 (9), 15,</i> ils ne se viennent pas en aide à eux-mêmes, ils ne s’occupent pas de leurs propres intérêts ; <i>m. sign. abs</i>. XÉN. <i>Hier. 1, 38 ;</i> SOPH. <i>El. 996, etc. ;</i> τὰ ἀπ' ἡμέων ἐς ὑμέας ὑπηρετέεται, HDT. <i>4, 139,</i> ce que nous faisons vous est utile ; <i>cf</i>. HDT. <i>1, 108 ;</i> ISOCR. <i>39</i> e, <i>etc. ; particul. en parl. des services que rendent des serviteurs :</i> ὅσα δοῦλοι δεσπόταις ὑπηρετοῦσιν, XÉN. <i>Ages. 1, 22,</i> tous les services que des esclaves rendent à des maîtres ;<br><b>      2</b> obéir à, être docile à, <i>dat</i>. XÉN. <i>Mem. 2, 1, 28 ;</i> PLAT. <i>Leg. 822</i> e, <i>etc. ; avec un acc. de chose :</i> ὑπ. τὸ κελευόμενον, PLUT. <i>Dio. 33,</i> obéir à l’ordre donné, exécuter ce qui est ordonné ;<br><b><i>Moy.</i></b> servir, aider, être <i>ou</i> se mettre au service de, <i>dat</i>. ALCIPHR. <i>1, 11 ;</i> HLD. <i>1, 4 ; 7, 25 et 27 ; abs</i>. τὸ ὑπηρετούμενον, MEMN. (PHOT. <i>Bibl. p. 223</i> a, <i>36 Bkk</i>.).<br><span><b>Étym</b>. ὑπηρέτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπηρετεω - ὑπηρετέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G5257":"<h1>huperetes</h1>\n<p>Strong n° 5257 <i>Prononciation [hoop-ay-ret'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>serviteur\n<ol type=\"a\">\n<li>de rang inférieur, d'un rang de subordonné, subalterne, aide</li>\n<li>tous ceux qui servent avec les mains : un serviteur\n<ol>\n<li>dans le N.T. les huissiers et aides des magistrats, l'officier qui fait exécuter les peines</li>\n<li>la suite d'un roi, serviteurs, le service, les soldats, les serviteurs d'une synagogue</li>\n<li>de tous ceux qui administrent ou remplissent un service</li>\n</ol>\n</li>\n<li>celui qui en aide un autre dans un travail\n<ol>\n<li>un assistant</li>\n<li>le prédicateur de l'évangile</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·ηρέτης, ου (ὁ) :<br>   I</b> rameur, matelot, tout homme d’équipage (autre que les soldats de marine) sous les ordres d’un chef <i>ou</i> patron, DÉM. <i>690, 11 ; cf. 37, 4 ;</i><br><b>   II</b> <i>p. ext</i>. tout homme sous les ordres d’un autre, serviteur, HDT. <i>3, 63 ; 5, 111 ;</i> PLAT. <i>Leg. 620</i> a, <i>720</i> a, <i>873</i> b ; <i>joint à</i> δοῦλοι, <i>dat</i>. PLAT. <i>Pol. 289</i> c, <i>etc. ; p. anal</i>. ὑπηρέτης θεῶν, ESCHL. <i>Pr. 954,</i> serviteur des dieux ; <i>avec le dat</i>. ὑπ. τῷ θεῷ, PLAT. <i>Leg. 773</i> e, serviteur de la divinité ; ὑπ. τοῖς νόμοις, PLAT. <i>Leg. 715</i> c, <i>etc</i>. serviteur des lois ; <i>particul. à Athènes :</i><br><b>      1</b> serviteur qui accompagnait l’hoplite en campagne et vaquait à ses menus soins, <i>sorte de</i> ordonnance de l’hoplite, THC. <i>3, 17 ;</i><br><b>      2</b> exécuteur public aux ordres des Onze, <i>chargé de l’exécution des criminels d’État,</i> XÉN. <i>Hell. 2, 3, 54 ; 2, 4, 8 ;</i> PLAT. <i>Phæd. 116</i> b ;<br><b>      3</b> <i>au plur. sorte de</i> aides de camp <i>ou de</i> adjudants auprès du général, XÉN. <i>Cyr. 2, 4, 4 ; 6, 2, 13, etc</i>.<br><span><b>Étym</b>. ὑπό, ἐρέσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπερετης - ὑπηρέτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> représente le serviteur dans son activité au travail ; non dans sa relation avec une personne, que cette relation soit servile, comme celle de , ou plus volontaire, comme dans le cas de .  contrairement à  indique un esclave, celui qui est en relation servile permanente avec un autre.\n<br><br> est l'exécutant volontaire de tâches, qu'il soit un homme libre ou un esclave ; ce mot a plus de noblesse que .  suggère la subordination.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 20 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (9)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5258":"<h1>hupnos</h1>\n<p>Strong n° 5258 <i>Prononciation [hoop'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sommeil</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὕπνος, ου (ὁ)</b> <span>[ῡ ; <i>souv</i>. ῠ <i>chez les poètes att. v. ci-dessous</i>]</span><br><b>      1</b> sommeil, HOM. ATT. <i>etc. ;</i> ἐν ὕπνῳ, PLAT. <i>Rsp. 476</i> c, <i>etc</i>. dans le sommeil, pendant le sommeil ; ἐν τοῖς ὕπνοις, PLAT. <i>Rsp. 572</i> b ; καθ' ὕπνον ὄντα, SOPH. <i>Tr. 970 ;</i> καθ' ὕπνον, PLAT. <i>Leg. 800</i> a ; κατὰ τὸν ὕπνον, ATT. <i>m. sign. ;</i> περὶ πρῶτον ὕπνον, THC. <i>2, 2 ;</i> AR. <i>Vesp. 31,</i> pendant le premier sommeil ; διὰ μέσων τῶν ὕπνων, PLUT. <i>Them. 28,</i> au milieu du sommeil ; ὕπνος τινὰ ἐπέρχεται, OD. <i>4, 793 ; ou</i> ἱκάνει, IL. <i>1, 610,</i> le sommeil vient trouver qqn ; ὕπνος αἱρεῖ, IL. <i>24, 4, ou</i> λαμϐάνει τινά, SOPH. <i>Ph. 767,</i> le sommeil s’empare de qqn ; ὕπνον λαμϐάνειν, PLAT. <i>Conv. 223</i> b, saisir le sommeil ; ὕπνου τυγχάνειν, AR. <i>Ach. 713,</i> trouver le sommeil ; ὕπνου λαγχάνειν, XÉN. <i>An. 3, 1, 11,</i> obtenir le sommeil ; ἐν ὕπνῳ πίπτειν, PD. <i>I. 4, 39 ;</i> ὕπνῳ πίπτειν, ESCHL. <i>Eum. 68 ;</i> εἰς ὕπνον πεσεῖν, SOPH. <i>Ph. 826,</i> tomber dans le sommeil ; ὕπνῳ δεδμημένος, IL. <i>10, 2 ; ou</i> δαμείς, IL. <i>14, 353,</i> dompté par le sommeil ; ὕπνῳ νικᾶσθαι, ESCHL. <i>Ag. 290 ; ou</i> κρατεῖσθαι, ESCHL. <i>Eum. 148,</i> être vaincu par le sommeil ; ὕπνος ἔχει τινά, IL. <i>10, 4 ;</i> ATT. le sommeil tient qqn ; ἀνεγείρειν ἐξ ὕπνου, OD. <i>15, 44,</i> réveiller ; ἐκ τῶν ὕπνων ἐγείρεσθαι, PLAT. <i>Rsp. 330</i> e, se réveiller ; ἐξ ὕπνου στῆναι, SOPH. <i>Ph. 277,</i> sortir du sommeil et se lever ; καθ' ὕπνον, ATT. pendant le sommeil ; <i>particul</i>. sommeil de la mort, IL. <i>11, 241, etc. ;</i><br><b>      2</b> Hypnos <i>ou</i> le Sommeil <i>personnifié,</i> IL. <i>14, 231 ; 16, 682</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῠ]</span> ESCHL. <i>Sept. 3, Ag. 14, 912, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *su(e/o)p-no-, sommeil ; <i>cf. lat</i>. sopor <i>et</i> somnus, <i>sscr</i>. svápna-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπνος - ὕπνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5259":"<h1>hupo</h1>\n<p>Strong n° 5259 <i>Prononciation [hoop-o']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>par, sous</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπό</b> <span>[ῠ]</span> <i>adv. et prép</i>. sous : <i>adv. (accentué</i> ὕπο) dessous, en dessous : τοὺς δ' ἄρ' ὕπο τρόμος εἷλεν, IL. <i>5, 862,</i> le tremblement les saisit en bas, <i>càd</i>. dans les jambes ; τρομέειν δ' ὕπο φαίδιμα γυῖα, IL. <i>10, 95,</i> en bas, mes membres brillants tremblent ; ἔνθα μοι ἵπποι δώδεκα θήλειαι ὕπο δ' ἡμίονοι, OD. <i>4, 636,</i> là j’ai douze cavales, et sous elles des mulets. <i>Prép. ;</i><br><b>A</b> <i>gén. :</i><br><b>   I. 1</b> de dessous : ἵππους λῦσαι ὑπὸ ζυγοῦ, IL. <i>8, 543 ; 24, 576,</i> délier des chevaux de dessous le joug, dételer des chevaux ; <i>cf</i>. OD. <i>7, 5 ;</i> λύεσθαι ὑπ' ἀρνειοῦ, OD. <i>9, 463,</i> se détacher de dessous le ventre du bélier ; αὖτις ἀναστήσονται ὑπὸ ζόφου, IL. <i>21, 56,</i> ils ressusciteront du royaume des ombres ; ὑπὸ χθονὸς φόωσδε, HÉS. <i>Th. 669</i> (envoyer) de dessous la terre à la lumière ; νεκρὸν ὑπ' Αἴαντος ἐρύειν, IL. <i>17, 235,</i> arracher le cadavre des mains d’Ajax ;<br><b>   II</b> sous :<br><b>      1</b> <i>avec idée d’une chose qui recouvre ou qui est placée sur :</i> ὑπὸ χθονός, IL. <i>8, 14, etc. ;</i> OD. <i>11, 52, etc</i>. sous terre ; ὑπὸ γῆς, PLAT. <i>Ap. 18</i> b, <i>etc. m. sign. ;</i> ὑπ' οὔατος, IL. <i>11, 424 ; 13, 177 ; 16, 339 ;</i> OD. <i>18, 96,</i> sous l’oreille ; ὄσσε ὑπὸ βλεφάρων ἐξεφάανθεν, IL. <i>19, 17,</i> les yeux brillèrent sous les paupières ; <i>avec un verbe de mouv. impliquant l’idée que l’objet dont on parle se fixe au point marqué par</i> ὑπό : τὸν βάλ' ὑπὸ γναθμοῖο καὶ οὔατος, IL. <i>13, 671 ; 17, 617,</i> il le frappa sous la mâchoire et l’oreille ; ὑπὸ στέρνοιο τυχεῖν, IL. <i>4, 106,</i> atteindre sous la poitrine ; <i>avec un verbe de mouv. pour marquer la direction :</i> τοὺς μὲν ὑπὸ χθονὸς πέμψαν, HÉS. <i>Th. 717,</i> ils les envoyèrent sous terre ; <i>fig. dans une inscr. att. pour marquer la dépendance, rar. la subordination :</i> ὑπὸ τῆς βουλῆς (<i>343 av. J.C</i>.) sous la surveillance <i>ou</i> l’autorité du sénat ; <i>v. Meisterh. p. 182, 52 ;</i><br><b>      2</b> au pied de : ἡ πηγὴ ὑπὸ τῆς πλατάνου ῥεῖ, PLAT. <i>Phædr. 230</i> b, la source coule au pied du platane ;<br><b>   III</b> par suite de, par le fait de, par : δαμῆναι ὑπ' αὐτοῦ δουρί, IL. <i>3, 436, etc</i>. être dompté, abattu par la lance de qqn ; θνῄσκειν ὑπό τινος, IL. <i>1, 142, etc</i>. mourir par le fait de qqn ; ἀποθνῄσκειν ὑπό τινος, HDT. <i>1, 137, etc. ;</i> THC. <i>1, 9, etc., m. sign. ;</i> ἀπολέσθαι ὑπό τινος, HDT. <i>3, 32 ;</i> XÉN. <i>Hell. 5, 4, 23, etc</i>. périr par le fait de qqn ; φεύγειν ὑπό τινος, IL. <i>18, 149 ; 19, 73, etc</i>. être mis en fuite par qqn, fuir devant qqn (<i>pour d’autres sens de</i> φεύγειν ὑπό τινος, <i>v</i>. φεύγω) ; ἐκπεσεῖν ὑπό τινος, THC. <i>4, 66, etc</i>. être chassé par qqn ; ἀναστῆναι ὑπό τινος, THC. <i>6, 4, etc</i>. être forcé par qqn d’émigrer ; πάσχειν τι ὑπό τινος, IL. <i>11, 119, etc</i>. se hâter pour échapper à l’attaque d’un lion ; χαλεπῶς ἔχειν ὑπὸ τραυμάτων, PLAT. <i>Theæt. 142</i> b, souffrir de blessures ; <i>de même dans les inscr. att. :</i> σίδηρος καταϐεϐρωμένος ὑπὸ τοῦ ἰοῦ (<i>329 av. J.C</i>.) fer rongé par la rouille ; <i>v. Meisterh. p. 182, 51 ;</i> πράγματα ἔχειν ὑπὸ τῶν λῃστῶν, XÉN. <i>Hell. 5, 1, 5,</i> être molesté par les pirates ; εὖ πράττω ὑπό τινος, SOPH. <i>O.C. 391,</i> j’éprouve, il m’arrive qqe ch. de bon de la part de qqn ; τὴν ἀρχὴν ἀπολέσαι ὑπό τινος, XÉN. <i>An. 3, 4, 11,</i> perdre le pouvoir par le fait de qqn ; νῆες κονάϐησαν ἀϋσάντων ὑπ' Ἀχαιῶν, IL. <i>2, 334,</i> les vaisseaux retentirent du cri des Achéens ; μάλα συχνοὺς ἀποϐαλεῖν ὑπό τινος, XÉN. <i>Hell. 2, 4, 3,</i> perdre beaucoup de monde par les attaques de l’ennemi ; δίκην διδόναι ὑπό τινος, être puni par qqn <i>ou</i> être l’objet d’une vengeance de la part de qqn, XÉN. <i>Cyr. 3, 1, 22 ; ou</i> expier qqe ch. XÉN. <i>Cyr. 7, 5, 40, etc. ;</i> αἰτίαν ἔχειν ὑπό τινος, ESCHL. <i>Eum. 99 ;</i> XÉN. <i>An. 7, 6, 11, etc</i>. être accusé par qqn ; ἔπαινον ἔχειν ὑπό τινος, HDT. <i>9, 78, etc</i>. recueillir des louanges de qqn ; εὖ ἀκούειν ὑπό τινος, XÉN. <i>An. 7, 7, 23, etc</i>. avoir bonne réputation auprès de qqn ; εἶναι ἐν ἀξιώματι ὑπὸ τῶν ἀστῶν, THC. <i>6, 15,</i> être considéré, estimé par les citoyens ; <i>avec un n. abstrait pour rég. :</i> ἀνορούειν ὑπὸ χάρματος, HH. <i>Cer. 372,</i> bondir de joie ; ἐνδακρύειν χαρᾶς ὕπο, ESCHL. <i>Ag. 541, etc</i>. pleurer de joie ; <i>de même :</i> ὑπὸ λύπης, XÉN. <i>An. 3, 1, 3, etc</i>. par l’effet du chagrin ; ὑπὸ δέους, THC. <i>6, 33, etc</i>. par l’effet de la peur, de peur ; ὑπ' ἄλγους, ESCHL. <i>Eum. 183 ;</i> ὑπ' ὀδύνης, PLAT. <i>Conv. 218</i> b, par l’effet de la douleur, de douleur ; ὑπ' ὀργῆς, AR. <i>Vesp. 1083,</i> de colère ; ὑπ' ἀγνοίας, ESCHL. <i>Suppl. 499,</i> par ignorance ; ὑπ' ἀνανδρίας, ESCHL. <i>Pers. 755,</i> par lâcheté ; ὑπ' ἀναισχυντίας, PLAT. <i>Conv. 192</i> a, par impudence ; μνήμης ὕπο, SOPH. <i>O.R. 1131,</i> de mémoire ; <i>avec un n. de pers. ou de chose marquant une circonstance extérieure :</i> ὑπ' ἀπλοίας, THC. <i>2, 85,</i> par suite d’un temps défavorable sur mer ; ὑπὸ τοῦ πλήθους τῶν βελῶν, XÉN. <i>An. 5, 2, 15,</i> par suite de l’abondance des traits ; ὑπ' ἐρημίας, THC. <i>4, 8,</i> par suite du manque d’habitants ; <i>avec le rég. de la pers. par le concours ou l’entremise de laquelle qqe ch. arrive :</i> ὑπ' ἀγγέλων φράζειν, PLAT. <i>Phil. 66</i> a, mander par des messagers ; ὑπὸ κήρυκος προαγορεύειν, HDT. <i>9, 98, ou</i> ἀπειπεῖν, EUR. <i>Alc. 737,</i> annoncer <i>ou</i> défendre par la voix du héraut ; ὑπὸ κήρυκος πωλεῖν, DÉM. <i>Or. 51, § 22,</i> vendre publiquement ; ὑπὸ κήρυκος εὐχὰς ποιεῖσθαι, THC. <i>6, 32,</i> faire une prière que le héraut prononce à haute voix ; <i>avec un subst. au lieu d’un verbe :</i> τὸ ὑπὸ τοῦ νόμου ἐπίταγμα, PLAT. <i>Rsp. 359</i> a, ce qui est ordonné par la loi ; ἡ ὑπό τινος παίδευσις, XÉN. <i>Mem. 2, 1, 34,</i> l’éducation faite par qqn ; ἡ ὑπὸ πάντων τιμή, XÉN. <i>Cyr. 3, 3, 2,</i> témoignages de respect de la part de tous ;<br><b>   IV</b> sous la conduite de, <i>d’où</i> avec accompagnement de : κωμάζειν ὑπ' αὐλοῦ, HÉS. <i>Sc. 281,</i> s’avancer joyeusement au son des flûtes ; στρατεύεσθαι ὑπὸ συρίγγων τε καὶ πηκτίδων καὶ αὐλοῦ, HDT. <i>1, 17,</i> partir pour une expédition au son des fifres, des cithares et de la flûte ; χωρεῖν ὑπ' αὐλητῶν, THC. <i>5, 70,</i> s’avancer au son de la musique des joueurs de flûte ; ἄελλα ὑπὸ βροντῆς εἶσι πέδονδε, IL. <i>13, 796,</i> l’orage se précipite sur le sol avec accompagnement de tonnerre ; δαΐδων ὑπὸ λαμπομενάων, IL. <i>18, 492,</i> à la lueur brillante des torches ; <i>de même :</i> ὑπὸ φανοῦ, XÉN. <i>Lac. 5, 7,</i> à la lumière d’une lanterne ; ὑπὸ πομπῆς, HDT. <i>2, 45,</i> en un cortège solennel ; ὑπὸ κλαυθμῶν, ESCHL. <i>Ag. 1533,</i> au milieu des hurlements de douleur ; ὑπ' οἰωνῶν καλῶν, EUR. <i>Ion 1333,</i> sous de bons auspices ; ὑπὸ σκότου, SOPH. <i>Ant. 692 ;</i> XÉN. <i>Cyr. 4, 6, 4, etc</i>. dans l’obscurité, dans le secret ;<br><b>B</b> <i>Dat. :</i> sous :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> sous, <i>avec idée d’une chose qui recouvre, sans mouv. :</i> ἔρδειν ἑκατόμϐας ὑπὸ πλατανίστῳ, IL. <i>2, 307,</i> offrir des hécatombes sous un platane ; ὑπὸ δρυῒ δαῖτα πένεσθαι, IL. <i>18, 558,</i> préparer un repas sous un chêne ; ὑπὸ θάμνῳ κατακεῖσθαι, IL. <i>17, 677,</i> être couché sous un buisson ; ὑπ' ἠελίῳ τε καὶ οὐρανῷ ναιετάουσι, IL. <i>4, 44,</i> les villes sont placées sous le soleil et sous le ciel ; κρύφθη ὑπ' ἀσπίδι, IL. <i>13, 405,</i> il se cacha, <i>càd</i>. s’abrita sous le bouclier ; στῆ δ' ἄρ' ὑπ' Αἴαντος σάκεϊ, IL. <i>8, 267,</i> il se tint sous le bouclier d’Ajax ; ἔχειν τι ὑπὸ τῷ ἱματίῳ, PLAT. <i>Phædr. 228</i> e, avoir qqe ch. sous son vêtement ; πῦρ ἀνακαίειν ὑπὸ τρίποδι, OD. <i>10, 359,</i> allumer du feu sous un trépied ; ὑφ' ἅρμασιν, IL. <i>8, 402, 416, etc</i>. attelés au char ; οἱ ὑπὸ τοῖς ἅρμασιν ἵπποι, XÉN. <i>Cyr. 6, 4, 1,</i> les chevaux de trait ; ὑπὸ ποσσὶ μέγα στοναχίζετο γαῖα, IL. <i>2, 784,</i> la terre résonnait faisant un grand bruit sous leurs pieds ; ὑπὸ ποσσὶ κονίσαλος ὤρνυτο, IL. <i>3, 13,</i> la poussière s’élevait sous leurs pas ; ὑπ' ὀφρύσιν ὄσσε, IL. <i>14, 236,</i> les yeux sous les sourcils ; ὄσσε ὑπὸ βλεφάροισι, IL. <i>24, 637,</i> les yeux sous les paupières ; <i>avec des verbes de mouv. pour marquer l’idée de repos qui succède au mouv. :</i> δέμνι' ὑπ' αἰθούσῃ θέμεναι, IL. <i>24, 644,</i> déposer des lits sous la galerie couverte ; <i>cf</i>. OD. <i>4, 297 ; 22, 449 ;</i> Σαρπηδόνα εἷσαν ὑπὸ φηγῷ, IL. <i>5, 693,</i> ils déposèrent Sarpédon sous un chêne ; κατακρύψασ' ὑπὸ κόλπῳ, OD. <i>15, 469,</i> l’ayant caché sous son sein ; <i>cf</i>. OD. <i>3, 329 ;</i> ἔζευξαν ὑφ' ἅρμασιν ἵππους, OD. <i>3, 478,</i> ils attelèrent les chevaux aux chars ; ὑπὸ δ' ἄξοσι φῶτες ἔπιπτον, IL. <i>16, 378,</i> les hommes tombaient sous les essieux ; ὑπὸ τῷ ἵππῳ πίπτειν, XÉN. <i>Cyr. 3, 1, 37,</i> tomber sous le cheval ;<br><b>      2</b> <i>p. anal</i>. au bas de, au pied de, <i>particul. en parl. de montagnes :</i> ὑπὸ Τμώλῳ, IL. <i>2, 866,</i> au pied du Tmôlos ; ὑπὸ Νηΐῳ, OD. <i>1, 186,</i> au pied du promontoire Nèïon ; τοῦ ὅρους, ὑφ' ᾧ ἦν ἡ κώμη, XÉN. <i>An. 3, 4, 24,</i> de la montagne au bas de laquelle était le village ; μάρνασθαι τείχει ὕπο Τρώων, IL. <i>17, 404,</i> combattre sous les murs des Troyens ; πέτρῃ ὕπο γλαφυρῇ εὗδον, OD. <i>14, 533,</i> ils dormaient sous un rocher creux ; ἱδρύσαντο ὑπὸ τῇ ἀκροπόλει ἱρόν, HDT. <i>6, 105,</i> ils posèrent les fondations du temple au bas de la citadelle ; ἔστι βασίλεια ὑπὸ τῇ ἀκροπόλει, XÉN. <i>An. 1, 2, 8,</i> il y a un palais royal au pied de la citadelle ; <i>avec un rég. de pers. :</i> ὑπό τινι κατακλίνεσθαι, PLAT. <i>Conv. 222</i> e, prendre place au-dessous de qqn ; <i>fig. en parl. d’un rapport de dépendance d’une idée particulière à une idée générale :</i> ὄργανα πάντα τά τε ὑπὸ τῇ μουσικῇ καὶ τὰ ὑπὸ ταῖς ἄλλαις τέχναις, PLAT. <i>Hipp. ma. 295</i> d, tous les instruments dépendant du domaine de la musique et des autres arts ; <i>cf</i>. PLAT. <i>Rsp. 511</i> b, <i>etc. ;</i><br><b>      3</b> <i>fig. pour marquer l’infériorité, la dépendance :</i> δέδμητο δὲ λαὸς ὑπ' αὐτῷ, OD. <i>3, 304,</i> le peuple était sujet sous lui <i>càd</i>. soumis à son autorité ; <i>cf</i>. IL. <i>9, 156, 298, etc. ;</i> γυναῖκες ὑπ' ἀνδράσιν, OD. <i>7, 68,</i> les femmes sous l’autorité des hommes ; εἶναι ὑπό τινι, THC. <i>1, 32 ;</i> PLAT. <i>Rsp. 574</i> e, être sous la dépendance de qqn ; τὰ θηρία τὰ ὑπὸ τοῖς ἀνθρώποις, PLAT. <i>Rsp. 563</i> c, les animaux soumis à l’homme ; ὑφ' ἑαυτῷ ἔχειν, XÉN. <i>Cyr. 2, 1, 26, etc</i>. avoir sous sa domination ; τεθραμμένος ὑπό τινι, PLAT. <i>Rsp. 301</i> c, <i>etc</i>. élevé sous la direction de qqn ; ὑπὸ Καίσαρι στρατεύεσθαι, PLUT. <i>Cic. 44,</i> servir sous César ; <i>de même avec les verbes qui marquent une idée de mouv. sous forme de changement d’état, quand on veut marquer ce changement comme durable :</i> γίγνεσθαι ὑπό τινι, HDT. <i>6, 96, etc. ;</i> THC. <i>7, 64 ;</i> XÉN. <i>An. 7, 2, 7, etc</i>. tomber sous la domination de qqn, devenir le sujet de qqn ; ὑφ' ἑαυτῷ ποιεῖσθαι, HDT. <i>7, 157, etc</i>. amener en sa puissance, soumettre à soi-même ;<br><b>      4</b> sous l’influence de, par le fait de, par suite de, à cause de, par : εἴκει δ' ὑπὸ βῶλος ἀρότρῳ, OD. <i>18, 374,</i> la glèbe cède sous la charrue ; ὑπὸ δουρὶ δαμῆναι, IL. <i>5, 653,</i> succomber sous la lance ; ὑπὸ χερσί τινος δαμῆναι, IL. <i>2, 860, etc</i>. être dompté <i>ou</i> vaincu par la main de qqn ; ὑπὸ χερσί τινος θανέειν, IL. <i>15, 289 ; ou</i> ὀλέσαι ψυχήν, IL. <i>13, 763 ; ou</i> ὀλέσαι θυμόν, IL. <i>24, 638, etc</i>. mourir de la main de qqn, <i>ou</i> perdre la vie par la main de qqn ; δαμάσαι τινὰ ὑπὸ χερσί τινος, IL. <i>3, 352 ; 6, 368, etc</i>. faire périr qqn par la main de qqn ; ὑπὸ γαμφηλῇσι λέοντος ὤλετο, IL. <i>16, 489,</i> il périt sous les dents d’un lion, déchiré par les dents d’un lion ; σῷ δ' ὑπὸ δουρὶ πόλιν πέρθαι, IL. <i>16, 708,</i> détruire la ville au moyen de ta lance ; ἐμῷ ὑπὸ δουρὶ τυπείς, IL. <i>11, 433 ; 12, 250, etc</i>. frappé par ma lance ; ὑπὸ Τρώεσσι δαμῆναι, IL. <i>13, 98,</i> être vaincu par les Troyens ; ὑπ' Ἀτρείδῃ πῖπτε κάρηνα Τρώων, IL. <i>11, 158,</i> les têtes des Troyens tombaient sous les coups de l’Atride ; ὑπὸ Πατρόκλῳ κτεινόμενος, IL. <i>16, 490,</i> blessé par Patrocle ; ἐν κονίῃσι πίπτειν ὑπ' ἀνδράσι δυσμενέεσσιν, IL. <i>6, 453,</i> tomber dans la poussière frappés par les guerriers irrités ; ἐφόϐηθεν ὑφ' Ἕκτορι, IL. <i>15, 637,</i> ils furent mis en fuite par Hector ; νούσῳ ὑπ' ἀργαλέῃ φθίσθαι, IL. <i>13, 667,</i> mourir consumé par suite d’une maladie ; ὦρτο δὲ κῦμα πνοιῇ ὕπο λιγυρῇ, IL. <i>23, 215,</i> et le flot se souleva gonflé par le souffle du vent sonore ; τίκτειν τινὰ ὑπό τινι, IL. <i>2, 714, 728, etc</i>. mettre au monde un enfant engendré par qqn ; <i>en ce sens rar. en prose (d’ord</i>. ὑπό <i>et le gén. ; v. ci-dessous</i>) ; ὑπὸ μάστιξι διορύττειν τὸν Ἄθω, PLUT. <i>M. 470</i> e, percer le mont Athos en travaillant sous le fouet ; ὑπὸ δικαιοσύνῃ διάγειν τὸν βίον, PLAT. <i>Ep. 335</i> d, gouverner sa vie en se soumettant aux règles de la justice, d’après les règles de la justice ; <i>en ce sens, d’ord. en prose ;</i><br><b>      5</b> sous la conduite de, avec accompagnement de : θεῶν ὑπ' ἀμύμονι πομπῇ, IL. <i>6, 171,</i> sous la conduite sûre des dieux ; πομπῇ ὑφ' ἡμετέρῃ, OD. <i>7, 193,</i> sous notre conduite, accompagné par nous ; εὐχαῖς ὕπο, PD. <i>I. 5, 44,</i> avec accompagnement de vœux ; ὑπ' αὐλητῆρι, HÉS. <i>Sc. 283,</i> accompagné par la musique d’un joueur de flûte ; ὑπ' ὀρχηθμῷ καὶ ἀοιδῇ, HÉS. <i>Sc. 282,</i> avec accompagnement de danse et de chant ; ὑπ' αὐλῷ καὶ τυμπάνοις, LUC. <i>D. deor. 2, 2,</i> au son de la flûte et des tambours ; ὑπὸ ῥάϐδοις καὶ πελέκεσι, PLUT. <i>Popl. 10,</i> (marcher) avec les faisceaux et les haches ; ὑπὸ σκότῳ, ESCHL. <i>Ag. 1030 ;</i> EUR. <i>Ph. 1214, etc</i>. dans l’obscurité, dans le secret ; ὑπὸ φωτί, PLUT. <i>Galb. 14,</i> à la lumière ;<br><b>C</b> <i>Accus. :</i> sous :<br><b>   I</b> <i>avec mouv. :</i><br><b>      1</b> ἰέναι ὑπὸ γαῖαν, IL. <i>18, 333,</i> aller sous terre ; <i>cf</i>. OD. <i>20, 81 ;</i> νέεσθαι ὑπὸ ζόφον, IL. <i>23, 51 ;</i> ἐλθεῖν ὑπὸ ζόφον, OD. <i>11, 57,</i> aller dans le royaume des ombres ; κρύπτει ὑπὸ γᾶν, PD. <i>P. 9, 81,</i> cacher sous terre ; δῦναι ὑπὸ κῦμα, IL. <i>18, 145 ;</i> ὑπὸ πόντον, OD. <i>11, 253,</i> s’enfoncer sous le flot, sous la mer ; παῖς ὣς ὑπὸ μητέρα ἰών, IL. <i>8, 271,</i> comme un enfant qui se réfugie derrière la robe de sa mère ; ὑπὸ ζυγὸν ἄγειν ἵππους, IL. <i>5, 731 ; 23, 294, etc</i>. mener des chevaux sous le joug ; ὑφ' ἅρμα ἀγαγεῖν ἵππους, ESCHL. <i>Pr. 465,</i> atteler des chevaux à un char ; ἀμϐροσίην ὑπὸ ῥῖνα θῆκε, OD. <i>4, 445,</i> elle plaça l’ambroisie sous nos narines ; ὑπ' ὀστέον ἤλυθ' ἀκωκή, IL. <i>5, 67,</i> la pointe sortit sous l’os ; <i>cf</i>. IL. <i>13, 652 ;</i><br><b>      2</b> <i>p. anal</i>. sous, au bas de, au pied de : ὑπὸ Ἴλιον ἐλθεῖν, IL. <i>2, 216, etc</i>. venir sous les murs de Troie ; ὑπὸ πτόλιν αἰπύ τε τεῖχος ἵξεσθαι, IL. <i>11, 181,</i> être sur le point d’arriver sous les murs et les remparts élevés de la ville ; ὑπὸ τεῖχος ἰέναι, IL. <i>12, 264, etc</i>. venir sous les murs de la ville ; <i>cf</i>. IL. <i>13, 652 ;</i> ὑπὸ δικαστήριον ἄγειν τινά ; HDT. <i>6, 104,</i> citer qqn en justice (<i>litt</i>. sous la tribune du juge) ; <i>de même</i> ὑπὸ τοὺς ἐφόρους ὑπάγειν, HDT. <i>6, 82 ;</i> ὑπὸ τὸν δῆμον ὑπάγειν, HDT. <i>6, 137,</i> citer devant les éphores, devant le peuple ;<br><b>      3</b> <i>p. ext</i>. au fond de : ὑπὸ σπέος ἤλασε μῆλα, IL. <i>4, 279,</i> il poussa les brebis au fond de la caverne ;<br><b>      4</b> à l’abri, sous, <i>par suite,</i> derrière : ὑπὸ θύρην, HDT. <i>1, 12,</i> derrière la porte ; ἀνακεχωρηκότες ὑπὸ τὸ τεῖχος καὶ τὰς πύλας, XÉN. <i>Hell. 6, 5, 8,</i> s’étant retirés derrière le mur et les portes ;<br><b>   II</b> <i>sans mouv. :</i><br><b>      1</b> sous : ὑπὸ γῆν εἶναι, HDT. <i>7, 114, etc</i>. être sous terre, dans les enfers ; οὔτε ὕπεστι οἰκήματα ὑπὸ γῆν, HDT. <i>2, 127,</i> et il n’y a pas de chambres souterraines ; ὅσσοι ἔασιν ὑπ' ἠῶ τ' ἠέλιόν τε, IL. <i>5, 267,</i> tous les chevaux qui sont sous l’aurore et sous le soleil ; ὑπ' αὐγὰς ὁρᾶν τι, EUR. <i>Hec. 1144, etc</i>. considérer qqe ch. à la lumière ; ὑπὸ ταὐτὸν ἱμάτιον κατακεῖσθαι, LUC. <i>V. auct. 15,</i> être étendus sous une seule et même couverture ;<br><b>      2</b> au pied de : Ἀρκαδίη ὑπὸ Κυλλήνης ὄρος, IL. <i>2, 603,</i> l’Arcadie qui s’étend au pied du mont Kyllènè ; χώρη ὑπὸ τὸν Ὑμησσὸν ἐοῦσα, HDT. <i>6, 137,</i> pays qui se trouve au pied du mont Hymette ; τὸ Πελασγικὸν τὸ ὑπὸ τὴν ἀκρόπολιν, THC. <i>2, 17,</i> le mur pélasgique qui s’étend au bas de la citadelle ; αἱ ὑπὸ τὸ ὄρος κῶμαι, XÉN. <i>An. 7, 4, 5,</i> les villages situés au pied de la montagne ; ὑπό τινα καθίζεσθαι, PLUT. <i>Artax. 15, ou</i> κατακλίνεσθαι, LUC. <i>Conv. 9,</i> s’asseoir <i>ou</i> se coucher sur un lit de table au-dessous de qqn ; <i>fig. en parl. d’un rapport de dépendance d’une idée particulière à une idée générale, de l’espèce au genre :</i> ὑπὸ τὸ αὐτὸ εἶδος ἐστί, ARSTT. <i>Top. 1, 5,</i> ce qui appartient au même genre ; οἱ ὑπὸ τὸ ψεῦδος τεταγμένοι, LUC. <i>Ind. 20,</i> ceux appartenant à la catégorie des pseudonymes ; <i>adv</i>., ὑπό τι, AR. <i>Vesp. 1290 ;</i> PLAT. <i>Gorg. 493</i> c, <i>etc. ;</i> HPC. <i>72</i> d, <i>etc</i>. en qqe mesure ;<br><b>      3</b> <i>fig. pour marquer la subordination ou la dépendance :</i> ὑφ' ἑαυτὸν ποιεῖσθαι, HDT. <i>1, 102 ;</i> THC. <i>4, 60, etc</i>. mettre sous son pouvoir, soumettre à soi-même ; γίγνεσθαι ὑπό τινα, THC. <i>1, 110,</i> tomber sous la domination de qqn ; εἶναι ὑπὸ βασιλέα, HDT. <i>7, 108,</i> être sous la domination du roi ; οἱ ὑπό τινα, XÉN. <i>Cyr. 3, 3, 6, etc</i>. les sujets, les subordonnés de qqn ; οἱ ὑπό τινα ἄρχοντες, XÉN. <i>Cyr. 2, 1, 22,</i> ceux qui commandent sous les ordres de qqn ; <i>avec idée de protection :</i> εἶναι ὑπὸ τὸν πεζὸν στρατόν, HDT. <i>9, 96,</i> être sous la protection de l’armée de terre ; ὑπὸ τὸν στρατὸν καταφυγεῖν, HDT. <i>9, 96,</i> se réfugier sous la protection de l’armée de terre ;<br><b>      4</b> <i>avec idée de temps,</i> près de, aux environs de, à l’approche de : ὑπὸ νύκτα, IL. <i>22, 102 ;</i> HDT. <i>6, 2,</i> à l’entrée de la nuit ; ὑπὸ τὴν κατάλυσιν τοῦ πολέμου, XÉN. <i>Mem. 2, 8, 1,</i> peu de temps avant (<i>litt</i>. vers) la fin de la guerre ; <i>ou</i> durant, pendant : ὑπὸ τοὺς αὐτοὺς χρόνους, THC. <i>1, 100 ; 2, 27, etc</i>. à la même époque ; ὑπὸ τὸν χρόνον τοῦτον, THC. <i>3, 92, etc. ;</i> ὑπὸ τοῦτον τὸν χρόνον, THC. <i>8, 73, etc</i>. à cette époque ; ὑπὸ τὸν σεισμόν, THC. <i>4, 56,</i> à l’époque du tremblement de terre ; πάνθ' ὑπὸ μηνιθμόν, IL. <i>16, 202,</i> pendant toute ma rancune, tant que je gardai rancune ; ὑπὸ ταῦτα, HDT. <i>2, 142,</i> pendant ce temps ; ὑπὸ τὸν νηὸν κατακαέντα, HDT. <i>1, 51,</i> à l’époque où le temple fut brûlé ;<br><b>      5</b> sous la conduite de, <i>d’où</i> avec accompagnement de : ὑπ' ὄρχησιν καὶ ᾠδήν, PLAT. <i>Leg. 670</i> a, avec accompagnement de danse et de chant ; ὑπὸ τὸν αὐλὸν διαλέγεσθαί τινι, XÉN. <i>Conv. 6, 3,</i> s’entretenir avec qqn au son de la flûte ;<br><b>D</b> <i>Rem. :</i><br><b>   I</b> <i>place de</i> ὑπό :<br><b>      1</b> ὑπό <i>se place souvent en poésie après son rég. ; il s’accentue alors</i> ὕπο : δηΐων ὕπο, IL. <i>16, 591 ; 18, 220 ;</i> σκήπτρου ὕπο, IL. <i>2, 268 ;</i> χαρᾶς ὕπο, ESCHL. <i>Ag. 541 ;</i> λύρας ὕπο, EUR. <i>Ph. 824 ;</i> πνοιῇ ὕπο, OD. <i>4, 402 ;</i> ὕπνῳ ὕπο, IL. <i>24, 634, etc. ;</i> εὐχαῖς ὕπο, PD. <i>I. 5, 44 ;</i><br><b>      2</b> <i>de même, en poésie il peut se placer entre le subst. qui lui sert de rég. et l’adj. ou le part. qui accompagne ce subst. :</i> δαΐδων ὑπὸ λαμπομενάων, IL. <i>18, 492 ;</i><br><b>      3</b> <i>de même encore, en poésie il peut être séparé de son régime par plusieurs mots :</i> ὑπὸ δὲ θρῆνυς ποσὶν ἦεν, IL. <i>18, 390 ;</i> ὑπὸ χθὼν σμερδαλέον κονάϐιζε ποδῶν, IL. <i>2, 465, etc. ;</i><br><b>   II</b> <i>en composition ὑπό marque :</i><br><b>      1</b> <i>l’idée de</i> être sous, <i>sans mouv</i>. (<i>v</i>. ὑπεῖναι, ὑπολείπειν, ὑπογάστριον, ὑπόγειος, <i>etc.), avec mouv</i>. (<i>v</i>. ὑπάγειν, ὑποϐάλλειν, ὑφαιρεῖν, <i>etc</i>.) ;<br><b>      2</b> <i>une idée de subordination</i> (<i>v</i>. ὑποτάσσειν, ὑπακούειν, ὑπογραμματεύς, ὑποστράτηγος, <i>etc</i>.) ;<br><b>      3</b> <i>l’idée de</i> agir en dessous (<i>v</i>. ὑπάγειν, ὑφαιρεῖν, ὑπέρχεσθαι, <i>etc</i>.) ;<br><b>      4</b> <i>l’idée de</i> approcher de, être voisin de, <i>au sens d’un dim</i>. (<i>v</i>. ὑπόλευκος, ὑπόπικρος, ὑποϐρέχειν, <i>etc</i>.) ; ὑπό <i>perd sa voy. finale en composition, et le</i> π <i>de</i> ὑπ- <i>s’assimile avec la consonne suivante dans</i> ὑϐϐάλλειν <i>pour</i> ὑποϐάλλειν.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. ὑπαί (<i>cf</i>. διαί) <i>devant</i> δ, IL. <i>3, 217 ; 11, 417, etc. ; et dev</i>. π, IL. <i>2, 824 ; non dev</i>. λ, ν, ρ, ϝ <i>ou dev. une voy. ; de même dans le composé</i> ὑπαιδείδοικα, HH. <i>Merc. 165 ; qqf. chez les poètes att</i>. ESCHL. <i>Ag. 892, 944 ; Eum. 417 ;</i> SOPH. <i>El. 711, 1418 ;</i> EUR. <i>El. 1186 ;</i> AR. <i>Ach. 970 ; éol</i>. ὐπά, ALC. <i>39</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *upo, sous ; <i>cf. lat</i>. sub, <i>sscr</i>. úpa.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπο - ὑπό</font>\n<br><br>une préposition primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n228 fois dans 209 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (31)</li>\n<li>Marc (11)</li>\n<li>Luc (35)</li>\n<li>Jean (4)</li>\n<li>Actes (43)</li>\n<li>Romains (13)</li>\n<li>1 Corinthiens (20)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (14)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (9)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (5)</li>\n<li>3 Jean (2)</li>\n<li>Jude (3)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G5260":"<h1>hupoballo</h1>\n<p>Strong n° 5260 <i>Prononciation [hoop-ob-al'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter ou mettre sous</li>\n<li>suggérer à l'esprit</li>\n<li>instruire en privé, instiguer, corrompre ou persuader (quelqu'un) d'une manière illicite de réaliser une mauvaise action ou de commettre un crime</li>\n<li>persuader (une personne spéc. un témoin) de faire un faux témoignage, suborner, soudoyer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·ϐάλλω</b> <span>(<i>f</i>. -ϐαλῶ, <i>ao.2</i> ὑπέϐαλον, <i>etc</i>.)</span><br><b>   I</b> jeter sous, mettre sous :<br><b>      1</b> <i>avec rég. dir. à l’acc. ou au gén. partitif :</i> λῖτα, OD. <i>10, 353,</i> jeter un tapis sous ; τῶν Μιλησίων ἐρίων, EUB. (ATH. <i>553</i> b) mettre dessous des tapis de Milet ; τι ὑπὸ τὴν τράπεζαν, DC. <i>66, 1,</i> jeter qqe ch. sous la table ; <i>particul</i>. placer sous pour allaiter : μαστῷ γυναικός, EUR. <i>Alc. 639,</i> placer un petit enfant sous le sein d’une femme, le suspendre au sein d’une femme ; σκυλάκιον ὑφ' ἑτέραν κύνα, XÉN. <i>Cyn. 7, 3,</i> donner un petit chien à allaiter à une autre chienne ; <i>ou</i> pour couvrir un animal : αἶγας τοῖς τράγοις, LGS <i>3, 21,</i> faire saillir des chèvres par les boucs ;<br><b>      2</b> jeter en bas, poser en bas, abaisser : τοὺς δακτύλους, LUC. <i>Harm. 1,</i> poser les doigts sur la flûte en soufflant ; τὰ ὄμματά τινι, PLUT. <i>M. 522</i> a, jeter les yeux sur qqe ch. ; <i>en mauv. part :</i> τινὰ τοῖς θηρίοις, POL. <i>1, 82, 2,</i> exposer qqn aux bêtes ; <i>fig. :</i> τὴν πατρίδα ὑπὸ τὴν ἐξουσίαν τινός, POL. <i>17, 15, 3,</i> livrer la patrie au pouvoir de qqn ; ἑαυτὸν ἐχθροῖς, EUR. <i>H.f. 1384 ;</i> Θηϐαίοις, ESCHN. <i>66, 25,</i> se livrer à ses ennemis, aux Thébains ;<br><b>   II</b> suggérer, <i>particul. :</i><br><b>      1</b> indiquer, dicter, souffler : ὑ. καὶ διδάσκειν ἃ χρὴ γράφειν, ESCHN. <i>57, 2,</i> dicter et enseigner ce qu’il faut écrire ; ὑ. παιδὶ τὸν λόγον, ISOCR. <i>280</i> e, dicter à un enfant ce qu’il doit dire ; <i>abs</i>. ὑποϐάλλειν δυνήσεσθε ἤν τι ἐπιλανθάνωνται, XÉN. <i>Cyr. 3, 3, 55,</i> vous pourrez leur indiquer, s’ils oublient qqe ch. ; <i>cf</i>. PLAT. <i>Gorg. 491</i> a, <i>etc. ;</i><br><b>      2</b> <i>en gén</i>. inspirer, exciter : ἡδονάς, PLUT. <i>Alc. 6,</i> inspirer le goût des plaisirs ; ἐλπίδα τινί, DC. <i>49, 11,</i> une espérance à qqn ;<br><b>   III</b> objecter, interrompre, <i>sel. d’autres,</i> souffler, suggérer (<i>v. le sens</i> II, 1) IL. <i>19, 80 ;</i><br><b>   IV</b> lancer secrètement, suborner : τινά, APP. <i>Civ. 1, 74,</i> qqn ;<br><b>   V <b><i>Moy.</i></b><br>      1</b> jeter <i>ou</i> mettre sous soi : πορφυρίδας, LUC. <i>Conv. 13,</i> des tapis de pourpre ; <i>fig</i>. soumettre à son autorité, <i>d’où en gén</i>. s’emparer de, s’approprier : ἀλλότρια, STR. <i>790,</i> le bien d’autrui ; δόξαν, PLUT. <i>Pomp. 31,</i> la gloire d’autrui ;<br><b>      2</b> jeter en dessous, <i>d’où</i> poser les fondements de : πόλιν, STR. <i>556,</i> d’une ville ; <i>fig. en parl. d’un ouvrage, d’un récit,</i> PLUT. <i>Dem. 2 ;</i><br><b>      3</b> supposer <i>ou</i> substituer frauduleusement, <i>en parl. de femmes qui substituent leurs enfants :</i> ὑποϐάλλεσθαι παιδίον, AR. <i>Th. 340, 407, 565 ;</i> HDT. <i>5, 41 ;</i> PLAT. <i>Rsp. 538</i> a ; DÉM. <i>563, 5, etc</i>. faire passer pour sien un enfant supposé ; <i>fig</i>. ὑποϐαλλόμενοι κλέπτουσι μύθους, SOPH. <i>Aj. 188,</i> ils trompent par de faux discours (<i>litt</i>. en supposant des discours).<br><span><b><span class=\"arrow\"></span></b> <i>Inf. épq</i>. ὑϐϐάλλειν, IL. <i>19, 80</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποβαλλω - ὑποβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5261":"<h1>hupogrammos</h1>\n<p>Strong n° 5261 <i>Prononciation [hoop-og-ram-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une copie écrite, incluant toutes les lettres de l'alphabet, donnée aux débutants comme une aide pour apprendre à les tracer</li>\n<li>un exemple mis devant quelqu'un, un modèle</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπογραμμός, οῦ (ὁ) :<br>      1</b> modèle, formule, SPT. <i>2Macc. 2, 28 ;</i> NT. <i>1Petr. 2, 21 ;</i><br><b>      2</b> modèle d’écriture, CLÉM. <i>675</i>.<br><span><b>Étym</b>. ὑπογράφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπογραμμος - ὑπογραμμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5262":"<h1>hupodeigma</h1>\n<p>Strong n° 5262 <i>Prononciation [hoop-od'-igue-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un signe suggestif d'une chose, le dessin d'une chose, la représentation, une figure, une copie</li>\n<li>un exemple : pour imitation\n<ol type=\"a\">\n<li>d'une chose qui doit être imitée</li>\n<li>pour un avertissement, d'une chose qui doit être évitée</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπόδειγμα, ατος (τὸ) :<br>      1</b> signe, marque, indice, XÉN. <i>Eq. 2, 2 ;</i><br><b>      2</b> modèle, exemple, POL. <i>3, 17, 8 ;</i> ANTH. <i>6, 342</i>.<br><span><b>Étym</b>. ὑποδείκνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποδειγμα - ὑπόδειγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5263":"<h1>hupodeiknumi</h1>\n<p>Strong n° 5263 <i>Prononciation [hoop-od-ike'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>montrer en plaçant sous (c.à.d. devant) les yeux</li>\n<li>exposer par des mots et des arguments, c.à.d. enseigner</li>\n<li>apprendre en faisant connaître les choses futures</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·δείκνυμι :<br>      1</b> montrer, faire entrevoir : τινί τι, HDT. <i>1, 32,</i> qqe ch. à qqn ;<br><b>      2</b> montrer, <i>en gén</i>. HPC. <i>Coac. 196 ;</i><br><b>      3</b> offrir en exemple, présenter comme modèle, <i>acc</i>. ARSTT. <i>Poet. 4, 12 ;</i> ISOCR. <i>268</i> a ;<br><b>      4</b> montrer indirectement, enseigner : τινί <i>avec un relat</i>. ISOCR. <i>38</i> d, enseigner à qqn (quel, comment, <i>etc.) ; postér</i>. τινί <i>avec un inf</i>. NT. <i>Matth. 3, 7,</i> enseigner à qqn à, <i>etc. ;</i><br><b><i>Moy.</i></b> montrer secrètement, <i>acc</i>. HDT. <i>7, 217</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Moy. ao. part. ion</i>. ὑποδεξάμενος, HDT. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποδεικνυμι - ὑποδείκνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G5264":"<h1>hupodechomai</h1>\n<p>Strong n° 5264 <i>Prononciation [hoop-od-ekh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>recevoir comme invité, accueillir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·δέχομαι</b> <span>(<i>f</i>. ὑποδέξομαι, <i>ao</i>. ὑπεδεξάμην, <i>rar</i>. ὑπεδέχθην)</span><br><b>   I</b> recevoir sous son toit, <i>d’où :</i><br><b>      1</b> accueillir, recevoir, protéger : τινα, IL. <i>6, 136, etc</i>. qqn ; <i>cf</i>. LUC. <i>D. mar. 8, 1 ; 14, 3 ; particul</i>. recevoir dans sa maison, dans sa ville <i>ou</i> son pays, accorder l’hospitalité : τινα, IL. <i>9, 480 ;</i> OD. <i>14, 52, etc. ;</i> HH. <i>Cer. 226 ;</i> PLAT. <i>Men. 91</i> a, <i>etc</i>. à qqn ; τὸν ξεῖνον οἴκῳ, OD. <i>16, 70,</i> recevoir l’hôte dans sa maison ; τινα οἰκίοισι, HDT. <i>1, 41, 44,</i> recevoir qqn dans sa maison ; ὑπ. ἱκέτας, EUR. <i>Her. 757 ;</i> φυγάδας, THC. <i>5, 83,</i> accueillir des suppliants, des exilés ; φρουρὰν ὑπ. DÉM. <i>1334, 21 ; 1343, 9,</i> recevoir une garnison ennemie ; <i>abs</i>. ὁ ὑποδεξάμενος, ISOCR. <i>192</i> e, celui qui a recueilli un fugitif ; ὁ ὑποδεχόμενος, EPICT. (STOB. <i>Fl. 4, 92</i>) celui qui reçoit, l’amphitryon ; <i>avec un n. de chose pour suj. :</i> πόλις ὑπ. τινα, XÉN. <i>Hell. 4, 8, 21,</i> une ville accueille qqn en ami ; ἡ ὑποδεξαμένη (χώρα) PLAT. <i>Menex. 237</i> c, le pays qui a recueilli qqn ; <i>en mauv. part, au propre :</i> γαῖα ὑπέδεκτο, PD. <i>N. 10, 14,</i> la terre recueillit dans son sein, <i>càd</i>. engloutit ; <i>avec un n. de chose pour rég. :</i> ὑπ. εὐχάς, HÉS. <i>Th. 419,</i> accueillir, exaucer des prières, des vœux ; διαϐολάς, LYS. <i>172, 11,</i> accueillir des imputations, y prêter l’oreille ; <i>avec un n. de chose pour suj. et un n. de chose pour rég. :</i> αἱ τοῦ Νείλου λίμναι ὑπ. τὰς χιόνας ἀπὸ τοῦ ὄρους, PTOL. <i>4, 8, 3,</i> les marais du Nil reçoivent la neige fondue des montagnes ; πῆμα ὑπ. τινα, OD. <i>14, 275,</i> la douleur atteint qqn ; <i>abs</i>. στυγερὸς ὑπεδέξατο κοῖτος, OD. <i>22, 470,</i> une triste couche les reçut ;<br><b>      2</b> <i>avec idée d’hostilité,</i> accueillir <i>ou</i> recevoir (l’ennemi), soutenir une attaque, un choc (de l’ennemi) HÉS. <i>Sc. 442 ;</i> HDT. <i>6, 104 ;</i> XÉN. <i>Cyr. 1, 6, 35 ; en parl. de chasseurs,</i> XÉN. <i>Cyr. 2, 4, 20 ; d’où</i> supporter, subir : βίας, OD. <i>13, 310 ; 16, 189,</i> des violences ;<br><b>      3</b> accepter, agréer, <i>acc</i>. HDT. <i>8, 106 ; particul</i>. dire oui, se déclarer partisan de, HDT. <i>4, 167 ;</i> οὐχ ὑπ. HDT. <i>3, 130 ; 6, 69,</i> dire non, nier ;<br><b>   II</b> <i>au propre, en parl. d’une femme,</i> recevoir dans son sein, concevoir, <i>acc</i>. HPC. <i>Aër. 292 ;</i> XÉN. <i>Mem. 2, 2, 5 ;</i><br><b>   III</b> suivre immédiatement, venir après, <i>en parl. de pers</i>. POSIDON. (ATH. <i>152</i> b) ; <i>avec idée de lieu :</i> être contigu <i>ou</i> confiner : τὸ πρὸς τὴν ἠῶ θάλασσα ὑποδέκεται, HDT. <i>7, 176,</i> la mer succède à la partie du pays située vers l’Orient, <i>càd</i>. borne le pays du côté de l’Orient ; ὑπ. μέλος, ESCHL. <i>Suppl. 1023,</i> reprendre le chant immédiatement après un autre, répondre ;<br><b>   IV</b> prendre sur soi, <i>d’où :</i><br><b>      1</b> se charger de, entreprendre, <i>abs</i>. IL. <i>7, 93 ;</i> HDT. <i>9, 21, 22 ;</i> PLAT. <i>Eryx. 396</i> e ;<br><b>      2</b> promettre, faire une promesse : τινι, OD. <i>2, 387,</i> à qqn ; τι, HDT. <i>5, 51,</i> promettre qqe ch. ; μεγάλα τινί, HDT. <i>2, 121,</i> faire de grandes promesses à qqn ; <i>avec l’inf. fut</i>. HH. <i>Cer. 443, 461 ;</i> HDT. <i>1, 24 ; 4, 119, etc. ;</i> THC. <i>2, 29 ; avec</i> ἦ μήν <i>et l’inf. fut</i>. THC. <i>8, 81 ; avec l’inf. prés</i>. ANT. <i>123, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass</i>. ὑπεδέχθην, <i>au sens moy</i>. EUR. <i>Her. 757 ; au sens pass</i>. POLL. <i>1, 74 ;</i> SCH.-IL. <i>14, 323 ; ao.2, 3 sg. épq</i>. ὑπέδεκτο, IL. <i>9, 480 ;</i> OD. <i>2, 387 ; 14, 52, etc. ; impér. 2 pl</i>. ὑπόδεχθε, ANTH. <i>8, 33 ; inf</i>. ὑπόδεχθαι, IL. <i>7, 93 ; part</i>. ὑποδέγμενος, OD. <i>13, 310. Conjug. ion</i>. ὑποδέκομαι, HDT. <i>7, 176, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποδεχομαι - ὑποδέχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G5265":"<h1>hupodeo</h1>\n<p>Strong n° 5265 <i>Prononciation [hoop-od-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lier ce qui est en bas, ce qui est « sous lié » (soulier)</li>\n<li>se chausser, se lacer les sandales</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·δέω-ῶ</b>, attacher en dessous, <i>d’où :</i><br><b>      1</b> <i>en gén</i>. attacher sous : ἁμαξίδας ὑπ. τῇσι οὐρῇσι, HDT. <i>3, 113,</i> attacher des chariots sous la queue (de petits moutons à longue queue) ;<br><b>      2</b> <i>particul. en parl. de chaussures :</i> κάμηλον καρϐατίναις, ARSTT. <i>H.A. 2, 1, 27,</i> chausser un chameau d’une espèce de mocassins ;<br><b><i>Moy.</i></b> attacher sous soi : ὑπ. κοθόρνους, HDT. <i>1, 155, etc. ;</i> AR. <i>Eccl. 269,</i> ses cothurnes ; ὑποδεδεμένος ὑποδήματα, PLAT. <i>Gorg. 490</i> e, <i>etc</i>. ayant ses chaussures, étant chaussé ; <i>p. suite,</i> se chausser : ὑποδεδεμένοι τὸν ἀριστερὸν πόδα, THC. <i>3, 22, etc</i>. ayant le pied gauche chaussé ; πόδα σανδάλῳ ὑποδεδεμένος, LUC. <i>H. conscr. 22,</i> ayant le pied chaussé d’une sandale ; <i>abs</i>. ὑποδεδεμένοι, XÉN. <i>An. 4, 5, 14,</i> étant chaussés.<br><span><b><span class=\"arrow\"></span></b> <i>Avec contr. au part. prés. : act</i>. ὑποδῶν, PLAT. <i>Prot. 321</i> a ; <i>pass</i>. ὑποδούμενος, PLAT. <i>Theæt. 193</i> c, <i>etc. ;</i> ὑποδουμένη, AR. <i>Eccl. 36</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποδεω - ὑποδέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G5266":"<h1>hupodema</h1>\n<p>Strong n° 5266 <i>Prononciation [hoop-od'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est lié en bas, une sandale, une semelle tenue aux pieds par des courroies</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπόδημα, ατος (τὸ) :<br>      1</b> semelle fixée sous le pied et attachée par des lanières <i>ou</i> des cordons s’entre-croisant, OD. <i>15, 369 ; 18, 361 ;</i> HDT. <i>1, 195, etc. ;</i> PLAT. <i>1 Alc. 128</i> a, <i>etc. ;</i><br><b>      2</b> ὑπόδημα κοῖλον, STR. <i>734, ou abs</i>. ὑπόδημα, AR. <i>Pl. 983,</i> soulier qui enveloppe tout le pied.<br><span><b>Étym</b>. ὑποδέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποδημα - ὑπόδημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G5267":"<h1>hupodikos</h1>\n<p>Strong n° 5267 <i>Prononciation [hoop-od'-ee-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dans un jugement, quelqu'un qui perd son procès</li>\n<li>le débiteur de quelqu'un, passible de justice\n<ol type=\"a\">\n<li>de celui qui est sujet au châtiment venant de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπό·δικος, ος, ον</b> <span>[ῐ]</span> qui peut être cité en justice, responsable, <i>abs</i>. LYS. <i>117, 3 ;</i> PLAT. <i>Leg. 954</i> a, <i>etc. ; avec le gén. du délit :</i> ὑπ. χερῶν, ESCHL. <i>Eum. 260,</i> soumis à un jugement pour un crime ; <i>p. suite,</i> accusé : φόνου, DÉM. <i>54, 25,</i> de meurtre ; <i>avec le dat. de la pers. envers qui l’on est responsable,</i> PLAT. <i>Leg. 871</i> b ; DÉM. <i>518, 3 ; avec double rég. : gén. du délit, dat. de la pers. lésée,</i> PLAT. <i>Leg. 868</i> d, <i>etc. ; gén. de la peine, dat. de la pers. lésée,</i> PLAT. <i>Leg. 846</i> b.<br><span><b>Étym</b>. ὑ. δίκη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποδικος - ὑπόδικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5268":"<h1>hupozugion</h1>\n<p>Strong n° 5268 <i>Prononciation [hoop-od-zoog'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sous le joug</li>\n<li>une bête de somme, un âne, une ânesse\n<ol type=\"a\">\n<li>l'âne était l'animal commun utilisé par les Orientaux pour voyager ou transporter des charges</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·ζύγιος, ος</b> <i>ou</i> <b>α, ον</b> <span>[ῠγ]</span> mis sous le joug, AR. GR. (EUST. <i>1625, 41</i>) ; τὸ ὑποζύγιον, THGN. <i>126 ;</i> HDT. <i>9, 39 ;</i> XÉN. <i>Lac. 11, 2 ;</i> PLAT. <i>Leg. 873</i> d, <i>etc</i>. bête de somme ; <i>d’ord. au pl</i>. HDT. <i>1, 167 ; 3, 25, etc. ;</i> THC. <i>2, 3, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ία, AR. GR. <i>l. c</i>.<br><span><b>Étym</b>. ὑ. ζυγόν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποζυγιον - ὑποζύγιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5269":"<h1>hupozonnumi</h1>\n<p>Strong n° 5269 <i>Prononciation [hoop-od-zone'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ceindre au dessous\n<ol type=\"a\">\n<li>lier un navire latéralement: c.à.d. avec des cordes, pour le rendre capable de résister à la force des vagues et de la tempête</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·ζώννυμι</b> (<i>pf</i>. ὑπέζωκα, <i>pf. pass</i>. ὑπέζωσμαι) <span>[νῡ]</span> ceindre en dessous, PLUT. <i>Eum. 11 ;</i> ναῦν, POL. <i>27, 3, 3 ;</i> NT. <i>Ap. 27, 17,</i> entourer un navire d’une préceinte (<i>v</i>. ὑπόζωμα) ; τοῖς ποσσίν, ANTH. <i>12, 222,</i> entourer avec les jambes, <i>t. de lutteur ; au pass</i>. PLUT. <i>Num. 13, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> se ceindre de : ξίφος, PLUT. <i>Pomp. 10,</i> d’une épée ; χρυσοῦς, PLUT. <i>Demetr. 49,</i> porter de l’or dans sa ceinture ; <i>au pf</i>. être ceint de : νηδὺν λευκήν, EL. <i>N.A. 13, 17,</i> d’un ventre blanc, avoir le ventre blanc ;<br><b>      2</b> relever autour de ses reins : ὑ. χιτῶνα, LUC. <i>V.H. 1, 13,</i> retrousser sa tunique.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποζωννυμι - ὑποζώννυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5270":"<h1>hupokato</h1>\n<p>Strong n° 5270 <i>Prononciation [hoop-ok-at'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sous, au-dessous, en dessous</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·κάτω</b> <span>[ᾰ]</span> <i>adv. et prép</i>. en dessous, en bas, PLAT. <i>Leg. 844</i> c ; <i>fig</i>. τὸ ὑποκάτω γένος, ARSTT. <i>Top. 6, 5, 6, etc</i>. le genre subordonné ; <i>avec un gén</i>. au-dessous de, au bas de, <i>gén</i>. PLAT. <i>Phæd. 112</i> d, <i>Conv. 222</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποκατω - ὑποκάτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G5271":"<h1>hupokrinomai</h1>\n<p>Strong n° 5271 <i>Prononciation [hoop-ok-rin'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre à son compte les déclarations d'un autre\n<ol type=\"a\">\n<li>répliquer, répondre</li>\n</ol>\n</li>\n<li>donner une réplique (parler) sur une scène\n<ol type=\"a\">\n<li>personnifier, représenter un personnage, jouer un rôle</li>\n</ol>\n</li>\n<li>simuler, feindre, prétendre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·κρίνω</b> <span>[ῐ]</span> <span>(<i>f</i>. ὑποκρινῶ, <i>ao</i>. ὑπέκρινα, <i>etc</i>.)</span> séparer sommairement, distinguer un peu, SUID. <i>t. 2, 2, p. 1367, 14, Bernh. ;</i> GRAMM. <i>p. 449, 25 Bekker, Anecdota græca, etc. ; particul. t. de droit,</i> diriger une enquête préalable sur, <i>acc</i>. EUST. <i>687, 20, etc. ;</i><br><b><i>Moy</i>. ὑποκρίνομαι</b> <span>[ῑ]</span> <span>(<i>impf</i>. ὑπεκρινόμην, <i>f</i>. ὑποκρινοῦμαι <span>[ῐ]</span>, <i>ao</i>. ὑπεκρινάμην <span>[ῑ]</span> <i>et</i> ὑπεκρίθην <span>[ῑ]</span>, <i>pf</i>. ὑποκέκριμαι <span>[ῐ]</span>)</span><br><b>   I</b> répondre : IL. <i>12, 228 ;</i> τινι, IL. <i>7, 407 ;</i> OD. <i>2, 111 ; 15, 170 ;</i> HDT. <i>1, 2, etc</i>. à qqn ; τι, HDT. <i>3, 119 ; etc</i>. qqe ch. ; <i>en parl. d’un oracle :</i> τί τινι, HDT. <i>1, 78, 91 ;</i> THCR. <i>Idyl. 24, 66 etc. ; p. ext</i>. expliquer, interpréter (en réponse à une question) : ὄνειρον, OD. <i>19, 535, 555,</i> interpréter un songe ; <i>cf</i>. AR. <i>Vesp. 53 ;</i><br><b>   II</b> <i>particul. en prose, surt. chez les Att</i>. donner la réplique dams un dialogue de théâtre, <i>d’où</i> jouer un rôle : Ἀντιγόνην, DÉM. <i>418, 9,</i> jouer le rôle d’Antigone ; ἥρωα, LUC. <i>Nigr. 11,</i> jouer un rôle de héros ; τὰ πρῶτα, LUC. <i>Tyr. 22,</i> jouer les premiers rôles ; τραγῳδίαν, DS. <i>13, 97 ;</i> PLUT. <i>Dem. 28 ; ou</i> κωμῳδίαν, ARSTT. <i>Rhet. 3, 1 ;</i> LUC. <i>M. cond. 30, etc</i>. jouer la tragédie <i>ou</i> la comédie ; προσωπεῖα, LUC. <i>Salt. 66,</i> jouer des rôles de pantomime ; <i>abs</i>. jouer la comédie, être comédien <i>ou</i> acteur, POL. <i>31, 4, 8 ;</i> LUC. <i>Pseud. 18 ; p. ext</i>. débiter <i>ou</i> jouer comme un acteur, <i>d’où :</i><br><b>      1</b> réciter, déclamer, <i>en gén. :</i> λόγους ἀλλότριους, LUC. <i>Pseud. 25,</i> déclamer les discours d’autrui ; <i>particul. en parlant de rhapsodes,</i> ATH. <i>620</i> d ; <i>ou d’orateurs,</i> DÉM. <i>230, 7 ;</i> PLUT. <i>Dem. 11 ;</i><br><b>      2</b> contrefaire, feindre : μανίαν, LUC. <i>Salt. 83,</i> contrefaire la folie ; <i>en parl. de singes,</i> contrefaire, singer, <i>acc</i>. PHILSTR. <i>V. Ap. 3, 4, d’où</i> feindre, <i>en gén., avec l’inf</i>. DÉM. <i>321, 18 ; 878, 3,</i> feindre de, <i>etc. ;</i> ὑποκριθεὶς ὡς πεπεισμένος, POL. <i>5, 25, 7,</i> ayant feint d’être persuadé.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. ion</i>. ὑποκρινέομαι, HDT. <i>1, 164</i>.<br><span><b>Étym</b>. ὑ. κρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποκρινομαι - ὑποκρίνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5272":"<h1>hupokrisis</h1>\n<p>Strong n° 5272 <i>Prononciation [hoop-ok'-ree-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui répond</li>\n<li>une réplique</li>\n<li>le rôle d'un joueur de théâtre</li>\n<li>dissimulation, hypocrisie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπόκρισις, εως (ἡ)</b> <span>[ῐσ]</span><br><b>   I</b> réponse, HDT. <i>1, 116 ; 9, 9 ;</i> A. RH. <i>4, 1755 ; particul</i>. réponse d’un oracle, HDT. <i>1, 90 ;</i><br><b>   II</b> action de jouer un rôle, une pièce, LUC. <i>Pisc. 32 ;</i> une pantomime, ARSTT. <i>Nic. 3, 10, 4 ; adv</i>. ὑπόκρισιν, PD. <i>fr. 259,</i> selon le jeu de, <i>càd</i>. à la façon de, <i>etc</i>. LUC. <i>Salt. 65 ; p. ext. :</i><br><b>      1</b> débit théâtral, déclamation, ARSTT. <i>Nic. 3, 1, 3 ; 3, 12, 2, etc. ;</i> POL. <i>10, 47, 10 ;</i><br><b>      2</b> feinte, faux-semblant, PHOCYL. <i>2 ;</i> POL. <i>35, 2, 13 ;</i> LUC. <i>Am. 3 ;</i> SPT. <i>2Macc. 6, 25</i>.<br><span><b>Étym</b>. ὑποκρίνομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποκρισις - ὑπόκρισις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5273":"<h1>hupokrites</h1>\n<p>Strong n° 5273 <i>Prononciation [hoop-ok-ree-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>quelqu'un qui répond, qui réplique, un interprète</li>\n<li>un acteur, un joueur de théâtre</li>\n<li>celui qui dissimule, un prétendant, un hypocrite</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑποκριτής, οῦ (ὁ)</b> <span>[ῐ]</span><br><b>   I</b> celui qui donne une réponse, <i>particul. :</i><br><b>      1</b> interprète d’un songe, d’une vision, PLAT. <i>Tim. 72</i> b ; LUC. <i>Somn. 17, etc. ;</i><br><b>      2</b> devin, prophète, NT. ;<br><b>   II</b> acteur, comédien, AR. <i>Vesp. 1279 ;</i> PLAT. <i>Rsp. 373</i> b, <i>Charm. 162</i> d, <i>etc. ; p. ext. :</i><br><b>      1</b> tout homme qui récite <i>ou</i> déclame, <i>particul</i>. rhapsode, DS. <i>14, 109 ; 15, 7 ;</i><br><b>      2</b> fourbe, hypocrite, SPT. <i>Job 34, 30 ; 36, 13</i>.<br><span><b>Étym</b>. ὑποκρίνομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποκριτης - ὑποκριτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G5274":"<h1>hupolambano</h1>\n<p>Strong n° 5274 <i>Prononciation [hoop-ol-am-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre dans le but d'élever, de porter plus haut\n<ol type=\"a\">\n<li>prendre et emporter</li>\n</ol>\n</li>\n<li>recevoir avec hospitalité, accueillir</li>\n<li>prendre\n<ol type=\"a\">\n<li>suivre un discours, dans le but de répliquer ou controverser suite à ce qu'a dit un autre</li>\n</ol>\n</li>\n<li>prendre en esprit\n<ol type=\"a\">\n<li>supposer, penser</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·λαμϐάνω</b> <span>(<i>f</i>. ὑπολήψομαι, <i>ao.2</i> ὑπέλαϐον, <i>etc</i>.)</span><br><b>   I</b> prendre par-dessous :<br><b>      1</b> porter sur son dos, <i>acc</i>. HDT. <i>1, 24 ;</i> PLAT. <i>Rsp. 453</i> d ; <i>en parl. d’une vague,</i> soulever, <i>acc</i>. CLÉARQ. (ATH. <i>332</i> e) ; <i>d’un nuage,</i> enlever, <i>acc</i>. NT. <i>Ap. 1, 9 ;</i><br><b>      2</b> prendre sous le bras, soutenir (un homme ivre) <i>acc</i>. PLAT. <i>Conv. 212</i> d ;<br><b>      3</b> prendre par en bas, <i>càd</i>. embrasser les genoux pour supplier, <i>acc</i>. DH. <i>7, 54 ;</i><br><b>      4</b> prendre pour mettre sous, fourrer, cacher : τι ὑπὸ τὸ ἱμάτιον, PLUT. <i>M. 234</i> b, qqe ch. sous son vêtement ;<br><b>   II</b> accueillir :<br><b>      1</b> accueillir amicalement, traiter en hôte, recueillir : φεύγοντας, XÉN. <i>An. 1, 1, 7,</i> des fuyards ;<br><b>      2</b> soutenir, protéger : τοὺς ἐνδεεῖς, STR. <i>653, etc</i>. les indigents ; <i>d’où</i> donner ses soins à, soigner (un malade) HPC. <i>452, 3 ;</i><br><b>      3</b> faire bon accueil à, approuver : λόγον, HDT. <i>1, 212 ; 3, 146,</i> une parole, une proposition, une déclaration ;<br><b>   III</b> prendre <i>ou</i> recevoir ensuite : δυσχωρία ὑπελάμϐανεν αὐτούς, XÉN. <i>Hell. 3, 5, 20,</i> ils arrivaient dans une région difficile ; <i>d’où sans rég</i>. succéder, suivre, survenir : ἡ ναυμαχίη ὑπολαϐοῦσα, HDT. <i>6, 27,</i> le combat naval qui suivit ; <i>particul. avec ou sans</i> λόγον : ὑ. τὸν λόγον, ATT. prendre la parole après qqn ; <i>abs. :</i> ὁ δὲ ὑπολαϐὼν ἔφη, HDT. <i>7, 101 ;</i> THC. <i>3, 113,</i> et ayant pris la parole, il dit ; <i>qqf</i>. prendre la parole en interrompant : ἔτι λέγοντος αὐτοῦ ὑπολαϐὼν εἶπε, XÉN. <i>Cyr. 5, 5, 35,</i> comme il parlait encore, Cyrus prit la parole et dit ; <i>p. suite,</i> répondre, THC. <i>5, 85 ;</i> τι, DÉM. <i>596, 14 ; 638, 17, etc</i>. qqe ch. ; <i>avec</i> ὅτι, PLAT. <i>Rsp. 598</i> d ; DÉM. <i>600, 23 ;</i> ὅτι <i>ou</i> ὡς, XÉN. <i>Ath. 3, 12 ;</i> DÉM. <i>600, 20,</i> répondre que ; <i>avec une prop. inf</i>. THC. <i>5, 49, m. sign. ;</i> ὑπ. τι πρός τινα, DÉM. <i>501, 25,</i> objecter qqe ch. à qqn ; τι πρός τι, DÉM. <i>594, 21,</i> objecter une chose à une autre ;<br><b>   IV</b> prendre à l’improviste, surprendre : ναῦς πεπλανημένας, THC. <i>8, 105,</i> des vaisseaux dispersés ; αὐτὸν ὑπέλαϐε μανίη νοῦσος, HDT. <i>6, 75,</i> il fut atteint d’une folie subite ;<br><b>   V</b> intercepter, arrêter :<br><b>      1</b> <i>t. d’équit. :</i> ἵππον, XÉN. <i>Eq. 7, 15 ; 9, 5,</i> retenir <i>ou</i> modérer un cheval ;<br><b>      2</b> <i>t. de méd</i>. enrayer un mal, l’arrêter à son origine, HPC. <i>21, 22 ;</i><br><b>   VI</b> prendre en dessous, <i>càd. :</i><br><b>      1</b> prendre secrètement : τὰ ὅπλα, THC. <i>6, 58,</i> les armes ;<br><b>      2</b> s’emparer par des moyens détournés de, attirer à soi par des voies détournées, détacher d’un parti : <i>acc</i>. THC. <i>1, 68 ;</i> μισθῷ μείζονι τοὺς ξένους, THC. <i>1, 143,</i> débaucher les troupes mercenaires par l’offre d’une plus forte solde ;<br><b>   VII</b> <i>en parl. de l’intelligence :</i><br><b>      1</b> concevoir : τι τῇ διανοίᾳ, ESCHN. <i>Tim. § 49 Baiter-Sauppe,</i> qqe ch. dans son esprit, <i>d’où abs</i>. concevoir, comprendre : λόγον, EUR. <i>I.A. 523 ;</i> τι, PLAT. <i>Euthyd. 295</i> b, un discours, qqe ch. ; ὑπ. ὀρθῶς, PLAT. <i>Gorg. 458</i> e, comprendre bien ; ὑπ. κάλλιστα, PLAT. <i>Theæt. 159</i> b, comprendre tout à fait bien ; τὸν Ἔρωτα ἕν τι, <i>etc</i>. PLAT. <i>Phædr. 263</i> d, concevoir l’amour comme une chose, <i>etc. ;</i> τι ὡς, <i>etc</i>. PLAT. <i>Parm. 134</i> c, comprendre qqe ch. comme, <i>etc. ; abs</i>. comprendre là-dessous, <i>càd</i>. vouloir dire par là, ARSTT. <i>Rhet. 3, 11 ;</i><br><b>      2</b> penser, croire, être d’avis : οὕτω περὶ αὐτῶν ὑπειλήφαμεν, ISOCR. <i>32</i> b, voilà ce que nous pensons d’eux ; τούτους ὑπ. φρονίμους, PLAT. <i>2 Alc. 140</i> e, tenir ceux-là pour sensés ; <i>avec</i> ὅτι, PLAT. <i>Phæd. 86</i> b ; <i>avec un inf</i>. XÉN. <i>Cyr. 5, 4, 49 ; avec une prop. inf</i>. PLAT. <i>Phæd. 86</i> b ; <i>au pass</i>. ὑπολαμϐάνομαι, on pense de moi que, <i>etc.,</i> je passe pour, <i>etc</i>. ISOCR. <i>233</i> d ; DÉM. <i>178, 8 ; 623, 5 ;</i> ARSTT. <i>Rhet. 1, 9, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπολαμβανω - ὑπολαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G5275":"<h1>hupoleipo</h1>\n<p>Strong n° 5275 <i>Prononciation [hoop-ol-i'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>laisser derrière</li>\n<li>être laissé derrière, laisser en reste\n<ol type=\"a\">\n<li>d'un survivant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·λείπω</b> <span>(<i>f</i>. ὑπολείψω, <i>ao.2</i> ὑπέλιπον, <i>etc</i>.)</span><br><b>   I <i>tr. :</i><br>      1</b> laisser dessous <i>ou</i> au fond, laisser de reste : ἃ ὑπέλειπον ἔδοντες, OD. <i>16, 50,</i> ce qu’ils avaient laissé (la veille) de nourriture ; <i>au pass</i>. être laissé, rester, IL. <i>23, 615, etc. ;</i> οὐδὲν ὑπολείπεται ἄλλ' ἢ ποιεῖν, PLAT. <i>Phædr. 231</i> b, il ne reste qu’à faire ;<br><b>      2</b> laisser derrière soi, <i>avec idée de lieu :</i> τινὰ πολέμιον, THC. <i>6, 17,</i> qqe ennemi ; <i>au pass</i>. être laissé en arrière, rester en arrière dans une course, AR. <i>Ran. 1092 ; en parl. de traînards,</i> XÉN. <i>An. 1, 2, 25 ;</i> PLAT. <i>Conv. 174</i> d, <i>etc. ;</i> τοῦ στόλου, HDT. <i>1, 165,</i> rester en arrière de l’expédition, <i>càd</i>. ne pas y prendre part ; <i>en gén</i>. être placé en arrière : τοῦ στόματος, XÉN. <i>An. 5, 4, 22,</i> du front de l’armée ; <i>avec idée de temps :</i> ὁπόταν νὺξ ὑπολειφθῇ, SOPH. <i>El. 91,</i> lorsque la nuit s’est écoulée (<i>litt</i>. a été laissée en arrière) ; <i>abs</i>. rester en arrière, rester seul : ἐν μεγάρῳ, OD. <i>7, 230,</i> dans son palais ; <i>fig</i>. ἀρωγῆς ὑπολειφθῆναι, ESCHL. <i>Ag. 73,</i> être privé d’un secours (<i>litt</i>. rester en arrière d’un secours) ; <i>fig</i>. être en arrière de, être inférieur à : τινός τινι, ARSTT. <i>Pol. 7, 16, 3,</i> à qqn en qqe ch. ; <i>avec idée de temps :</i> ὑπολείπειν πόλεμον τοῖς παισί, THC. <i>1, 81,</i> laisser <i>ou</i> léguer une guerre à ses enfants ;<br><b>   II <i>intr. :</i></b> venir à manquer, tomber, <i>en parl. des cheveux,</i> ARSTT. <i>G.A. 2, 6, 48 ;</i> faire défaut : ὑπολείψει ἡμᾶς ἡ μισθοφορά, LYS. <i>177 fin</i>, la solde nous manquera ; ὅταν ὑπολίπῃ τὸ μέλι, ARSTT. <i>H.A. 9, 40, 43,</i> lorsque le miel vient à manquer ; <i>cf</i>. ARSTT. <i>Pol. 7, 11, 3, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> laisser de reste, réserver pour soi : ὑπ. περὶ ἑωυτόν, HDT. <i>2, 25,</i> garder (une certaine quantité d’eau) ; ὑπ. μαρτυρίαν εἰς τὸν ὕστερον λόγον, DÉM. <i>836, 6,</i> se réserver un témoignage pour le discours suivant ; ὑπ. ἀναφοράν, DÉM. <i>301, 23,</i> se réserver un moyen d’échapper ;<br><b>      2</b> laisser derrière soi : μηδεμίην τῶν νεῶν, HDT. <i>6, 7,</i> ne laisser aucun navire en arrière ; <i>cf</i>. HDT. <i>4, 121 ; 8, 24, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπολειπω - ὑπολείπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G5276":"<h1>hupolenion</h1>\n<p>Strong n° 5276 <i>Prononciation [hoop-ol-ay'-nee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un réceptacle placé sous une presse (et en Orient généralement mis sous le sol) pour recevoir le jus extrait des raisins, une fosse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·λήνιον, ου (τὸ)</b> cuve sous le pressoir, SPT. <i>Joel 3, 13 ; Esaï. 16, 10 ;</i> NT. <i>Marc. 12, 1</i>.<br><span><b>Étym</b>. ὑ. ληνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποληνιον - ὑπολήνιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G5277":"<h1>hupolimpano</h1>\n<p>Strong n° 5277 <i>Prononciation [hoop-ol-im-pan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>quitter, laisser derrière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·λιμπάνω</b> (<i>seul. prés. et impf</i>.) :<br><b>      1</b> laisser derrière, THÉM. <i>139</i> d ; NT. <i>1Petr. 2, 21 ;</i><br><b>      2 <i>intr.</i></b> faire défaut, manquer, DH. <i>1, 23</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπολιμπανω - ὑπολιμπάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5278":"<h1>hupomeno</h1>\n<p>Strong n° 5278 <i>Prononciation [hoop-om-en'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rester\n<ol type=\"a\">\n<li>s'attarder derrière</li>\n</ol>\n</li>\n<li>rester c.à.d. demeurer, ne pas s'éloigner ou s'enfuir\n<ol type=\"a\">\n<li>conserver : dans les épreuves et dans les peines, maintenir sa foi en Christ</li>\n<li>endurer, supporter bravement et calmement les mauvais traitements</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·μένω</b> <span>(<i>f</i>. -μενῶ, <i>ao</i>. ὑπέμεινα, <i>etc</i>.)</span><br><b>   I <i>intr. :</i><br>      1</b> rester en arrière, OD. <i>10, 232, 258 ;</i> XÉN. <i>Cyr. 2, 4, 29, etc. ;</i> οἱ ὑπομένοντες, THC. <i>5, 14,</i> ceux qui étaient restés dans l’intérieur du pays ; οἱ ὑπομείναντες, XÉN. <i>Conv. 9, 7,</i> ceux qui étaient restés après le départ des autres ;<br><b>      2</b> rester là, demeurer, séjourner : ἐν τῇ πόλει, HDT. <i>7, 109,</i> dans la ville ; ἐντὸς τείχους, DH. <i>11, 9,</i> à l’intérieur des murs ; <i>en parl. de choses,</i> ARSTT. <i>Categ. 6, p. 5 a, 27 ;</i><br><b>      3</b> vivre, HDT. <i>4, 149 ;</i><br><b>   II <i>tr. :</i><br>      1</b> attendre : τινά, XÉN. <i>An. 4, 1, 31,</i> qqn ; <i>avec l’inf</i>. οὐδ' ὑπέμεινε γνώμεναι, OD. <i>1, 410,</i> il n’attendit pas qu’on apprît à le connaître ; <i>avec un suj. de chose et le rég. à l’acc</i>. attendre, être réservé à, POL. <i>1, 81, 3 ;</i> ὅσα ἡμᾶς ἐν ὑστέρῳ χρόνῳ ὑπέμενεν, PLAT. <i>Phædr. 250</i> c, tout ce qui nous était réservé dans la suite ;<br><b>      2</b> attendre de pied ferme, soutenir le choc de, <i>acc</i>. IL. <i>16, 814 ; 17, 25, 174 ;</i> HDT. <i>3, 9 ; 7, 120, etc. ;</i> PLAT. <i>Theæt. 241</i> a, <i>etc. ; abs</i>. IL. <i>5, 498 ;</i> HDT. <i>4, 3 ; 6, 96 ;</i> PLAT. <i>Theæt. 177</i> b, <i>etc. ; joint à</i> καρτερεῖν, PLAT. <i>Lach. 193</i> b ; <i>p. opp. à</i> φεύγειν, PLAT. <i>Tim. 49</i> e ; <i>en parl. d’animaux,</i> laisser s’approcher de soi, n’être pas farouche <i>ou</i> craintif, EL. <i>N.A. 16, 18, etc. ;</i><br><b>      3</b> supporter, endurer, <i>acc</i>. HDT. <i>6, 12 ;</i> THC. <i>1, 8 ;</i> PLAT. <i>Leg. 770</i> c, <i>etc. ;</i> ISOCR. <i>130</i> d ; DÉM. <i>515, 17, etc. ;</i> τὰς δωρεὰς οὐχ ὑπέμειναν, ISOCR. <i>60</i> b, ils n’acceptèrent pas les présents, ils les dédaignèrent ; <i>avec l’inf</i>. XÉN. <i>Mem. 2, 2, 5 ; 2, 7, 11 ;</i> PLAT. <i>Leg. 869</i> c, <i>etc. ;</i> οὐχ ὑπομένει ὠφελούμενος, PLAT. <i>Gorg. 505</i> c, il ne consent pas à être aidé ; <i>avec un part</i>. se résigner à ce que, PHYLARQ. (ATH. <i>606</i> f) ; <i>avec un gén</i>. φιλοῦντος ὑπομεῖναι, EL. <i>V.H. 12, 1,</i> consentir à ce que qqn embrasse ;<br><b>      4</b> prendre sur soi, se charger de, entreprendre, <i>avec un part</i>. SOPH. <i>O.R. 1324 ;</i> XÉN. <i>Cyr. 4, 5, 22 ;</i><br><b>      5</b> avoir la hardiesse de, oser, <i>avec un part. :</i> εἰ ὑπομενέουσι χεῖρας ἐμοὶ ἀνταειρόμενοι, HDT. <i>7, 101,</i> s’ils osent lever les mains contre moi, <i>càd</i>. me résister ; <i>cf</i>. HDT. <i>7, 209, etc. ;</i><br><b>      6</b> en rester à, persister dans, <i>dat</i>. APP. <i>Civ. 5, 54</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπομενω - ὑπομένω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 16 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (4)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5279":"<h1>hupomimnesko</h1>\n<p>Strong n° 5279 <i>Prononciation [hoop-om-im-nace'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rappeler à quelqu'un, remettre en mémoire, rappeler à l'esprit d'un autre</li>\n<li>réprimander pour que quelqu'un se souvienne</li>\n<li>se rappeler, se souvenir de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·μιμνῄσκω</b> <span>(<i>f</i>. ὑπομνήσω, <i>ao</i>. ὑπέμνησα, <i>etc</i>.)</span><br><b>   I</b> <i>act. :</i><br><b>      1</b> faire ressouvenir, avertir en rappelant : τινά τινος, OD. <i>1, 321 ; 15, 3 ;</i> THC. <i>6, 19 ; ou</i> τινὰ περί τινος, PLAT. <i>Phædr. 275</i> d ; <i>ou</i> τινά τι, THC. <i>7, 64 ;</i> XÉN. <i>Cyr. 3, 3, 37, etc</i>. faire ressouvenir qqn de qqe ch., rappeler qqe ch. à qqn ; <i>avec un relat. :</i> τινά τί βούλεται, PLAT. <i>Phil. 31</i> c, rappeler à qqn ce qu’il veut ; τινά <i>avec</i> ὡς <i>et un part</i>. ISOCR. <i>6</i> d, rappeler à qqn que, <i>etc. ;</i> τινὰ ὅτι, PLAT. <i>Phæd. 88</i> d, rappeler à qqn que, <i>etc. ; avec un adv</i>. καλῶς ὑπ. PLAT. <i>Phædr. 266</i> d ; ὀρθῶς ὑπ. PLAT. <i>Theæt. 187</i> e, rappeler heureusement, avec raison, <i>etc. ;</i><br><b>      2</b> mettre dans l’esprit, avertir : τι, HDT. <i>7, 171 ; 9, 6 ;</i> SOPH. <i>Ph. 1170,</i> de qqe ch. ; τινί τι, ESCHL. <i>Pers. 990,</i> suggérer qqe ch. à qqn ; ὑπ. ὅτι, PLAT. <i>Rsp. 452</i> c, suggérer la pensée que, <i>etc. ;</i><br><b>      3</b> faire mention de, <i>gén</i>. THC. <i>7, 69 ;</i> ESCHN. <i>75, 42 ;</i> THCR. <i>Idyl. 21, 50 ;</i><br><b>   II</b> <i>moy. :</i><br><b>      1</b> se souvenir : περί τινος, ESCHL. <i>Pers. 329,</i> de qqn ;<br><b>      2</b> se ressouvenir : τι, XÉN. <i>Cyr. 6, 1, 24 ;</i> PLAT. <i>Phil. 47</i> e, <i>Lach. 188</i> a ; τινος, LUC. <i>Cat. 4,</i> de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. dor</i>. ὑπομιμνᾴσκω, THCR. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπομιμνησκω - ὑπομιμνῄσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>2 Pierre (1)</li>\n<li>3 Jean (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G5280":"<h1>hupomnesis</h1>\n<p>Strong n° 5280 <i>Prononciation [hoop-om'-nay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un souvenir</li>\n<li>un rappel, une remise en mémoire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπόμνησις, εως (ἡ) :<br>      1</b> action de faire ressouvenir, PLAT. <i>Phædr. 275</i> a, <i>etc. ;</i> ὑπόμνησίν τινος ἔχειν, XÉN. <i>Cyr. 3, 3, 38,</i> avoir le souvenir de qqe ch. ;<br><b>      2</b> mention, récit, EUR. <i>Or. 1032 ;</i> PLAT. <i>Leg. 732</i> d ; ὑπόμνησίν τινος ποιεῖσθαι, THC. <i>2, 88 ; 3, 54, etc</i>. faire mention de qqe ch.<br><span><b>Étym</b>. ὑπομιμνῄσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπομησις - ὑπόμνησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> dénote une chose qui revient en mémoire sans l'assistance de personne,  un souvenir rappelé par quelqu'un, cependant dans le Grec classique les deux mots sont facilement interchangeables</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G5281":"<h1>hupomone</h1>\n<p>Strong n° 5281 <i>Prononciation [hoop-om-on-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>constance, persévérance, endurance\n<ol type=\"a\">\n<li>dans le N.T., le trait caractéristique d'un homme qui ne dévie pas de son but délibéré et de sa loyauté à la foi et la piété malgré les plus grandes épreuves et souffrances</li>\n<li>patiemment, et constamment</li>\n</ol>\n</li>\n<li>un homme patient, constant dans son attente</li>\n<li>une patience qui endure, qui est ferme, persévérante</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπομονή, ῆς (ἡ) :<br>   I</b> <i>intr. :</i><br><b>      1</b> action de rester en arrière, de rester là, ARSTT. <i>Rhet. 3, 9, 7 ;</i> DH. <i>1, 44 ;</i><br><b>      2</b> pouvoir <i>ou</i> force de résistance, ARSTT. <i>Rhet. 2, 6, 13 ; en parl. d’une plante,</i> durée, persistance, TH. <i>C.P. 5, 16, 3 ; au mor</i>. persévérance, PLUT. <i>Crass. 3 ;</i><br><b>   II</b> <i>tr. :</i><br><b>      1</b> <i>au propre,</i> pouvoir <i>ou</i> force de supporter, de résister à (des coups) <i>en parl. d’une épée,</i> POL. <i>15, 15, 8 ; au mor</i>. action de supporter sans fléchir <i>ou</i> sans se laisser entamer, <i>gén</i>. PLAT. <i>Def. 412</i> c ; POL. <i>4, 51, 1 ;</i> PLUT. <i>Pel. 1 ; p. suite,</i> résignation, patience, ARSTT. <i>An. post. 2, 13, 18 ;</i><br><b>      2</b> action d’oser : αἰσχρῶν λόγων καὶ πράξεων, TH. <i>Char. 6,</i> audace pour dire et faire des choses honteuses.<br><span><b>Étym</b>. ὑπομένω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπομονη - ὑπομονή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> est le tempérament de celui qui ne succombe pas facilement sous la souffrance,\n<br><br> est l'auto-restriction de celui qui n'use pas hâtivement de représailles envers une faute.\n<br><br> est le contraire de la lâcheté, de la couardise, du découragement,  est opposé de courroux et vengeance.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 31 versets de 13 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Romains (6)</li>\n<li>2 Corinthiens (3)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (3)</li>\n<li>2 Pierre (2)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G5282":"<h1>huponoeo</h1>\n<p>Strong n° 5282 <i>Prononciation [hoop-on-o-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>supposer, soupçonner, présumer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·νοέω-οῶ</b>, se mettre dans l’esprit, <i>d’où :</i> conjecturer, supposer : τι, HDT. <i>9, 88 ;</i> THC. <i>7, 73 ;</i> PLAT. <i>Leg. 679</i> c ; EUR. <i>I.A. 1132 ;</i> AR. <i>Lys. 38,</i> qqe ch. ; <i>avec une prop. inf</i>. HDT. <i>9, 99 ;</i> ARSTT. <i>fr. 12 ; en mauv. part,</i> soupçonner, suspecter : ὑπ. τινα ὡς <i>avec un part</i>. PLUT. <i>Dem. 20,</i> soupçonner qqn de, <i>etc. ;</i> ὑπ. τινος ὡς <i>avec un mode pers</i>. THC. <i>1, 68,</i> avoir de qqn le soupçon que ; ὑπ. περί τινος, AND. <i>28, 4,</i> soupçonner qqe ch., avoir un soupçon sur qqe ch. ; ὑπ. τι εἴς τινα, AR. <i>Pl. 361,</i> avoir qqe soupçon à l’égard de qqn ; ὑπ. ὡς, XÉN. <i>Hell. 4, 8, 35 ; ou</i> ὅπως, XÉN. <i>Cyr. 3, 3, 20,</i> soupçonner que ; <i>abs</i>. AR. <i>Lys. 38 ;</i> PLAT. <i>Gorg. 454</i> c, <i>etc. ; p. opp. à</i> οἶδα, MÉN. (<i>Com. fr. 4, 145</i>.)\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπονοεω - ὑπονοέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G5283":"<h1>huponoia</h1>\n<p>Strong n° 5283 <i>Prononciation [hoop-on'-oy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un soupçon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπόνοια, ας (ἡ) :<br>      1</b> supposition, conjecture, EUR. <i>Ph. 1133 ;</i> AR. <i>Pax 993 ;</i> PLUT. <i>Sol. 28 ; au plur</i>. THC. <i>5, 87, etc. ; particul</i>. fiction (<i>p. opp. à</i> ἀλήθεια) THC. <i>2, 4 ; en mauv. part,</i> soupçon, suspicion, DÉM. <i>1178, 2 ;</i> POL. <i>5, 15, 1 ;</i> DH. <i>1, 81 ;</i><br><b>      2</b> pensée, sens, signification, XÉN. <i>Conv. 3, 6 ; particul</i>. signification symbolique <i>ou</i> allégorique, EUR. <i>Ph. 1140 ;</i> PLAT. <i>Rsp. 378</i> d ; PLUT. <i>M. 19</i> e ; καθ' ὑπόνοιαν, POL. <i>28, 4, 5 ;</i> DH. <i>Rhet. 9, 1 ;</i> δι' ὑπονοιῶν, ALCIPHR. <i>2, 4,</i> allusion par insinuation, à mots couverts.<br><span><b>Étym</b>. ὑπονοέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπονοια - ὑπόνοια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5284":"<h1>hupopleo</h1>\n<p>Strong n° 5284 <i>Prononciation [hoop-op-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>naviguer au-dessous, longer une côte</li>\n<li>être sous le vent de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·πλέω :<br>      1</b> naviguer sous, <i>dat</i>. ANTH. <i>9, 296 ; gén</i>. PHILSTR. <i>836 ;</i><br><b>      2</b> naviguer de côté, obliquement, NT. <i>Ap. 27, 4 ;</i><br><b>      3</b> naviguer secrètement, DC. <i>49, 43</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποπλεω - ὑποπλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G5285":"<h1>hupopneo</h1>\n<p>Strong n° 5285 <i>Prononciation [hoop-op-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>souffler en dessous</li>\n<li>souffler doucement, légèrement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·πνέω :<br>      1</b> souffler <i>ou</i> respirer du fond de, respirer, ARSTT. <i>Probl. 8, 6 ;</i><br><b>      2</b> souffler agréablement, NT. <i>Ap. 27, 13</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποπνεω - ὑποπνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5286":"<h1>hupopodion</h1>\n<p>Strong n° 5286 <i>Prononciation [hoop-op-od'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un marchepied, un escabeau\n<ol type=\"a\">\n<li>faire de quelqu'un un marchepied pour son pied, c.à.d. l'assujettir, le soumettre à son pouvoir</li>\n<li>métaph. prise de la pratique des conquérants qui plaçaient le pied sur le cou de leurs ennemis vaincus</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·πόδιον, ου (τὸ)</b> petit escabeau, marchepied, CHARÈS (ATH. <i>514</i> f) ; LUC. <i>H. conscr. 27 ;</i> SPT. <i>Ps. 98, 5</i>.<br><span><b>Étym</b>. ὑ. πούς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποποδιον - ὑποπόδιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G5287":"<h1>hupostasis</h1>\n<p>Strong n° 5287 <i>Prononciation [hoop-os'-tas-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est fixé ou placé au dessous\n<ol type=\"a\">\n<li>chose posée au-dessous, sous-structure, fondation, fondement</li>\n</ol>\n</li>\n<li>ce qui a un fondement, qui est ferme\n<ol type=\"a\">\n<li>ce qui a une existence actuelle\n<ol>\n<li>une substance, un être réel</li>\n</ol>\n</li>\n<li>la qualité substantielle, la nature, d'une personne ou chose</li>\n<li>la constance de l'esprit, fermeté, courage, résolution\n<ol>\n<li>confiance, ferme assurance</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπόστασις, εως (ἡ) :<br>A</b> action de se placer dessous, <i>d’où :</i><br><b>      1</b> action de supporter, <i>p. suite</i> support, ARSTT. <i>P.A. 2, 16, 7 ;</i><br><b>      2</b> action de se mettre en embuscade, SOPH. <i>fr. 644 ;</i><br><b>B</b> ce que l’on place dessous, ce qui est au fond :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> base, fondement, HPC. <i>Mochl. 856 ; particul</i>. fondement d’un édifice, DS. <i>1, 66 ; 13, 82 ;</i><br><b>      2</b> dépôt, sédiment, <i>en gén</i>. HPC. <i>686, 38 ;</i> ARSTT. <i>H.A. 5, 19, 14, etc. ; particul</i>. dépôt de l’urine, HPC. <i>Coac. 140, 180, etc. ;</i> ARSTT. <i>Meteor. 2, 3, 20, etc. ; en parl. de résidus secs,</i> excrément, selle, ARSTT. <i>P.A. 2, 2, 3, etc. ;</i> amas d’humeurs, abcès, HPC. <i>Art. 806 ;</i><br><b>      3</b> matière épaissie <i>ou</i> coagulée, gelée, MÉN. (ATH. <i>132</i> e) ; POLL. <i>6, 60 ;</i><br><b>      4</b> amidon, DIEUCH. (ORIB. <i>p. 46 Matthäi</i>) ;<br><b>      5</b> eau stagnante, mare, bourbier, ARSTT. <i>Meteor. 2, 8 ;</i><br><b>      6</b> vapeur condensée qui forme un nuage, DS. <i>1, 38 ;</i><br><b>      7</b> <i>abs</i>. substance, matière, TH. <i>C.P. 5, 16, 4 ; 6, 7, 4 ;</i><br><b>      8</b> <i>postér</i>. lieu sur lequel s’établit une armée, camp, SPT. <i>1Reg. 13, 23 ; 14, 4 ;</i><br><b>   II</b> <i>au sens mor</i>. ce qui est au fond de l’âme, fermeté, sang-froid, confiance, courage, POL. <i>4, 50, 10 ;</i> DS. <i>1, 6 ;</i> NT. <i>Hebr. 3, 14 ; 2Cor. 11, 17, etc. ;</i><br><b>   III</b> <i>en parl. de l’intelligence, de la pensée, etc. :</i><br><b>      1</b> fondement <i>ou</i> sujet d’un ouvrage, d’un discours, <i>etc</i>. POL. <i>4, 2, 1, etc. ;</i> DS. <i>1, 3, etc. ; d’où particul</i>. point de départ, commencement, DS. <i>1, 66 ; en gén</i>. origine (d’un peuple) JOS. <i>c. Ap. 1, 1 ;</i><br><b>      2</b> dessein, plan, DS. <i>1, 3 et 28 ; 16, 32, etc. ;</i><br><b>      3</b> <i>t. de rhét</i>. développement d’une idée, RHÉT. <i>3, 271 W. ; 7, 2 et 1030 W. ; 8, 636 W. ;</i><br><b>      4</b> <i>t. de philos</i>. substance, <i>càd</i>. réalité, <i>p. opp. à</i> φάντασμα, ARSTT. <i>Mund. 4, 21, etc. ; ou à</i> φαντασία, ARTÉM. <i>3, 14 ; ou</i> fond d’une chose, <i>p. opp. à la forme,</i> LUC. <i>Par. 27 ;</i> SEXT. <i>M. 9, 338 ;</i> NT. <i>Hebr. 1, 3</i>.<br><span><b>Étym</b>. ὑφίστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποστασις - ὑπόστασις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G5288":"<h1>hupostello</h1>\n<p>Strong n° 5288 <i>Prononciation [hoop-os-tel'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>retirer, laisser tomber, baisser\n<ol type=\"a\">\n<li>se retirer : d'une personne timide</li>\n</ol>\n</li>\n<li>se cacher, c.à.d. être timide, couvrir, rétrécir\n<ol type=\"a\">\n<li>de ceux qui, par timidité, hésitent à avouer ce qu'ils croient</li>\n<li>être incapable de se prononcer, par crainte</li>\n<li>rétrécir une déclaration, cacher, dissimuler</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·στέλλω</b> <span>(<i>f</i>. ὑποστελῶ, <i>ao</i>. ὑπέστειλα, <i>pf</i>. ὑπέσταλκα)</span><br><b>   I <i>tr. :</i><br>      1</b> amener en dessous, tirer en bas : ἱστία, PD. <i>I. 2, 60,</i> amener <i>ou</i> carguer des voiles ;<br><b>      2</b> amener en arrière, ramener : στρατόν, PLUT. <i>Crass. 23, 26,</i> une armée ; ἑαυτὸν ὑπό τι, POL. <i>7, 17, 1,</i> se retirer sous un abri (un refuge, une place, <i>etc</i>.) ; ἑαυτόν τινι, PLUT. <i>Arat. 47,</i> se retirer derrière qqn ; <i>abs</i>. ὑπ. (<i>s.-e</i>. ἑαυτόν) POL. <i>6, 40, 14, etc</i>. se retirer ;<br><b>      3</b> resserrer, diminuer, restreindre, GRAMM. ; <i>p. suite,</i> excepter, DYSC. <i>Synt. p. 17, 1 ; au pass</i>. être excepté, GRAMM. <i>p. 490, 3 Bekker, Anecdota græca ;</i><br><b>   II <i>intr. :</i><br>      1</b> se retirer (<i>v. ci-dessus</i> I, 2) ;<br><b>      2</b> se contraindre, cacher ses sentiments par crainte <i>ou</i> par respect, PHILSTR. <i>V. soph. p. 536 ;</i> LUC. <i>Dem. enc. 44 ;</i><br><b>      3</b> se resserrer, se diminuer, se rapetisser, CALLIX. (ATH. <i>204</i> a) ;<br><b>      4</b> se soumettre, <i>au pf</i>. être soumis à, <i>dat</i>. SEXT. <i>p. 464 ;</i><br><b><i>Moy.</i></b> se retirer, reculer devant, éviter, <i>acc</i>. HPC. <i>Aph. 1249 ; V. med. 10 ;</i> ARSTT. <i>M. mor. 2, 9, 5 ;</i> τινος, ARSTT. <i>Probl. 1, 46 ; abs</i>. ARÉT. <i>Cur. m. acut. 1, 1,</i> se relâcher, se désister <i>ou</i> s’abstenir de qqe ch. ; <i>particul. :</i><br><b>      1</b> se retirer par crainte <i>ou</i> déférence : τινα, DIN. <i>91, 29,</i> devant qqn ; δύναμίν τινος, DÉM. reculer devant la puissance de qqn ; <i>abs</i>. montrer de la crainte, EL. <i>N.A. 7, 19, etc. ;</i><br><b>      2</b> refouler ses sentiments <i>ou</i> contenir sa parole par crainte <i>ou</i> par respect, EUR. <i>Or. 607 ;</i> DÉM. <i>14, 4 ; d’où</i> ὑποστέλλεσθαί τι, PLAT. <i>Ap. 24</i> a ; ISOCR. <i>134</i> c, <i>167</i> d, <i>196</i> b ; DÉM. <i>54, 30 ; 537, 7,</i> dissimuler <i>ou simpl</i>. taire qqe ch. ; ὑπ. τι πρός τινα, DIN. <i>109, 40,</i> se contraindre qqe peu par déférence <i>ou</i> par crainte devant qqn ; οὐδὲν ὑπ. πρός τινα, DÉM. <i>390, 10,</i> ne pas reculer par crainte devant qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποστελλω - ὑποστέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Galates (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5289":"<h1>hupostole</h1>\n<p>Strong n° 5289 <i>Prononciation [hoop-os-tol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la timidité de quelqu'un se retirant furtivement</li>\n<li>défection, lâcheté, désertion</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑποστολή, ῆς (ἡ)</b> resserrement, <i>d’où :</i><br><b>      1</b> diminution, PLUT. <i>M. 129</i> c, <i>475</i> f ; <i>particul</i>. diminution de nourriture, ORIB. <i>105 Cocch. ;</i><br><b>      2</b> <i>t. de gr</i>. suppression d’une lettre, DYSC. (<i>Bkk. p. 600</i>) ;<br><b>      3</b> <i>fig</i>. abattement, crainte, peur, pusillanimité, NT. <i>Hebr. 10, 39</i>.<br><span><b>Étym</b>. ὑποστέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποστολη - ὑποστολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5290":"<h1>hupostrepho</h1>\n<p>Strong n° 5290 <i>Prononciation [hoop-os-tref'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>retourner\n<ol type=\"a\">\n<li>s'en retourner</li>\n</ol>\n</li>\n<li>revenir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·στρέφω :<br>   I <i>tr. :</i><br>      1</b> faire tourner <i>ou</i> rouler sous, <i>d’où au pass</i>. rouler sous, être entraîné sous, <i>dat</i>. ARAT. <i>73 ; ou acc</i>. ARAT. <i>512 ;</i><br><b>      2</b> faire tourner en arrière, faire retourner : ἵππους, IL. <i>5, 581,</i> ramener des chevaux ; Βακχίαν ἅμιλλαν, SOPH. <i>Tr. 220,</i> ramener l’émulation bachique <i>càd</i>. la joie et le plaisir ; <i>au pass</i>. se retourner, revenir sur ses pas, IL. <i>11, 567 ;</i> HDT. <i>4, 129 ;</i> XÉN. <i>Hell. 5, 4, 5 ; fig</i>. τινος, SOPH. <i>O.R. 728,</i> faire un retour soudain sur qqe ch., s’aviser tout à coup de qqe ch. ;<br><b>   II <i>intr. :</i><br>      1</b> se retourner, revenir sur ses pas, IL. <i>12, 71 ;</i> HDT. <i>7, 211, etc. ;</i> THC. <i>3, 24 ;</i> XÉN. <i>Hell. 4, 5, 3, etc. ;</i> πάλιν, EUR. <i>Alc. 1019 ;</i> ANT. <i>119, 39 ; ou</i> τοὔμπαλιν, XÉN. <i>An. 6, 6, 38, m. sign. ;</i> φύγαδε αὖτις, IL. <i>11, 446,</i> se retourner pour prendre la fuite ; <i>fig</i>. revenir à des goûts <i>ou</i> à des sentiments d’autrefois, AR. <i>Av. 1283 ;</i><br><b>      2</b> revenir, <i>en parl. d’une maladie,</i> HPC. <i>Epid. 1, 941 ;</i><br><b>      3</b> retourner : Ὄλυμπον, IL. <i>3, 407,</i> dans l’Olympe ; ἐς τὴν Σκυθικήν, HDT. <i>4, 124,</i> en Scythie ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. ὑποστρέψομαι)</span> retourner, revenir, OD. <i>18, 23</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποστρεφω - ὑποστρέφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n35 fois dans 35 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (21)</li>\n<li>Actes (11)</li>\n<li>Galates (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G5291":"<h1>hupostronnumi</h1>\n<p>Strong n° 5291 <i>Prononciation [hoop-os-trone'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>joncher, étendre sous, étaler</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·στρωννύω</b> (<i>seul. prés. et impf.) c</i>. ὑποστρώννυμι PLUT. <i>Artax. 22 ;</i> ATH. <i>48</i> d.<br><br>\n<b>ὑπο·στρώννυμι</b> <span>(<i>f</i>. ὑποστρώσω, <i>ao</i>. ὑπέστρωσα, <i>pf</i>. ὑπέστρωκα, <i>pf. pass</i>. ὑπέστρωμαι)</span><br><b>      1</b> étendre (une peau, une couche, un tapis, <i>etc</i>.) sous, IL. <i>10, 155 ;</i> AMPHIS (ATH. <i>47</i> f) ; <i>particul. :</i> λέκτρα τινί, EUR. <i>Hel. 59,</i> étendre <i>ou</i> préparer un lit pour qqn, <i>càd</i>. être mariée ; <i>abs</i>. préparer un lit, PLUT. <i>Num. 10 ;</i><br><b>      2</b> joncher : ἅλω τινί, BABR. <i>34, 2,</i> une grange de qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποστρωννυμι - ὑποστρωννύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G5292":"<h1>hupotage</h1>\n<p>Strong n° 5292 <i>Prononciation [hoop-ot-ag-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un acte de soumission</li>\n<li>obéissance, soumission</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑποταγή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> subordination, soumission, DH. <i>3, 66 ;</i> NT. <i>2Cor. 9, 13, Gal. 2, 5 ;</i><br><b>      2</b> <i>t. de gr</i>. subjonctif, DYSC. <i>Synt. 301, etc</i>.<br><span><b>Étym</b>. ὑποτάσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποταγη - ὑποταγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G5293":"<h1>hupotasso</h1>\n<p>Strong n° 5293 <i>Prononciation [hoop-ot-as'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>disposer sous, subordonner</li>\n<li>soumettre, mettre en soumission</li>\n<li>se soumettre, obéir à</li>\n<li>se soumettre au contrôle de quelqu'un</li>\n<li>céder à un avertissement ou un conseil</li>\n<li>obéir, être soumis, assujetti</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·τάσσω</b>, <i>att</i>. <b>ὑπο·τάττω :<br>   I</b> ranger sous, <i>càd. :</i><br><b>      1</b> subordonner, ranger sous un chef, dans une classe : τινὰ ὑπό τι ὄνομα, POL. <i>17, 15, 4,</i> qqn sous une dénomination ; τινί τι, POL. <i>3, 36, 7 ;</i> PLUT. <i>Nic. 23, etc</i>. rattacher une ch. à une autre ;<br><b>      2</b> soumettre : ἑαυτόν τινι, PLUT. <i>Pomp. 64, Brut. 4, M. 142</i> d, se soumettre à qqn ; ἑαυτῷ τὰ πάντα, NT. <i>Phil. 3, 21,</i> soumettre tout à sa propre autorité ; πάντα ὑπὸ τοὺς πόδας, αὐτοῦ, NT. <i>Eph. 1, 22,</i> mettre tout à ses pieds ; <i>au pass</i>. être soumis à, <i>dat</i>. NT. <i>Col. 3, 18, etc. ;</i> οἱ ὑποτεταγμένοι, ceux qui sont soumis à une autorité, les sujets, <i>en gén</i>. POL. <i>3, 13, 8 ; 10, 22, 3 ;</i><br><b>   II</b> ranger derrière, EL. TACT. ; <i>au pass</i>. se ranger derrière, venir à la suite de, s’abriter derrière, <i>dat</i>. LUC. <i>Par. 49 ; abs</i>. PLUT. <i>M. 1020</i> a ;<br><b>   III</b> <i>t. de log</i>. prendre comme prémisse une mineure, ARR. <i>Epict. 4, 1, 61 ;</i><br><b>   IV</b> <i>t. de gr</i>. gouverner le subjonctif, EM. <i>471, 16 ;</i><br><b><i>Moy.</i></b> soumettre à son autorité, <i>dat</i>. HDN <i>2, 2, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy</i>. ὑποτάξομαι, <i>au sens pass</i>. HDN <i>2, 2, 20</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποτασσω - ὑποτάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n40 fois dans 32 versets de 10 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (9)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Tite (3)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (7)</li>\n</ul>\n</td></tr>\n</table>","G5294":"<h1>hupotithemi</h1>\n<p>Strong n° 5294 <i>Prononciation [hoop-ot-ith'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer sous, mettre sous, exposer</li>\n<li>métaph. fournir, suggérer (fournir d'après ses propres ressources)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·τίθημι</b> <span>(<i>f</i>. ὑποθήσω, <i>ao</i>. ὑπέθηκα, <i>etc</i>.)</span>. ;<br><b>   I. 1</b> placer sous : τί τινι, XÉN. <i>Hell. 4, 1, 13,</i> étendre qqe ch. sous les pieds de qqn ; τὰ ᾠὰ ἀλεκτορίδι, ARSTT. <i>H.A. 6, 9,</i> placer les œufs sous la poule ; τόξα μασχάλῃ, PLUT. <i>M. 967</i> d, placer son arc sous son bras ; τὰ ὀπίσθια σκέλη ὑπὸ τὰ ἐμπρόσθια, XÉN. <i>Eq. 11, 2,</i> placer les jambes de derrière sous celles de devant ; ὑπ. ἑαυτὸν φορτίῳ, LUC. <i>Char. 4,</i> se mettre sous le fardeau ; <i>avec</i> ὑπό <i>et l’acc</i>. τι ὑπὸ ὀφθαλμόν, ARSTT. <i>Probl. 3, 20,</i> approcher qqe ch. sous son œil ;<br><b>      2</b> placer au bas : ὑπ. πόλιν ὑπὸ ποταμούς, PLAT. <i>Leg. 682</i> c, bâtir une ville vers le bas au bord des fleuves ;<br><b>      3</b> livrer : τί τινι, PLAT. <i>Pol. 308</i> a, qqe ch. à qqn ;<br><b>      4</b> mettre à la place, substituer : τοὺς λόγους, EUR. <i>I.A</i>. un langage à un autre ;<br><b>   II.1</b> prendre pour base : ὑπ. ῥυθμοὺς καὶ σχῆμα, PLAT. <i>Leg. 669</i> c, prendre pour base les rythmes et les gestes (d’une mélodie), choisir comme base tels <i>ou</i> tels rythmes, <i>etc. ;</i> ὑπ. αἰτίαν τινί, PLUT. <i>M. 425</i> e, donner à qqe ch. une cause comme fondement, adopter une base pour qq. ch. ; ὑπ. τι τῇ γνώμῃ, DÉM. <i>552, 5,</i> donner qqe ch. pour fondement à sa pensée, prendre pour base d’un raisonnement une pensée ; <i>au pass</i>. ἀριθμὸν ἀνάγκη ὑποτίθεσθαι, PLAT. <i>Epin. 779</i> d, il est nécessaire que le nombre soit pris pour base, serve de base ; οἱ ὑποτεθέντες λόγοι, PLAT. <i>Leg. 812</i> a ; τὰ ὑποτεθέντα, PLAT. <i>Parm. 136</i> b, les propositions prises pour base, les principes ; ὑποτεθεὶς σκοπός, ARSTT. <i>Nic. 6, 12, 9,</i> but proposé ;<br><b>      2</b> tenir sous les yeux de qqn, <i>d’où</i> tenir devant, mettre à la disposition de, offrir : ὑπ. ἐλπίδα, faire naître l’espoir, THC. <i>1, 138 ;</i> XÉN. <i>Hell. 4, 8, 28, etc., ou</i> se flatter de l’espoir, se livrer à l’espoir, DÉM. <i>638, 24 ; avec un nom de pers. pour rég. :</i> ὑπ. ἑαυτὸν ἔγγυον, PLUT. <i>Crass. 7,</i> se livrer comme otage, fournir une caution ; ὑπ. τὴν ψυχὴν ταῖς τῆς πατρίδος τύχαις, LUC. <i>Dem. enc. 41,</i> offrir sa vie aux destins de la patrie ; ὑπ. ἑαυτὸν ὀργῇ, PLUT. <i>Them. 24 ;</i> ἀπεχθείαις, <i>Cato mi. 18,</i> s’exposer à la colère, aux inimitiés, <i>etc. ; en ce sens avec un rég. de chose :</i> ὑποθεῖναι τὸν ἴδιον κίνδυνον, DÉM. <i>420, 25,</i> risquer son propre danger, <i>càd</i>. faire qqe ch. à ses risques et périls ;<br><b>   III</b> mettre en gage, engager, <i>acc</i>. HDT. <i>2, 136 ;</i> ISOCR. <i>400</i> b, <i>etc. ;</i> τινί τι, ESCHN. <i>68, 25 ;</i> DÉM. <i>820, 23, etc</i>. donner qqe ch. en gage à qqn ; τι πρός τι, PLUT. <i>Arat. 19,</i> donner une chose en gage contre une autre<br><i><b>Moy</b>. :</i><br><b>   I</b> mettre sous soi, <i>acc</i>. XÉN. <i>Cyr. 8, 1, 41 ;</i><br><b>   II</b> se poser une base :<br><b>      1</b> <i>en gén</i>. établir comme fondement, prendre comme base : DÉM. <i>29, 5 ;</i> POL. <i>1, 5, 1,</i> qqe ch. ; ταύτην πυρὸς ἀρχὴν καὶ τῶν ἄλλων σωμάτων ὑποτιθέμεθα, PLAT. <i>Tim. 53</i> d, c’est ce que nous admettons comme la cause première du feu et des autres corps ; ὑπ. τό τε περιττὸν καὶ τὸ ἄρτιον καὶ τὰ σχήματα, PLAT. <i>Rsp. 510</i> c, adopter le pair et l’impair et les figures comme condition fondamentale, <i>càd</i>. les supposer ; ἕνα τοῦτον ὑποθέσθαι τὸν σκοπόν, <i>avec l’inf</i>. LUC. <i>Pisc. 7,</i> se proposer comme seul but de, <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> poser en principe, supposer, admettre : ὥσπερ ὑπέθου, PLAT. <i>Rsp. 346</i> b, ainsi que tu l’as posé en principe ; δώσω σοι ὑποτίθεσθαι, <i>etc</i>. PLAT. <i>Phædr. 236</i> b, je veux accorder cela en principe ; ὑπ. ὑπόθεσιν, PLAT. <i>Phæd. 101</i> d, <i>Parm. 136</i> a, <i>etc</i>. poser un principe, poser qq. ch. en principe ; ὑπ. (τὴν ἀρετὴν) διδακτὸν ὄν, PLAT. <i>Prot. 361</i> b, admettre en principe que la vertu peut s’enseigner ; ὑπ. τι ὡς ὄν, PLAT. <i>Parm. 136</i> c, admettre en principe une chose comme étant ; ὑπ. περί τινος ὡς <i>ou</i> οὕτως ἔχοντος, PLAT. <i>Rsp. 437</i> a, admettre en principe qu’il en est ainsi, supposer qu’il en est ainsi ; <i>avec une prop. inf. :</i> ὑπ. τὴν γεωργικὴν εὐμαθεστάτην εἶναι, XÉN. <i>Œc. 21, 1,</i> admettre que l’agriculture est très facile à apprendre ; <i>cf</i>. PLAT. <i>Soph. 237</i> a, <i>Phæd. 100</i> b, <i>etc. ;</i><br><b>      3</b> <i>p. suite,</i> se proposer : τι, AND. <i>1, 39 Baiter-Sauppe,</i> qqe ch. ; <i>avec l’inf. :</i> ἵππον ὠνεῖσθαι, XÉN. <i>Hipp. 3, 7,</i> se proposer d’acheter un cheval ; <i>avec l’inf. s.-e. :</i> περὶ ἧς ὑπεθέμην (<i>s.-e</i>. ποιεῖσθαι) ποιήσομαι τοὺς λόγους, ISOCR. <i>257</i> b, je parlerai de celle dont je m’étais proposé de parler ; <i>cf</i>. XÉN. <i>Cyr. 8, 8, 27 ;</i> ISOCR. <i>51</i> a, <i>etc. ;</i> PLUT. <i>M. 10</i> e, <i>etc. ;</i><br><b>      4</b> prendre pour sujet d’exposition, de narration, de discours, <i>etc. :</i> ἐντεῦθεν ὑποτιθέμενος ἠρξάμην, ISOCR. <i>29</i> c, voilà ce que je me suis proposé et d’où je suis parti ; λόγον ὑποθέσθαι Τρωϊκόν, PHILSTR. <i>692, 694,</i> choisir pour sujet (de son poème) la légende troyenne ; εἰ ὑποθοῖτό τις τῷ λόγῳ, <i>avec une prop. inf</i>. LUC. <i>M. cond. 7,</i> si qqn voulait admettre comme vrai pour traiter un sujet, <i>etc. ;</i><br><b>      5</b> s’imaginer, se représenter, se faire une idée : τι, LGN <i>14, 2,</i> de qqe chose ; <i>p. opp. à</i> αὐτὸς ξυγγεγονώς, PHILSTR. <i>702 ; particul</i>. tenir pour : τινα νεώτερον, DH. <i>4, 6,</i> tenir qqn pour plus jeune ;<br><b>      6</b> proposer, suggérer : βουλήν τινι, IL. <i>8, 36, 467,</i> donner un conseil à qqn ; ἔπος τινί, OD. <i>4, 163 ;</i> ἔργον τινί, IL. <i>11, 788,</i> donner à qqn l’idée d’un discours, d’une action, les lui conseiller ; <i>cf</i>. OD. <i>3, 27 ;</i> HH. <i>Cer. 149 ;</i> HÉS. <i>Th. 175 ;</i> HDT. <i>1, 156, etc. ;</i> ὑπ. τινι, OD. <i>2, 194 ; 5, 143 ;</i> PLAT. <i>Charm. 155</i> d, conseiller qqn ; ὑπ. πυκινῶς τινι, IL. <i>21, 293 ;</i> OD. <i>1, 279,</i> conseiller qqn sagement ; ἀλλά μοι εὖ ὑπόθευ, OD. <i>15, 310 ;</i> HDT. <i>1, 90,</i> allons ! conseille-moi bien ! σοὶ δ' οὐ κακῶς ὑποθήσομαι, AR. <i>Av. 1362,</i> LYS. <i>522,</i> je ne te conseillerai pas mal ; <i>avec l’inf</i>. conseiller de, THC. <i>5, 90 ;</i> PLUT. <i>Rom. 1, etc. ;</i><br><b>      7</b> enseigner, apprendre : τι, PLAT. <i>Pol. 295</i> d, <i>Tim. 26</i> a, <i>etc. ;</i> PLUT. <i>M. 795</i> b, qqe ch. ; τί τινι, PLAT. <i>Hipp. ma. 286</i> b, qqe ch. à qqn ; ὑπ. περί τινος, APD. <i>1, 9, 22,</i> instruire au sujet de qqe ch. ; <i>avec une prop. relat. :</i> ὑπ. δι' ὧν, <i>etc. ;</i> ISOCR. <i>46 ;</i> ὡς, <i>etc. ;</i> PHILSTR. <i>712,</i> montrer par quels, <i>etc</i>. que, <i>etc. ;</i><br><b>   III</b> <i>t. de droit,</i> prendre pour gage : τὰ σκεύη τῆς νεώς, DÉM. <i>1223, 24,</i> les agrès du navire ; οἱ ὑποτιθέμενοι, DÉM. <i>841, 20,</i> ceux qui ont hypothèque sur un bien, les créanciers hypothécaires.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 moy. impér. 2 sg. épq</i>. ὑπόθευ.<br><span><b>Étym</b>. <i>v. ci-dessus</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποτιθημι - ὑποτίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5295":"<h1>hupotrecho</h1>\n<p>Strong n° 5295 <i>Prononciation [hoop-ot-rekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>passer au-dessous\n<ol type=\"a\">\n<li>de navigateurs\n<ol>\n<li>passer sous un lieu de la côte, et donc qui est placé plus haut</li>\n<li>passer sous le vent de</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·τρέχω</b> <span>(<i>f</i>. ὑποθρέξομαι <i>ou</i> ὑποδραμοῦμαι, <i>ao.2</i> ὑπέδραμον, <i>pf</i>. ὑποδέδρομα <i>et</i> ὑποδεδρόμηκα)</span><br><b>   I</b> courir sous : ἡ σελήνη τὸν ἥλιον ὑποτρέχει, THÉM. la lune passe (<i>litt</i>. décrit sa course) sous le soleil ; <i>particul. avec idée d’abri ou de protection :</i> ταῖς πλατάνοις ὑποτρέχειν, PLUT. <i>M. 185</i> e, courir se réfugier sous les platanes ; ὑπέδραμε καὶ λάϐε γούνων, IL. <i>21, 68 ;</i> OD. <i>10, 323,</i> il courut se jeter à ses pieds et prit ses genoux ; ὑπ. τινά, EUR. <i>I.A. 630,</i> courir avant qqn, prendre les devants ; <i>p. anal. ou fig. :</i><br><b>      1</b> s’étendre sous : ὑποδέδρομε βῆσσα, HH. <i>Ap. 284,</i> une vallée court au-dessous ;<br><b>      2</b> se glisser sous, pénétrer dans, <i>avec un suj. de chose :</i> ὑπ. τις ἔννοιά τινι, POL. <i>16, 6, 10,</i> il vient une pensée à l’esprit de qqn ; ἀπελπισμὸς ὑποτρέχει τινί, POL. <i>31, 8, 11,</i> le désespoir envahit l’âme de qqn ; ἔλεος αὐτὸν <i>ou</i> αὐτῷ ὑποτρέχει, POL. <i>9, 10, 7,</i> la pitié entre dans son âme ; ἄν σ' ὑποτρέχῃ, ARR. <i>Epict. 4, 2, 2,</i> s’il te vient à l’esprit de, <i>etc. ;</i> οὐχ ὑπέδραμε, STR. <i>554,</i> il ne (me) vint pas à l’esprit de, <i>etc. ; avec une prop. inf</i>. POL. <i>14, 12, 5, etc. ; en mauv. part,</i> s’insinuer auprès de : τινά, EUR. <i>Or. 669 ;</i> ESCHN. <i>76, 40 ;</i> PLUT. <i>Æmil. 2, etc</i>. auprès de qqn, chercher à capter qqn ; <i>abs</i>. PLAT. <i>Rsp. 426</i> b, <i>Leg. 923</i> c ;<br><b>   II</b> courir après, à la suite de : λῃστάς, XÉN. <i>Cyr. 1, 2, 12,</i> courir après des brigands ; <i>fig. :</i> δόξαν, SEXT. <i>M. 9, 38,</i> courir après la renommée ;<br><b>   III</b> courir à la traverse, <i>d’où</i> interrompre, DIUS (STOB. <i>Fl. 65, 17</i>) ;<br><b>   IV</b> courir près de, le long de, <i>d’où abs. au part</i>. ὑποδραμών, en passant, AR. <i>Eq. 676 ;</i> ὑποδραμὼν ὑποδείξω, DIOSC. j’indiquerai en passant, <i>sel. d’autres,</i> j’indiquerai sommairement.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. ὑποδέδρομα, HH. <i>l. c. ; pf. dor. 3 sg</i>. ὑποδεδρόμακε <span>[ᾱ]</span> SAPPH. <i>2, 10</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποτρεχω - ὑποτρέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G5296":"<h1>hupotuposis</h1>\n<p>Strong n° 5296 <i>Prononciation [hoop-ot-oop'-o-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un contour, un aperçu, exposition brève et sommaire</li>\n<li>un exemple, un modèle\n<ol type=\"a\">\n<li>pour un exemple de ceux qui veulent dorénavant croire</li>\n<li>montrer par l'exemple de ma conversation que la même grâce qui m'a été donnée peut être obtenue aussi de ceux qui voudront croire désormais</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑποτύπωσις, εως (ἡ)</b> <span>[τῠ]</span><br><b>      1</b> esquisse, ébauche, <i>fig</i>. exposition sommaire, définition générale, SEXT. <i>P. 1, 1 ;</i> DL. <i>9, 78 ;</i> GAL. <i>19, 11 ;</i><br><b>      2</b> modèle, exemple, NT. <i>1Tim. 1, 16 ; 2, 1, 13 ;</i><br><b>      3</b> hypotypose, <i>fig. t. de rhét. qui consiste à rendre en qqe sorte vivants les personnages ou les faits dont on parle,</i> QUINT. <i>9, 2, 40</i>.<br><span><b>Étym</b>. ὑποτυπόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποτυπωσις - ὑποτύπωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G5297":"<h1>hupophero</h1>\n<p>Strong n° 5297 <i>Prononciation [hoop-of-er'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter en étant au-dessous, supporter (une chose placée sur les épaules)</li>\n<li>supporter patiemment, endurer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·φέρω</b> <span>(<i>f</i>. ὑποίσω, <i>ao</i>. ὑπήνεγκα, <i>ao.2</i> ὑπήνεγκον, <i>pf</i>. ὑπενήνοχα, <i>etc</i>.)</span><br><b>   I</b> être dessous et transporter : πόδες μ' ὑπήνεικαν (<i>p</i>. ὑπήνεγκαν) IL. <i>5, 885,</i> mes pieds m’arrachèrent au danger ; <i>en parl. du courant d’un fleuve :</i> ναῦν, PLUT. <i>Cæs. 38 ;</i> LGS <i>2, 14,</i> porter un navire ; <i>au pass</i>. ὑποφέρεσθαι τῷ ποταμῷ, PLUT. <i>Alex. 63, ou</i> ἐν ποταμῷ, LUC. <i>Nec. 9,</i> descendre un fleuve en bateau ; <i>fig. :</i> ὁ λόγος ὥσπερ ῥεῦμα φέρων ὑπήνεγκε βίᾳ ARSTD. <i>t. 1, 214,</i> le discours les soulevant comme le courant d’un fleuve les entraîna ; <i>au pass</i>. ἐὰν τὸ ὑποκείμενον ὑποφέρηται, ARSTT. <i>Inc. an. 3, 2,</i> si la base est retirée ; <i>fig. :</i> ὑποφέρεσθαι εἴς τι, PLUT. <i>Cor. 15, Alc. 18, ou</i> πρός τι, PLUT. <i>Alex. 23, etc</i>. se laisser emporter à qqe excès ;<br><b>   II</b> être dessous et porter, <i>d’où :</i><br><b>      1</b> <i>au propre :</i> ὑπ. ὅπλα, XÉN. <i>Cyr. 4, 5, 57,</i> porter des armes ; <i>cf</i>. PLUT. <i>Syll. 7 ; d’où</i> supporter, soutenir : σῶμα, TH. <i>H.P. 9, 14, 4,</i> avoir la force de soutenir son corps ;<br><b>      2</b> <i>fig</i>. supporter : τὰς τῆς τύχης μεταϐολάς, XÉN. <i>Cyr. 6, 2, 29,</i> les changements de la fortune ; κινδύνους, XÉN. <i>Hipp. 1, 3, etc</i>. des dangers ; πόνους καὶ κινδύνους, ISOCR. <i>40</i> a, des fatigues et des dangers ;<br><b>      3</b> porter au-dessus de soi, mettre en avant, prétexter, <i>acc</i>. XÉN. <i>Hell. 4, 7, 2 ;</i><br><b>   III</b> porter de dessous, <i>d’où :</i><br><b>      1</b> lever, élever : δᾷδα, PLUT. <i>Popl. 23,</i> un flambeau ; <i>fig</i>. faire naître, exciter : ἐλπίδα, SOPH. <i>El. 834,</i> une espérance ; ἔγκλημά τινι, HDN <i>2, 5, 12,</i> porter une accusation contre qqn ;<br><b>      2</b> proposer : σπονδάς, XÉN. <i>Hell. 4, 7, 2,</i> un traité ;<br><b>   IV</b> porter en dessous, <i>d’où :</i><br><b>      1</b> porter sous soi, avancer sous soi : τὰ ὀπίσθια σκέλη, ARSTT. <i>H.A. 8, 24, 2,</i> les jambes de derrière ;<br><b>      2</b> porter sens dessus dessous, <i>d’où</i> déplacer (l’époque d’une fête) PLUT. <i>Cæs. 59 ;</i><br><b>      3</b> faire chanceler, faire tomber : χωρία ὑποφέροντα, POLL. <i>1, 187,</i> terrains où l’on tombe, où l’on enfonce ; <i>au pass</i>. être précipité : κατὰ κρημνῶν, PLUT. <i>Mar. 23,</i> de hauteurs à pic ; <i>fig</i>. ἐς πενίαν, APP. <i>Civ. 2, 2,</i> dans la pauvreté ; <i>abs</i>. πόλις ὑποφερομένη, PLUT. <i>Per. c. Fab. 1,</i> ville <i>ou</i> État en décadence ; <i>p. anal. en parl. de malades,</i> décliner de plus en plus, HPC. <i>1111</i> g, <i>etc. ; au sens mor</i>. se laisser abattre, se décourager, PLUT. <i>Sert. 4, M. 72</i> c ; <i>ou</i> s’humilier, s’abaisser, PLUT. <i>Lyc. 2 ;</i><br><b>   V</b> porter sous, exposer à, opposer à : τὰ σεσιδηρωμένα μέρη ταῖς πληγαῖς, PLUT. <i>Cam. 41,</i> opposer aux coups les parties garnies de fer ;<br><b>   VI</b> porter derrière :<br><b>      1</b> <i>au propre :</i> τινὶ δίφρους, EL. <i>V.H. 4, 22,</i> suivre qqn en portant des sièges ; <i>au pass</i>. se porter derrière, reculer : θᾶττον ἢ ὥστ' ἔχειν ἀπερείσασθαι, ARSTT. <i>Inc. an. 3,</i> trop vite et avant d’avoir où appuyer le pied ;<br><b>      2</b> <i>fig</i>. porter ensuite, <i>d’où</i> faire suivre, ajouter (à ce qu’on a dit) DH. <i>7, 16 ;</i> LGN <i>16, 4 ;</i><br><b>   VII</b> porter peu à peu : εἰς διόρθωσιν, PLUT. <i>Lyc. 25,</i> amener insensiblement à correction.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.1 ion. et épq. 3 pl</i>. ὑπήνεικαν, IL. <i>5, 885</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποφερω - ὑποφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G5298":"<h1>hupochoreo</h1>\n<p>Strong n° 5298 <i>Prononciation [hoop-okh-o-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'en aller</li>\n<li>se retirer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπο·χωρέω-ῶ</b> <span>(<i>ao</i>. ὑπεχώρησα)</span> <i>litt</i>. céder la place (pour se retirer <i>ou</i> pour s’avancer) :<br><b>   I</b> (se retirer) :<br><b>      1</b> s’éloigner, se retirer, <i>abs</i>. IL. <i>6, 107 ; 22, 96 ;</i> XÉN. <i>Cyr. 6, 4, 3 ; en parl. d’animaux,</i> ARSTT. <i>H.A. 6, 14 ; 8, 2 ; de la mer,</i> PHILSTR. <i>V. Ap. 4, 34 ;</i> τῆς χώρης, HDT. <i>1, 207,</i> quitter le pays ; <i>au part. joint à un verbe :</i> ὑποχωρῶν ᾤχετο, IS. <i>49, 25, litt</i>. il allait se retirant ; ὑποχωρήσας φεύγει, DÉM. <i>613 fin</i>, il s’est retiré et fuit ; <i>avec le dat. ou l’acc. de l’objet devant lequel on se retire :</i> τινι, THC. <i>1, 77 ;</i> XÉN. <i>An. 1, 4, 18 ; fig</i>. DÉM. <i>272, 10,</i> devant qqn <i>ou</i> qqe ch. ; <i>fig</i>. PLAT. <i>Rsp. 560</i> a ; <i>avec un acc</i>. ὄχλον νεῶν, THC. <i>2, 88,</i> devant une multitude de vaisseaux ; <i>avec deux rég. :</i> τινι τοῦ θρόνου, AR. <i>Ran. 790,</i> céder le siège à qqn ; τῇ πόλει ἐκ γῆς καὶ θαλάσσης, ARSTD. céder à l’État la possession de la terre et de la mer ;<br><b>      2</b> <i>t. de méd</i>. sortir par le bas, ARSTT. <i>H.A. 8, 2 ; Probl. 4, 30 ;</i> ὑποχωρεῖ αὐτῷ πάμπολλα, EL. <i>N.A. 3, 3,</i> il a d’abondantes évacuations ; <i>p. ext. en parl. de l’évacuation des humeurs,</i> des selles, <i>etc</i>. HPC. <i>Aph. 1250, etc. ;</i><br><b>   II</b> (avancer) avancer peu à peu, PD. <i>P. 4, 360 ;</i> XÉN. <i>An. 4, 5, 20 ;</i> DH. <i>9, 63 dout</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υποχωρεω - ὑποχωρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G5299":"<h1>hupopiazo</h1>\n<p>Strong n° 5299 <i>Prononciation [hoop-o-pee-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>battre « noir et bleu », frapper comme pour causer meurtrissures et marques blêmes\n<ol type=\"a\">\n<li>comme un boxeur qui entraîne son corps, le traite rudement, et le discipline par privation</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>donner à quelqu'un d'intolérables contrariétés\n<ol>\n<li>battre quelqu'un</li>\n</ol>\n</li>\n<li>par des instances</li>\n</ol>\n</li>\n<li>la partie du visage qui est sous les yeux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ὑπ·ωπιάζω :<br>   I</b> frapper sous les yeux, <i>vulg</i>. pocher les yeux ; <i>au pass</i>. AR. <i>Pax 541 ;</i> ARSTT. <i>Rhet. 3, 11, 15 ;</i> DL. <i>6, 89 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> <i>fig</i>. blesser, mortifier, NT. <i>1Cor. 9, 27 ;</i><br><b>      2</b> molester, NT. <i>Luc. 18, 5 ;</i> PLUT. <i>M. 921</i> f ; LUC. <i>Nec. 5</i>.<br><span><b>Étym</b>. ὑπώπιον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">υπωπιαζω - ὑπωπιάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>"};
